            const salesCount = Math.max(salesInChats, confirmedOrders);
            const lostCount = visibleChats.filter((chat) => lostOrderStatuses.has(authoritativePanelStatusForChat(chat))).length;
            const conversionRate = visibleChats.length ? Math.round((salesCount / visibleChats.length) * 100) : 0;
            const reviewCount = Number.isFinite(state.dropiOrderStats?.authorization)
                ? state.dropiOrderStats.authorization
                : confirmedOrders;
            const totalClients = Number(
                state.dashboardMetrics?.commercialTotalClients
                ?? state.dashboardMetrics?.totalClients
                ?? 0
            ) || visibleChats.length;

            el('metricChats').textContent = String(visibleChats.length);
            el('metricManual').textContent = String(manualCount);
            el('metricMine').textContent = String(mineCount);
            el('metricClosed').textContent = String(closedCount);
            el('metricConfirming').textContent = String(reviewCount);
            el('careMetricEntered').textContent = String(totalClients);
            el('careMetricHuman').textContent = String(salesCount);
            el('careMetricClosed').textContent = String(lostCount);
            el('careMetricReview').textContent = `${conversionRate}%`;
            el('careMetricEntered')?.closest('.care-metric')?.setAttribute('title', `${totalClients} cliente(s) EC no banco operacional; ${visibleChats.length} conversa(s) visiveis no painel`);
            el('careMetricHuman')?.closest('.care-metric')?.setAttribute('title', `${salesCount} venda(s): confirmado, enviado, entregue, recompra ou finalizado`);
            el('careMetricClosed')?.closest('.care-metric')?.setAttribute('title', `${lostCount} desistente(s): comprar depois, cancelado ou devolvido`);
            el('careMetricReview')?.closest('.care-metric')?.setAttribute('title', `Conversao atual: ${salesCount}/${visibleChats.length || 0}`);
            const unreadTotal = visibleChats.reduce((total, chat) => total + Math.max(0, Number(chat.unreadCount || 0)), 0);
            const commercialNewChats = visibleChats.filter(isNewMessagesChatForPanel);
            const unreadChats = commercialNewChats.filter((chat) => Number(chat.unreadCount || 0) > 0).length;
            const vslWaitingChats = commercialNewChats.filter(isVslAwaitingHuman).length;
            const newUnreadChats = commercialNewChats.length;
            if (el('chatTotalCounterValue')) el('chatTotalCounterValue').textContent = String(visibleChats.length);
            if (el('chatUnreadCounterValue')) el('chatUnreadCounterValue').textContent = unreadTotal > 99 ? '99+' : String(unreadTotal);
            el('chatTotalCounter')?.classList.toggle('has-unread', unreadTotal > 0);
            el('chatTotalCounter')?.setAttribute('title', `${visibleChats.length} conversa${visibleChats.length === 1 ? '' : 's'} visiveis${unreadTotal ? ` | ${unreadTotal} nao lida${unreadTotal === 1 ? '' : 's'}` : ''}`);
            el('markVisibleReadBtn')?.classList.toggle('has-unread', unreadChats > 0);
            el('markVisibleReadBtn')?.setAttribute('title', unreadChats > 0
                ? `Marcar como lidas ${unreadTotal} mensagen${unreadTotal === 1 ? 'm' : 's'} antiga${unreadTotal === 1 ? '' : 's'} em ${unreadChats} conversa${unreadChats === 1 ? '' : 's'}, sem apagar o historico`
                : 'Nao ha mensagens antigas para marcar como lidas');
            if (el('chatUnreadTabCount')) el('chatUnreadTabCount').textContent = newUnreadChats > 99 ? '99+' : String(newUnreadChats);
            el('newMessagesFilterBtn')?.classList.toggle('has-unread', newUnreadChats > 0);
            el('newMessagesFilterBtn')?.setAttribute('title', newUnreadChats
                ? `${newUnreadChats} conversa${newUnreadChats === 1 ? '' : 's'} nova${newUnreadChats === 1 ? '' : 's'} (${unreadChats} com mensagem nao lida e ${vslWaitingChats} entrada${vslWaitingChats === 1 ? '' : 's'} da VSL aguardando atendimento)`
                : 'Nenhuma mensagem nova');
            el('readMessagesFilterBtn')?.setAttribute('title', unreadChats > 0
                ? `Marcar ${unreadTotal} mensagen${unreadTotal === 1 ? 'm' : 's'} como lida${unreadTotal === 1 ? '' : 's'} e limpar Novas`
                : 'Nenhuma mensagem nova para marcar como lida');
        };

        const renderDashboardMetrics = () => {
            const metrics = state.dashboardMetrics || {};
            const today = metrics.today || {};
            const week = metrics.week || {};
            const month = metrics.month || {};
            el('statEnteredToday').textContent = String(today.totalEntries ?? today.entered ?? 0);
            el('statActiveToday').textContent = String(today.active || 0);
            el('statManualNow').textContent = String(metrics.commercialManualNow ?? metrics.manualNow ?? 0);
            el('statClosedToday').textContent = String(today.closed || 0);
            el('statEnteredWeek').textContent = String(week.totalEntries ?? week.entered ?? 0);
            el('statSalesWeek').textContent = moneyShort(week.revenue || 0);
            el('statEnteredMonth').textContent = String(month.totalEntries ?? month.entered ?? 0);
            el('statSalesMonth').textContent = moneyShort(month.revenue || 0);
        };

        async function loadDashboardMetrics() {
            if (!state.token) return;
            const now = Date.now();
            if (state.dashboardLastLoadedAt && now - state.dashboardLastLoadedAt < 25000) return;
            state.dashboardLastLoadedAt = now;
            const country = selectedPanelCountry();
            state.dashboardMetrics = await api(`/api/whatsapp/dashboard-metrics?country=${encodeURIComponent(country || 'EC')}`);
            renderDashboardMetrics();
        }

        const isMine = (chat) => {
            if (!state.user || chat.human?.mode !== 'manual') return false;
            const assignedTo = String(chat.human?.assignedTo || '');
            const assignedName = String(chat.human?.assignedName || '');
            return assignedTo === String(state.user.id || state.user._id || '')
                || assignedName === String(state.user.name || state.user.email || '');
        };

        const chatTags = (chat) => Array.isArray(chat.tags) ? chat.tags.filter(Boolean) : [];
        const shipmentStatusFromChat = (chat) => {
            const shipment = chat?.shipment || {};
            const status = String(shipment.status || '').toUpperCase();
            if (['RETURNED', 'DEVUELTO'].includes(status)) return 'devolvido';
            if (['DELIVERED', 'ENTREGADO'].includes(status) || shipment.bonusNotifiedAt) return 'entregue';
            if (
                shipment.trackingNumber
                || shipment.guiaNotifiedAt
                || shipment.readyForPickupNotifiedAt
                || ['GUIDE_CREATED', 'PICKED_UP_BY_CARRIER', 'IN_TRANSIT', 'LOGISTICS_CENTER', 'ENTERING_AGENCY', 'READY_FOR_PICKUP', 'NOT_PICKED_UP', 'RETURNING', 'EXCEPTION'].includes(status)
            ) return 'pedido_enviado';
            return '';
        };
        const statusFromChatTags = (chat) => {
            const tags = chatTags(chat);
            if (tags.includes('manual:fechado')) return 'entregue';
            if (tags.includes('manual:pedido_confirmado')) return 'confirmado';
            if (tags.includes('manual:enviado_dropi')) return 'pedido_enviado';
            if (tags.includes('manual:resolvido')) return 'entregue';
            if (tags.includes('manual:atendimento_iniciado') || tags.includes('manual:humano_no_comando')) return 'atendendo';
            return '';
        };
        const chatDisplayStatus = (chat) => orderStatusInfo(
            authoritativePanelStatusForChat(chat)
            || statusFromChatTags(chat)
            || (chat.human?.mode === 'manual' ? 'atendendo' : 'novo')
        );
        const isFavoriteChat = (chat) => chatTags(chat).some((tag) => /favorit|favorite|star/i.test(String(tag)));
        const shipmentPanelStatusLabel = (chat) => {
            const shipment = chat?.shipment || {};
            const status = String(shipment.status || '').toUpperCase();
            const trackingNumber = String(shipment.trackingNumber || '').trim();
            if (status === 'READY_FOR_PICKUP' && shipment.canPickup === true && shipment.pickupReadyVerified === true) {
                return { label: shipment.panelLabel || 'Disponível para retirada', className: 'notice ok' };
            }
            if (status === 'DELIVERED') return { label: shipment.panelLabel || 'Entregue', className: 'notice ok' };
            if (status === 'RETURNED') return { label: shipment.panelLabel || 'Devolvido', className: 'notice warn' };
            if (['NOT_PICKED_UP', 'RETURNING', 'EXCEPTION', 'UNKNOWN'].includes(status)) {
                return { label: shipment.panelLabel || 'Revisão logística', className: 'notice warn' };
            }
            if (['PICKED_UP_BY_CARRIER', 'IN_TRANSIT', 'LOGISTICS_CENTER', 'ENTERING_AGENCY'].includes(status)) {
                return { label: shipment.panelLabel || 'Em trânsito · ainda não retirar', className: 'notice ok' };
            }
            if (status === 'GUIDE_CREATED' || trackingNumber) return { label: shipment.panelLabel || 'Guia gerada · ainda não retirar', className: 'notice ok' };
            return null;
        };
        const visibleShipmentNoticeLabel = (chat) => {
            const stage = chat?.shipmentNoticeStage || {};
            const label = String(stage.label || '').trim();
            const fallback = label ? null : shipmentPanelStatusLabel(chat);
            if (!label && !fallback) return null;
            const shipment = chat?.shipment || {};
            const visibleLabel = label || fallback.label;
            return {
                label: visibleLabel,
                className: fallback?.className || 'notice ok',
                title: [
                    stage.orderId || shipment.orderId ? `Pedido ${stage.orderId || shipment.orderId}` : '',
                    stage.status || shipment.status || '',
                    stage.trackingNumber || shipment.trackingNumber ? `guia ${stage.trackingNumber || shipment.trackingNumber}` : '',
                    stage.sentAt ? formatTime(stage.sentAt) : ''
                ].filter(Boolean).join(' | ')
            };
        };
        const visibleShipmentNoticeLabels = (chat) => {
            const stages = Array.isArray(chat?.shipmentNoticeStages) ? chat.shipmentNoticeStages : [];
            const shipment = chat?.shipment || {};
            const labels = stages.map((stage) => {
                const label = String(stage?.label || '').trim();
                if (!label) return null;
                return {
                    label,
                    className: String(stage?.code || '').includes('returned') ? 'notice warn' : 'notice ok',
                    title: [
                        stage.orderId || shipment.orderId ? `Pedido ${stage.orderId || shipment.orderId}` : '',
                        stage.status || shipment.status || '',
                        stage.trackingNumber || shipment.trackingNumber ? `guia ${stage.trackingNumber || shipment.trackingNumber}` : '',
                        stage.sentAt ? formatTime(stage.sentAt) : ''
                    ].filter(Boolean).join(' | ')
                };
            }).filter(Boolean);
            if (labels.length) return labels;
            const fallback = visibleShipmentNoticeLabel(chat);
            return fallback ? [fallback] : [];
        };
        const hasVisibleLabels = (chat) => chatTags(chat).length > 0 || visibleShipmentNoticeLabels(chat).length > 0;
        const tagLabel = (tag = '') => {
            const value = String(tag || '');
            const labels = {
                'manual:atendimento_iniciado': 'Atendimento iniciado',
                'manual:humano_no_comando': 'Humano no comando',
                'manual:bot_liberado': 'Bot liberado',
                'manual:bot_pausado': 'Bot pausado',
                'manual:fechado': 'Fechado humano',
                'manual:repetidas_limpas': 'Mensagens limpas',
                'manual:dados_pedidos': 'Dados pedidos',
                'manual:dados_recebidos': 'Dados recebidos',
                'manual:audio_enviado': 'Áudio enviado',
                'manual:prova_enviada': 'Prova enviada',
                'manual:preco_enviado': 'Preço enviado',
                'manual:aguardando_cliente': 'Aguardando cliente',
                'manual:pedido_confirmado': 'Pedido confirmado',
                'manual:enviado_dropi': 'Enviado Dropi',
                'manual:guia_enviada': 'Guia enviada',
                'manual:resolvido': 'Resolvido',
                'manual:revisar': 'Revisar',
                'manual:aquecimento_liberado': 'AQUECE',
                'manual:aquecimento_vip': 'AQUECE VIP',
                'manual:aquecimento_removido': 'NAO AQUECE',
                'manual:aquecimento_risco_manual': 'RISCO',
                'warmup:allowed': 'AQUECE',
                'warmup:vip': 'AQUECE VIP',
                'warmup:blocked': 'NAO AQUECE',
                'warmup:risk': 'RISCO',
                'warmup:manual_only': 'MANUAL',
                'manual:bot_insistence_error': '[ALERT: Robot was too aggressive. Human intervention required]'
            };
            return labels[value] || value.replace(/^manual:/, '').replace(/^auto:/, '').replace(/_/g, ' ');
        };
        const renderChatLabels = (chat) => {
            const orderedTags = chatTags(chat).sort((a, b) => {
                const aWarmup = String(a || '').startsWith('warmup:') || String(a || '').includes('aquecimento');
                const bWarmup = String(b || '').startsWith('warmup:') || String(b || '').includes('aquecimento');
                return Number(bWarmup) - Number(aWarmup);
            });
            const tags = orderedTags.slice(0, 4).map((tag) => {
                const value = String(tag || '');
                const className = value.includes('bot_insistence_error')
                    ? 'alert'
                    : (value.startsWith('warmup:') || value.includes('aquecimento') ? 'warmup' : (value.startsWith('manual:') ? 'manual' : 'auto'));
                return { label: tagLabel(tag), className, title: '' };
            });
            const notices = visibleShipmentNoticeLabels(chat);
            const combinedLabels = [...tags, ...notices];
            const labels = window.VitalismenEngagementPanelV42?.dedupeVisibleLabels?.(combinedLabels)
                || combinedLabels.filter((item, index, list) => list.findIndex((candidate) => (
                    String(candidate?.label || '').trim().toLowerCase() === String(item?.label || '').trim().toLowerCase()
                    && String(candidate?.className || 'auto') === String(item?.className || 'auto')
                )) === index);
            if (!labels.length) return '';
            return `<div class="chat-labels">${labels.map((item) => (
                `<span class="wa-label ${escapeHtml(item.className || 'auto')}"${item.title ? ` title="${escapeHtml(item.title)}"` : ''}>${escapeHtml(item.label)}</span>`
            )).join('')}</div>`;
        };

        const vslEntryPhraseForPanel = (chat = {}) => {
            const draft = chat?.customerDraft || {};
            const phrase = String(draft.vslEntryMessage || '').trim();
            if (!phrase) return '';
            const rawVariant = String(draft.vslVariant || '').trim().toUpperCase();
            const variant = ['A', 'B'].includes(rawVariant) ? `VSL ${rawVariant}` : 'VSL';
            return `<div class="chat-vsl-entry" title="Frase inicial enviada pelo botão ${escapeHtml(variant)}">
                <strong>${escapeHtml(variant)}</strong>
                <span class="truncate">${escapeHtml(phrase)}</span>
            </div>`;
        };

        const renderTeamList = () => {
            const operationalChats = visibleOperationalChats();
            const commercialChats = window.VitalismenPanelWarmupIsolationV118?.commercialChats?.(
                operationalChats,
                chatConversationBucket
            ) || operationalChats.filter((chat) => chatConversationBucket(chat) !== 'engagement');
            const active = commercialChats.filter((chat) => chat.human?.mode === 'manual');
            const byOwner = active.reduce((acc, chat) => {
                const owner = chat.human?.assignedName || 'Atendente';
                acc[owner] = (acc[owner] || 0) + 1;
                return acc;
            }, {});
            const rows = Object.entries(byOwner).sort((a, b) => b[1] - a[1]);
            el('teamList').innerHTML = rows.map(([owner, count]) => `
                <div class="team-row">
                    <strong>${escapeHtml(owner)}</strong>
                    <span class="badge orange">${count} cliente${count > 1 ? 's' : ''}</span>
                </div>
            `).join('') || '<div class="empty">Nenhum atendimento humano agora.</div>';
        };

        const renderChats = () => {
            const search = el('chatSearch').value.trim().toLowerCase();
            const searchActive = window.VitalismenChatSearchV41?.isSearchActive(search) ?? Boolean(search);
            const applyOperationalBucketFilter = window.VitalismenGlobalNewMessagesV44?.shouldApplyOperationalBucketFilter?.({
                searchActive,
                chatFilter: state.chatFilter,
                conversationBucketFilter: state.conversationBucketFilter
            }) ?? (
                !searchActive
                && state.chatFilter !== 'unread'
                && Boolean(state.conversationBucketFilter)
            );
            const filtered = visibleOperationalChats({ search }).filter((chat) => {
                const warmupIsolationDecision = searchActive
                    ? undefined
                    : window.VitalismenPanelWarmupIsolationV118?.isChatVisibleInOperationalView?.({
                        chat,
                        conversationBucketFilter: state.conversationBucketFilter,
                        chatFilter: state.chatFilter,
                        resolveConversationBucket: chatConversationBucket
                    });
                if (!searchActive && warmupIsolationDecision === false) return false;
                // Search can cross commercial queues, but never the engagement boundary.
                if (searchActive && chatConversationBucket(chat) === 'engagement'
                    && (state.conversationBucketFilter !== 'engagement' || state.chatFilter === 'unread')) return false;
                if (searchActive && state.conversationBucketFilter === 'engagement' && state.chatFilter !== 'unread'
                    && chatConversationBucket(chat) !== 'engagement') return false;
                if (warmupIsolationDecision === undefined && applyOperationalBucketFilter && chatConversationBucket(chat) !== state.conversationBucketFilter) return false;
                if (state.chatFilter === 'unread' && !isNewMessagesChatForPanel(chat)) return false;
                if (!searchActive && state.chatFilter === 'favorites' && !isFavoriteChat(chat)) return false;
                if (!searchActive && state.chatFilter === 'groups' && !chat.isGroup) return false;
                if (!searchActive && state.chatFilter === 'labels' && !hasVisibleLabels(chat)) return false;
                return chatMatchesSearch(chat, search);
            }).sort((left, right) => {
                const activityDifference = chatTimestampValue(right) - chatTimestampValue(left);
                if (activityDifference) return activityDifference;
                const unansweredDifference = Number(Number(right.unansweredCount || 0) > 0) - Number(Number(left.unansweredCount || 0) > 0);
                if (unansweredDifference) return unansweredDifference;
                const unreadDifference = Number(Number(right.unreadCount || 0) > 0) - Number(Number(left.unreadCount || 0) > 0);
                if (unreadDifference) return unreadDifference;
                return parsePanelDateMs(chatEntryAtRaw(right)) - parsePanelDateMs(chatEntryAtRaw(left));
            });

            const remoteSearchState = state.remoteChatSearch || {};
            const searchEmptyState = remoteSearchState.loading
                ? 'Buscando também no histórico de pedidos, Dropi e guias...'
                : remoteSearchState.error
                    ? `Busca histórica indisponível: ${remoteSearchState.error}`
                    : (remoteSearchState.query === search && searchActive
                        ? 'Nenhum cliente encontrado no painel ou no histórico.'
                        : (window.VitalismenChatSearchV41?.emptyStateMessage(search) || 'Nenhum chat encontrado.'));
            el('chatList').innerHTML = filtered.map((chat) => {
                const isActive = state.selectedChat?.id === chat.id || sameChatIdentity(state.selectedChat, chat);
                const owner = chat.human?.mode === 'manual'
                    ? (chat.human?.assignedName || 'humano')
                    : 'auto';
                const status = chatDisplayStatus(chat);
                const modeClass = chat.human?.mode === 'manual' ? 'manual' : '';
                const orderClass = status.closed ? 'closed' : 'pending';
                const orderBadge = chat.orderId
                    ? `<span class="badge ${status.className}">${escapeHtml(status.label)}</span>`
                    : '';
                const bucket = chatConversationBucket(chat);
                const bucketInfo = {
                    attendance: { label: 'ATENDIMENTO', className: 'orange' },
                    engagement: { label: 'AQUECIMENTO', className: 'green' },
                    orders: { label: 'PEDIDOS', className: 'orange' },
                    review: { label: 'REVISAR', className: 'red' }
                }[bucket] || { label: 'ATENDIMENTO', className: 'orange' };
                const title = chatDisplayName(chat);
                const lastTime = chatTimestampValue(chat) ? formatTime(chatTimestampValue(chat)).split(', ').pop() : '';
                const unreadCount = Math.max(0, Number(chat.unreadCount || 0));
                const unreadLabel = unreadCount > 99 ? '99+' : String(unreadCount);
                const unansweredCount = Math.max(0, Number(chat.unansweredCount || 0));
                const unansweredLabel = unansweredCount > 99 ? '99+' : String(unansweredCount);
                const vslWaiting = isVslAwaitingHuman(chat);
                const needsAttention = vslWaiting || unansweredCount > 0;
                const attentionTitle = chat.vslPrelead === true
                    ? 'Entrada VSL registrada; aguardando o primeiro WhatsApp com telefone real'
                    : unansweredCount > 0
                    ? `${unansweredLabel} mensagem${unansweredCount === 1 ? '' : 'ns'} do cliente sem resposta`
                    : 'Cliente da VSL sem atendimento';
                const attentionLabel = unansweredCount > 0 ? unansweredLabel : '!';
                const entryInfo = chatEntryInfo(chat);
                const sourceInfo = chatSourceInfo(chat);
                const avatar = `<span>${escapeHtml(avatarInitial(title))}</span>${chat.profilePictureUrl
                    ? `<img src="${escapeHtml(chat.profilePictureUrl)}" alt="" loading="lazy" onerror="this.remove()">`
                    : ''}`;
                return `
                    <button class="chat-item ${isActive ? 'active' : ''} ${unreadCount ? 'has-unread' : ''} ${unansweredCount ? 'has-unanswered' : ''} ${vslWaiting ? 'has-vsl-waiting' : ''} ${modeClass} ${orderClass}" data-chat-id="${escapeHtml(chat.id)}" type="button">
                        <div class="chat-row">
                            <div class="chat-avatar ${status.closed ? 'closed' : ''}">${avatar}</div>
                            <div class="chat-main">
                                <div class="chat-title">
                                    <span class="truncate">${escapeHtml(title)}</span>
                                    <span class="chat-side-meta">
                                        <span class="chat-time">${escapeHtml(lastTime)}</span>
                                        ${unreadCount ? `<span class="chat-unread-count">${escapeHtml(unreadLabel)}</span>` : ''}
                                    </span>
                                </div>
                                <div class="chat-phone-line">
                                    <span class="chat-phone-value">${escapeHtml(chat.vslPrelead === true ? 'AGUARDANDO WHATSAPP' : (chat.phone || chat.id || 'sem telefone'))}</span>
                                    ${needsAttention ? `<span class="chat-phone-attention ${unansweredCount > 0 ? 'customer-message' : ''}" title="${escapeHtml(attentionTitle)}" aria-label="${escapeHtml(attentionTitle)}">${escapeHtml(attentionLabel)}</span>` : ''}
                                </div>
                                <div class="chat-entry-line ${escapeHtml(entryInfo.className)}" title="${escapeHtml(entryInfo.title)}">
                                    <span class="entry-badge">${escapeHtml(entryInfo.badge)}</span>
                                    <span class="source-badge ${escapeHtml(sourceInfo.className)}" title="${escapeHtml(sourceInfo.title)}">${escapeHtml(sourceInfo.badge)}</span>
                                    <span class="truncate">${escapeHtml(entryInfo.label)}</span>
                                </div>
                                <div class="chat-preview">
                                    <span class="chat-badges">
                                        <span class="badge ${escapeHtml(bucketInfo.className)}">${escapeHtml(bucketInfo.label)}</span>
                                        ${orderBadge}
                                        ${vslWaiting ? (chat.vslPrelead === true
                                            ? '<span class="badge orange" title="Prelead VSL canônico sem telefone inventado; será consolidado quando o WhatsApp chegar">AGUARDANDO WHATSAPP</span>'
                                            : '<span class="badge orange" title="Entrada registrada pela VSL; nenhum atendente humano assumiu este cliente ainda">VSL · sem atendimento</span>') : ''}
                                        ${unansweredCount ? `<span class="badge orange" title="${escapeHtml(`${unansweredLabel} mensagem${unansweredCount === 1 ? '' : 'ns'} sem resposta`)}">${escapeHtml(unansweredLabel)} pendente${unansweredCount === 1 ? '' : 's'}</span>` : ''}
                                        <span class="badge ${chat.human?.mode === 'manual' ? 'orange' : 'green'}">${escapeHtml(owner)}</span>
                                    </span>
                                    <span class="chat-status-pill ${status.className}">${escapeHtml(status.label)}</span>
                                </div>
                                ${renderChatLabels(chat)}
                                <div class="chat-foot">
                                    <div class="meta truncate">${escapeHtml(chat.vslPrelead === true ? 'Telefone ainda não informado' : (chat.phone || chat.id))} ${chat.country ? ' · ' + escapeHtml(chat.country) : ''}</div>
                                    ${chat.orderId ? `<div class="meta">${escapeHtml(chat.orderId)}</div>` : ''}
                                </div>
                            </div>
                        </div>
                    </button>
                `;
            }).join('') || `<div class="empty">${escapeHtml(searchEmptyState)}</div>`;

            renderOperationalMetrics();
            renderTeamList();
        };

        const localSearchHasMatch = (query = '') => dedupeChatsForPanel(state.chats)
            .some((chat) => chatMatchesSearch(chat, query));

        const runRemoteChatSearch = async (query, sequence) => {
            const descriptor = window.VitalismenRemoteChatSearchV65?.queryDescriptor?.(query) || { valid: false };
            if (!descriptor.valid || !state.token || localSearchHasMatch(query)) {
                if (sequence === state.remoteChatSearch.sequence) {
                    state.remoteChatSearch.loading = false;
                    state.remoteChatSearch.results = [];
                    state.remoteChatSearch.error = '';
                    renderChats();
                }
                return;
            }
            try {
                const response = await api(`/api/whatsapp/chats/search?q=${encodeURIComponent(query)}&limit=12`);
                if (sequence !== state.remoteChatSearch.sequence) return;
                state.remoteChatSearch.results = Array.isArray(response?.results)
                    ? response.results.map(mergeSavedCustomerDraftIntoChat)
                    : [];
                state.remoteChatSearch.error = '';
            } catch (error) {
                if (sequence !== state.remoteChatSearch.sequence) return;
                state.remoteChatSearch.results = [];
                state.remoteChatSearch.error = String(error?.message || 'falha de consulta');
            } finally {
                if (sequence === state.remoteChatSearch.sequence) {
                    state.remoteChatSearch.loading = false;
                    renderChats();
                }
            }
        };

        const scheduleRemoteChatSearch = () => {
