            state.remoteChatSearch.sequence += 1;
            const sequence = state.remoteChatSearch.sequence;
            state.remoteChatSearch.query = query;
            state.remoteChatSearch.error = '';
            if (!descriptor.valid || localSearchHasMatch(query)) {
                state.remoteChatSearch.results = [];
                state.remoteChatSearch.loading = false;
                renderChats();
                return;
            }
            state.remoteChatSearch.results = [];
