            renderDropiDispatchHistory(data.history || []);
        }

        async function runDropiDispatchRetroactive({ dryRun = true, button = null } = {}) {
            if (state.busy) return;
            if (!dryRun && !window.confirm('Enviar agora avisos pendentes de guia/retirada/devolucao para clientes Vitalismen?')) return;
            state.busy = true;
            const label = button?.textContent || '';
            if (button) {
                button.disabled = true;
                button.textContent = dryRun ? 'Simulando...' : 'Enviando...';
            }
            try {
                const result = await api('/api/shipments/dispatch/retroactive', {
                    method: 'POST',
                    body: JSON.stringify({
                        days: 10,
                        syncLimit: 10,
                        dispatchLimit: 3,
                        dryRun,
                        actions: ['guide', 'ready_for_pickup', 'returned']
                    })
                });
                renderDropiDispatchResult(result);
                await Promise.all([loadDropiDispatchHistory(), loadAutomationStatus(), loadShipments(), loadChats()]);
                showToast(dryRun
                    ? `Simulacao concluida: ${result.pendingBeforeDispatch || 0} aviso(s) pendente(s).`
                    : `Avisos enviados: ${result.dispatch?.sent || 0}/${result.dispatch?.processed || 0}.`);
            } catch (error) {
                showToast(error.message);
                el('dropiDispatchSummary').textContent = `Falha na consulta/aviso: ${error.message}`;
            } finally {
                state.busy = false;
                if (button) {
                    button.disabled = false;
                    button.textContent = label;
                }
            }
        }

        async function loadChats() {
            if (!state.token) return;
            if (state.chatsLoading) {
                state.chatsRefreshQueued = true;
                return;
            }
            state.chatsLoading = true;
            const qs = new URLSearchParams();
            qs.set('country', 'EC');
            qs.set('fast', '1');
            try {
                const chats = await api(`/api/whatsapp/chats?${qs.toString()}`);
                await loadPersistedCustomerStateV204({ render: false }).catch(() => null);
                const ownZapiPhone = digitsOnlyText(state.zapiDevice?.device?.phone || '');
                let nextChats = ownZapiPhone
                    ? chats.filter((chat) => {
                        const chatPhone = digitsOnlyText(chat.phone || chat.id || '');
                        return !(chatPhone && (chatPhone === ownZapiPhone || chatPhone.endsWith(ownZapiPhone) || ownZapiPhone.endsWith(chatPhone)));
                    })
                    : chats;
                let selectedUnreadObserved = false;
                if (state.selectedChat) {
                    const selectedPhone = digitsOnlyText(state.selectedChat.phone || state.selectedChat.id || '');
                    nextChats = nextChats.map((chat) => {
                        const chatPhone = digitsOnlyText(chat.phone || chat.id || '');
                        const isSelected = chat.id === state.selectedChat.id
                            || (selectedPhone && chatPhone && (chatPhone === selectedPhone || chatPhone.endsWith(selectedPhone) || selectedPhone.endsWith(chatPhone)));
                        if (isSelected && Number(chat.unreadCount || 0) > 0) selectedUnreadObserved = true;
                        return isSelected ? { ...chat, unreadCount: 0 } : chat;
                    });
                }
                nextChats = dedupeChatsForPanel(nextChats.map(mergeSavedCustomerDraftIntoChat));
                const signature = getChatSignature(nextChats);
                state.chats = nextChats;
                document.dispatchEvent(new CustomEvent('vitalismen:whatsapp-chats-loaded-v226', { detail: chats }));
                if (state.selectedChat) {
                    const refreshedSelectedChat = state.chats.find((chat) => sameChatIdentity(state.selectedChat, chat));
                    state.selectedChat = refreshedSelectedChat
                        ? mergeSavedCustomerDraftIntoChat(refreshedSelectedChat)
                        : mergeSavedCustomerDraftIntoChat(state.selectedChat);
                }
                if (signature !== state.chatSignature) {
                    state.chatSignature = signature;
                    renderChats();
                    renderSelectedDetails();
                }
                if (selectedUnreadObserved) {
                    markSelectedChatRead({ silent: true }).catch(() => null);
                }
            } finally {
                state.chatsLoading = false;
                if (state.chatsRefreshQueued) {
                    state.chatsRefreshQueued = false;
                    window.setTimeout(() => loadChats().catch(() => null), 250);
                }
            }
        }

        async function createNewContact(event) {
            event.preventDefault();
            syncNewContactCountryFromPhone();
            const newContactPhone = el('newContactPhone').value.trim();
            const payload = {
                name: el('newContactName').value.trim(),
                phone: newContactPhone,
                note: el('newContactNote').value.trim(),
                country: el('newContactCountry').value || selectedPanelCountry() || 'EC',
