        async function addCustomerContactFromForm({ silent = false } = {}) {
            const draft = customerDraftFromForm();
            const selectedChatAtStart = state.selectedChat;
            if (!draft.phone) {
                showToast('Informe o WhatsApp do cliente na ficha.');
                return null;
            }
            const payload = {
                name: draft.name,
                phone: draft.phone,
                note: draft.note,
                country: draft.country || selectedPanelCountry() || 'EC',
                mode: 'manual'
            };
            const result = await api('/api/whatsapp/contacts', {
                method: 'POST',
                body: JSON.stringify(payload)
            });
            if (!silent) showToast(panelSyncMessage(result, 'Cliente adicionado ao atendimento'));
            await loadChats();
            const added = findChatByPhone(payload.phone);
            if (added && (!selectedChatAtStart || sameChatIdentity(state.selectedChat, selectedChatAtStart))) {
                selectChat(added.id);
            }
            return result;
        }

        const getMessageSignature = (messages) => (messages || [])
            .map((message) => [
                window.VitalismenCleanChatV29?.canonicalMessageIdentity(message) || message._id || '',
                message.timestamp || '',
                message.isFromMe ? '1' : '0',
                message.body || '',
                message.audioTranscript || message.audioTranslation || message.audioTranscription?.text || message.metadata?.audioTranscript || '',
                message.type || '',
                message.mediaUrl || '',
                message.mediaPreviewUrl || '',
                message.deliveryStatus || '',
                message.providerStatus || '',
                message.ack || '',
                message.mediaStorageStatus || '',
                message.mediaDownloadError || '',
                message.storedMime || '',
                message.mediaSize || '',
                (message.mediaAttachments || []).map((item) => `${item.type || ''}:${item.mediaUrl || ''}:${item.mediaPreviewUrl || ''}`).join(',')
            ].join(':'))
            .join('|');

        const messageComparableText = (message) => String(message?.body || '').trim();

        const isPendingMediaConfirmed = (pending, message) => {
            if (!pending?.mediaUrl || !message?.isFromMe) return false;
            const pendingAt = Number(pending.localCreatedAt || 0);
            const messageAt = parsePanelDateMs(message.timestamp || message.createdAt);
            if (pendingAt && messageAt && Math.abs(messageAt - pendingAt) > 300000) return false;
            const messageType = String(message.type || '').toLowerCase();
            return Boolean(message.mediaUrl || message.mediaAttachments?.length)
                || ['audio', 'ptt', 'image', 'video', 'media'].includes(messageType);
        };

        const mergePendingLocalMessages = (messages) => {
            const pendingMessages = state.pendingLocalMessages || [];
            const serverMessages = (Array.isArray(messages) ? messages : []).map((message) => {
                const hasMediaUrl = Boolean(message.mediaUrl || message.mediaAttachments?.length);
                const messageType = String(message.type || '').toLowerCase();
                if (hasMediaUrl || !message?.isFromMe || !['audio', 'ptt', 'image', 'video', 'media'].includes(messageType)) return message;
                const messageAt = parsePanelDateMs(message.timestamp || message.createdAt);
                const pending = pendingMessages.find((item) => (
                    item.mediaUrl
                    && (!messageAt || Math.abs(messageAt - (item.localCreatedAt || 0)) < 300000)
                    && (inferMediaType(item) === messageType || messageType === 'media')
                ));
                return pending
                    ? { ...message, mediaUrl: pending.mediaUrl, mediaPreviewUrl: pending.mediaPreviewUrl || pending.mediaUrl }
                    : message;
            });
            const now = Date.now();
            state.pendingLocalMessages = pendingMessages
                .filter((pending) => {
                    const pendingText = messageComparableText(pending);
                    const confirmed = serverMessages.some((message) => (
                        (
                            message?.isFromMe
                            && messageComparableText(message) === pendingText
                            && Math.abs(parsePanelDateMs(message.timestamp || message.createdAt) - (pending.localCreatedAt || 0)) < 180000
                        )
                        || isPendingMediaConfirmed(pending, message)
                    ));
                    return !confirmed && now - (pending.localCreatedAt || 0) < 180000;
                });
            return [...serverMessages, ...state.pendingLocalMessages]
                .sort((a, b) => parsePanelDateMs(a.timestamp || a.createdAt) - parsePanelDateMs(b.timestamp || b.createdAt));
        };

        const appendLocalMessage = (body, options = {}) => {
            const now = Math.floor(Date.now() / 1000);
            const localId = `local_${Date.now()}_${Math.random().toString(16).slice(2, 8)}`;
            const localMessage = {
                _id: localId,
                clientGeneratedId: localId,
                body,
                type: options.type || 'chat',
                mediaUrl: options.mediaUrl || '',
                mediaPreviewUrl: options.mediaPreviewUrl || '',
                timestamp: now,
                localCreatedAt: Date.now(),
                isFromMe: true,
                isBot: false,
                senderRole: 'human',
                attendantId: state.user?.id || state.user?._id || 'ana_lopez',
                notifyName: state.user?.name || state.user?.email || 'Atendente',
                quotedMessageId: options.quotedMessage?._id || '',
                quotedBody: options.quotedMessage ? messagePreviewText(options.quotedMessage).slice(0, 500) : '',
                quotedFromMe: options.quotedMessage ? Boolean(options.quotedMessage.isFromMe) : undefined,
                deliveryStatus: options.deliveryStatus || ''
            };
            state.pendingLocalMessages = [...(state.pendingLocalMessages || []), localMessage];
            state.currentMessages = mergePendingLocalMessages(state.currentMessages || []);
            state.messageSignature = getMessageSignature(state.currentMessages);
            renderMessages(state.currentMessages, { forceBottom: true });
            return localMessage;
        };

        const removePendingLocalMessage = (messageId) => {
            const id = String(messageId || '');
            if (!id) return;
            state.pendingLocalMessages = (state.pendingLocalMessages || []).filter((message) => String(message._id || '') !== id);
            state.currentMessages = (state.currentMessages || []).filter((message) => String(message._id || '') !== id);
            state.messageSignature = getMessageSignature(state.currentMessages);
            renderMessages(state.currentMessages, { preserveScroll: true });
        };

        const confirmPendingLocalMessage = (messageId, result = {}) => {
            const id = String(messageId || '');
            if (!id) return;
            const providerMessageId = String(result.providerMessageId || '').trim();
            const providerZaapId = String(result.providerZaapId || '').trim();
            const requestedStatus = String(result.deliveryStatus || '').trim().toLowerCase();
            const providerAccepted = ['provider_accepted', 'pending_confirmation'].includes(requestedStatus);
            const deliveryStatus = providerAccepted && !(providerMessageId || providerZaapId)
                ? 'request_failed'
                : (requestedStatus || 'request_failed');
            state.pendingLocalMessages = (state.pendingLocalMessages || []).map((message) => (
                String(message._id || '') === id
                    ? {
                        ...message,
                        _id: result.messageRecordId || message._id,
                        providerMessageId: providerMessageId || message.providerMessageId || '',
                        providerZaapId: providerZaapId || message.providerZaapId || '',
                        deliveryStatus,
                        sendError: deliveryStatus === 'request_failed'
                            ? (result.error || 'A Z-API não retornou um ID válido; envio não confirmado.')
                            : ''
                    }
                    : message
            ));
        };

        const inferMediaType = (attachment = {}) => {
            const explicit = String(attachment.type || '').toLowerCase();
            const url = String(attachment.mediaUrl || attachment.url || '').toLowerCase();
            if (/\.(jpe?g|png|webp|gif|heic|heif)(\?|#|$)/.test(url)) return 'image';
            if (/\.(mp3|ogg|opus|webm|m4a|aac|wav)(\?|#|$)/.test(url)) return 'audio';
            if (/\.(mp4|mov|m4v|avi|mkv)(\?|#|$)/.test(url)) return 'video';
            if (explicit && explicit !== 'media') return explicit;
            return explicit || 'media';
        };

        const panelMediaPath = (url = '') => {
            const value = String(url || '');
            if (!value) return value;
            const normalized = value.replace(/\\/g, '/');
            const marker = '/public/media/';
            const index = normalized.indexOf(marker);
            if (index !== -1) return `/media/${normalized.slice(index + marker.length)}`;
            return value;
        };

        const mediaUrlWithVersion = (url = '') => {
            const value = panelMediaPath(url);
            if (!value || !value.startsWith('/media/')) return value;
            return `${value}${value.includes('?') ? '&' : '?'}v=mediafix-20260517`;
        };

        const mediaPublicOrigin = () => {
            const host = String(window.location.hostname || '').toLowerCase();
            if (host === 'maxlien.shop' || host === 'www.maxlien.shop') return 'https://ec.maxlien.shop';
            return window.location.origin;
        };

        const absoluteMediaUrl = (url = '') => {
            const value = mediaUrlWithVersion(url);
            if (!value || /^(data:|blob:)/i.test(value)) return value;
            if (/^https?:\/\//i.test(value)) {
                try {
                    const parsed = new URL(value);
                    const sameSite = ['ec.maxlien.shop', 'maxlien.shop', window.location.hostname].includes(parsed.hostname);
                    return sameSite ? value : `/api/whatsapp/media-proxy?url=${encodeURIComponent(value)}`;
                } catch {
                    return value;
                }
            }
            return `${mediaPublicOrigin()}${value}`;
        };

        const protectedMediaRuntime = window.VitalismenAuthenticatedMedia;
        const authenticatedMediaObjectUrls = new Map();

        const clearAuthenticatedMediaObjectUrls = () => {
            for (const pending of authenticatedMediaObjectUrls.values()) {
                Promise.resolve(pending).then((objectUrl) => {
                    try { window.URL.revokeObjectURL(objectUrl); } catch { }
                }).catch(() => null);
            }
            authenticatedMediaObjectUrls.clear();
        };

        const isProtectedPanelMediaUrl = (url = '') => Boolean(
            protectedMediaRuntime?.isProtectedMediaUrl(url, window.location.origin)
        );

        const mediaHealthFallbackText = (message = {}, kind = 'media', reasonOverride = '') => (
            protectedMediaRuntime?.failureText({
                kind,
                status: message.mediaStorageStatus || '',
                reason: reasonOverride || message.mediaDownloadError || ''
            }) || 'Mídia indisponível · o arquivo não pôde ser carregado'
        );

        const mediaHealthBlocksRendering = (message = {}) => {
            const status = String(message.mediaStorageStatus || '').toUpperCase();
            return ['RECEIVED', 'FETCHING', 'STORED', 'FAILED'].includes(status);
        };

        const authenticatedMediaObjectUrl = (url = '') => {
            if (!authenticatedMediaObjectUrls.has(url)) {
                const promise = protectedMediaRuntime.fetchObjectUrl(url, { token: state.token })
                    .then((result) => result.objectUrl)
                    .catch((error) => {
                        authenticatedMediaObjectUrls.delete(url);
                        throw error;
                    });
                authenticatedMediaObjectUrls.set(url, promise);
            }
            return authenticatedMediaObjectUrls.get(url);
        };

        const markAuthenticatedMediaFailure = (node, reason = '') => {
            const shell = node.closest('[data-media-shell], [data-audio-player]');
            if (!shell) return;
            const kind = shell.dataset.mediaKind || 'media';
            const fallback = shell.querySelector('[data-auth-media-fallback]');
            if (fallback) {
                fallback.textContent = protectedMediaRuntime?.failureText({ kind, reason })
                    || mediaHealthFallbackText({}, kind, reason);
                fallback.classList.remove('hidden');
            }
            shell.classList.add('media-auth-error');
            const button = shell.querySelector('.wa-audio-play');
            if (button) button.disabled = true;
            const time = shell.querySelector('.wa-audio-time');
            if (time && (kind === 'audio' || kind === 'ptt')) time.textContent = 'Áudio indisponível';
            if (node.matches('img, video')) node.style.display = 'none';
        };

        const hydrateAuthenticatedMedia = (scope = document) => {
            if (!protectedMediaRuntime?.fetchObjectUrl || !state.token) return;
            scope.querySelectorAll('[data-auth-media-src]:not([data-auth-media-hydrated])').forEach((node) => {
                const source = node.dataset.authMediaSrc || '';
                if (!source) return;
                node.dataset.authMediaHydrated = 'pending';
                authenticatedMediaObjectUrl(source).then((objectUrl) => {
                    node.src = objectUrl;
                    node.dataset.authMediaHydrated = 'ready';
                    const shell = node.closest('[data-media-shell], [data-audio-player]');
                    shell?.querySelectorAll('[data-auth-media-link]').forEach((link) => {
