                    <div class="observer-compact-content">
                        <div class="observer-action-panel">
                            <button data-observer-lab-tab="best" class="${isBest ? 'primary' : ''}" type="button">Melhores</button>
                            <button data-observer-lab-tab="strategy" class="${isStrategy ? 'primary' : ''}" type="button">Estrategia</button>
                            <button data-observer-lab-tab="cache" class="${isCache ? 'primary' : ''}" type="button">Cache</button>
                            <button data-observer-lab-refresh="1" type="button" ${state.observerLabLoading ? 'disabled' : ''}>${state.observerLabLoading ? 'Atualizando...' : 'Atualizar'}</button>
                        </div>
                        <div class="actionable-card-body">${escapeHtml(summaryBits.filter(Boolean).join(' · '))}</div>
                        ${summary.warning ? `<div class="actionable-card-script">${escapeHtml(summary.warning)}</div>` : ''}
                        <div class="observer-funnel-grid">${rowsHtml}</div>
                        ${data.promptCandidate ? `<details class="observer-action-menu"><summary>Prompt candidato</summary><div class="actionable-card-script">${escapeHtml(data.promptCandidate)}</div></details>` : ''}
                    </div>
                </details>
