        };

        const renderActionableSamples = () => {
            const box = el('actionableSamples');
            if (!box) return;
            const items = state.actionableSamples || [];
            const blueprint = state.observerBlueprint || null;
            box.classList.toggle('active', Boolean(state.selectedChat));
            if (!state.selectedChat) {
                box.innerHTML = '';
