            }
            const leakItems = blueprint?.summary?.leaks || [];
            const blueprintHtml = blueprint ? `
                <details class="observer-compact-section">
                    <summary class="observer-compact-summary">
                        <span>Funil perfeito gerado</span>
                        <span class="badge green">${escapeHtml(blueprint.summary?.customerProfile || 'perfil geral')}</span>
                    </summary>
                    <div class="observer-compact-content">
                        <div class="actionable-card-body">
                            ${escapeHtml(`Analisei ${blueprint.summary?.totalMessages || 0} mensagens: ${blueprint.summary?.customerMessages || 0} do cliente e ${blueprint.summary?.humanMessages || 0} do atendente.`)}
                        </div>
                        ${leakItems.length ? `<div class="actionable-card-script">${leakItems.map((item) => `- ${escapeHtml(item)}`).join('<br>')}</div>` : ''}
                        <div class="observer-funnel-grid">
                            ${(blueprint.steps || []).slice(0, 10).map((step) => `
                                <div class="observer-step">
                                    <strong>${escapeHtml(step.order)}. ${escapeHtml(step.label)}</strong>
                                    <span class="meta">${escapeHtml(step.strategy || 'conducao')}</span>
                                    <div>${escapeHtml(step.perfectScript || '')}</div>
                                    ${step.learnedFromHuman ? `<span class="meta">${escapeHtml('Aprendido do atendente: ' + step.learnedFromHuman)}</span>` : ''}
                                </div>
                            `).join('')}
                        </div>
                    </div>
                </details>
            ` : '';
            const cardsHtml = items.map((item) => {
                const kind = String(item.type || '');
                const isWarning = kind === 'warning';
                const title = item.title || (isWarning ? 'Alerta do Observador' : 'Estrategia detectada');
                const body = item.body || '';
                const script = item.suggestedScript || item.templateDraft || item.detectedArgument || '';
                const confidence = Number(item.confidence || 0);
                const confidenceText = confidence ? `Confianca ${Math.round(confidence * 100)}%` : '';
                const audioHints = Array.isArray(item.context?.audioCandidates) ? item.context.audioCandidates.slice(0, 4) : [];
                const mediaHints = Array.isArray(item.context?.mediaCandidates) ? item.context.mediaCandidates.slice(0, 2) : [];
                const hintsHtml = (audioHints.length || mediaHints.length) ? `
                    <div class="actionable-card-script">
                        ${audioHints.length ? `<strong>Audios:</strong> ${escapeHtml(audioHints.join(' | '))}<br>` : ''}
                        ${mediaHints.length ? `<strong>Midias:</strong> ${escapeHtml(mediaHints.join(' | '))}` : ''}
                    </div>
                ` : '';
                const strategyActions = `
                    <button class="success" data-actionable-save="${escapeHtml(item._id)}" type="button">Sim, guardar</button>
                    <button data-actionable-feedback="${escapeHtml(item._id)}" type="button">Dica errada</button>
                    <button data-actionable-discard="${escapeHtml(item._id)}" type="button">Descartar</button>
                `;
                const warningActions = `
                    <button class="primary" data-actionable-apply="${escapeHtml(item._id)}" type="button">Aplicar via Z-API</button>
                    <button data-actionable-feedback="${escapeHtml(item._id)}" type="button">Dica errada</button>
                    <button data-actionable-discard="${escapeHtml(item._id)}" type="button">Descartar</button>
                `;
                return `
                    <details class="actionable-card ${isWarning ? 'warning' : 'strategy'}">
                        <summary class="row">
                            <div class="actionable-card-title">${escapeHtml(title)}</div>
                            ${confidenceText ? `<span class="badge ${isWarning ? 'orange' : 'green'}">${escapeHtml(confidenceText)}</span>` : ''}
                        </summary>
                        <div class="actionable-card-body">${escapeHtml(body)}</div>
                        ${hintsHtml}
                        ${script ? (isWarning
                            ? `<textarea class="observer-script-editor" data-actionable-script="${escapeHtml(item._id)}">${escapeHtml(script)}</textarea>`
                            : `<div class="actionable-card-script">${escapeHtml(script)}</div>`) : ''}
                        <details class="observer-action-menu">
                            <summary>Acoes</summary>
                            <div class="observer-action-panel">${isWarning ? warningActions : strategyActions}</div>
                        </details>
                    </details>
                `;
            }).join('');
            const audio = observerAudioRecommendations();
            const attendance = state.observerAttendanceScore;
            const attendanceBadge = attendance
                ? `${attendance.score10}/10`
                : 'sem nota';
            const attendanceClass = attendance?.score10 >= 10 ? 'green' : attendance?.score10 >= 9 ? 'orange' : attendance ? 'red' : 'orange';
            const attendanceHtml = `
                <details class="observer-compact-section" ${attendance ? 'open' : ''}>
                    <summary class="observer-compact-summary">
                        <span>Nota do atendimento</span>
                        <span class="badge ${attendanceClass}">${escapeHtml(attendanceBadge)}</span>
                    </summary>
                    <div class="observer-compact-content">
                        ${attendance ? `
                            <div class="actionable-card-body">${escapeHtml(`${attendance.label} · ${attendance.percent}/100 · ${attendance.summary?.humanMessages || 0} respostas humanas · ${attendance.summary?.audioCount || 0} audio(s)`)}</div>
                            ${(attendance.missing || []).length ? `<div class="actionable-card-script">${(attendance.missing || []).map((item) => `${escapeHtml(item.label)}: ${escapeHtml(item.fix)}`).join('<br>')}</div>` : '<div class="actionable-card-script">Atendimento pronto para virar skill validada.</div>'}
                            ${attendance.score10 >= 10 ? `
                                <details class="observer-action-menu">
                                    <summary>Acoes</summary>
                                    <div class="observer-action-panel">
                                        <button class="success" data-observer-save-attendance-skill="1" type="button" ${state.observerSavingAttendanceSkill ? 'disabled' : ''}>${state.observerSavingAttendanceSkill ? 'Salvando...' : 'Guardar no banco de skills'}</button>
                                    </div>
                                </details>
                            ` : attendance.score10 === 9 ? `
                                <div class="actionable-card-body">Falta pouco: aplique os ajustes acima para tentar chegar em 10/10 e 100/100.</div>
                            ` : `
                                <div class="actionable-card-body">Use as correcoes acima antes de salvar como skill.</div>
                            `}
                        ` : '<div class="actionable-card-body">Clique em Dar nota para o Observador avaliar de 0 a 10.</div>'}
                    </div>
                </details>
            `;
            const observerCountry = currentTemplateCountry();
            const audioHtml = `
                <details class="observer-compact-section">
                    <summary class="observer-compact-summary">
                        <span>Audios recomendados</span>
                        <span class="badge green">${escapeHtml(audio.recommendations.length)} sugestoes</span>
                    </summary>
