                button.disabled = true;
                button.textContent = '...';
            }
            try {
                const result = await api(`/api/whatsapp/messages/${encodeURIComponent(currentChatPhone())}/read-customer-image`, {
                    method: 'POST',
                    body: JSON.stringify({ messageId })
                });
                const data = result?.data || {};
                if (['none', 'low'].includes(data.confidence)) {
                    showToast('A imagem não contém dados de entrega legíveis o bastante para preencher a ficha.');
                    return;
                }
                const intelligence = window.VitalismenCustomerFormIntelligence;
                const safeName = intelligence?.confidentPersonName?.(data.name) || '';
                const fields = [
                    ['Nome', 'customerNameInput', safeName],
                    ['Endereço', 'customerAddressInput', data.address],
                    ['Referência', 'customerReferenceInput', data.reference],
                    ['Cidade', 'customerCityInput', data.city],
                    ['Província', 'customerProvinceInput', data.province]
                ].filter(([, , value]) => String(value || '').trim());
                if (!fields.length) {
                    showToast('Nenhum dado logístico validável foi encontrado na imagem.');
                    return;
                }
                const preview = fields.map(([label, , value]) => `${label}: ${value}`).join('\n');
                const evidence = String(data.evidence || '').trim();
                const accepted = window.confirm(
                    `Dados visíveis identificados na imagem:\n\n${preview}`
                    + `${evidence ? `\n\nTexto de apoio: ${evidence}` : ''}`
                    + '\n\nAplicar estes campos à ficha? Você poderá editar tudo normalmente antes do envio.'
                );
                if (!accepted) return;
                fields.forEach(([, inputId, value]) => {
                    setInputValue(inputId, value);
                    markCustomerInputCorrectedByHuman(inputId);
                });
                markCustomerFormDirty();
                scheduleCustomerFieldAutoSave({ delay: 700, source: 'customer-image-reader' });
                el('customerSyncHint').textContent = `Dados da imagem aplicados e salvando: ${fields.map(([label]) => label.toLowerCase()).join(', ')}.`;
                if (data.city || data.province || data.reference || data.address) {
                    lookupAgencySuggestions({ immediate: true }).catch(() => null);
                }
            } catch (error) {
                showToast(error.message || 'Não foi possível ler esta imagem agora.');
            } finally {
                if (button) {
                    button.disabled = false;
                    button.textContent = originalLabel;
                }
            }
        }

