        const markVisibleChatsRead = async () => {
            if (!state.token) {
                showToast('Entre no painel para marcar mensagens como lidas');
                return false;
            }
            const unreadChats = visibleOperationalChats().filter((chat) => Number(chat.unreadCount || 0) > 0);
            const unreadMessages = unreadChats.reduce((total, chat) => total + Math.max(0, Number(chat.unreadCount || 0)), 0);
            if (!unreadChats.length) {
                showToast('Nao ha mensagens antigas para marcar como lidas');
                return true;
            }
            const confirmed = window.confirm(
                `Marcar ${unreadMessages} mensagen${unreadMessages === 1 ? 'm' : 's'} antiga${unreadMessages === 1 ? '' : 's'} como lida${unreadMessages === 1 ? '' : 's'}?\n\n`+
                'Nenhuma conversa sera apagada. Clientes sem resposta continuarao identificados em Novas e mensagens novas voltarao a aparecer como nao lidas.'
            );
            if (!confirmed) return false;

            const button = el('markVisibleReadBtn');
            const originalLabel = button?.textContent || '✓ Marcar lidas';
            if (button) {
                button.disabled = true;
                button.textContent = 'Marcando...';
            }
            let markedChats = 0;
            let failedChats = 0;
            try {
                for (let index = 0; index < unreadChats.length; index += 6) {
                    const batch = unreadChats.slice(index, index + 6);
                    const results = await Promise.allSettled(batch.map((chat) => api('/api/whatsapp/chats/read', {
                        method: 'POST',
                        body: JSON.stringify({ chatId: chat.id, phone: chat.phone })
                    })));
                    results.forEach((result, resultIndex) => {
                        if (result.status === 'fulfilled' && Number(result.value?.matched || 0) > 0) {
                            batch[resultIndex].unreadCount = 0;
                            markedChats += 1;
                        } else {
                            failedChats += 1;
                        }
                    });
                    renderChats();
                }
                await loadChats().catch(() => null);
                if (failedChats) {
                    showToast(`${markedChats} conversa(s) marcada(s); ${failedChats} nao puderam ser atualizadas`);
                } else {
                    showToast(`${unreadMessages} mensagen${unreadMessages === 1 ? 'm' : 's'} antiga${unreadMessages === 1 ? '' : 's'} marcada${unreadMessages === 1 ? '' : 's'} como lida${unreadMessages === 1 ? '' : 's'}, sem apagar o historico`);
                }
            } finally {
                if (button) {
                    button.disabled = false;
                    button.textContent = originalLabel;
                }
                renderOperationalMetrics();
            }
            return failedChats === 0;
        };

        async function loadSelectedMessages(options = {}) {
            if (!state.token || !state.selectedChat) return;
            const requestKey = currentContactStateKey();
            state.messagesRequestKey = requestKey;
            if (state.messagesLoading && !options.bypassLoading) {
                state.messagesRefreshQueued = true;
                return;
            }
            state.messagesLoading = true;
            try {
                const limit = Math.min(Math.max(Number.parseInt(String(options.limit || 80), 10) || 80, 20), 300);
                const data = await api(`/api/whatsapp/messages/${encodeURIComponent(currentChatPhone())}?fast=1&limit=${limit}&_=${Date.now()}`);
                if (!state.selectedChat || state.messagesRequestKey !== requestKey || currentContactStateKey() !== requestKey) return;
                qaPanelUiV248.load().catch(() => null);
                const messages = mergePendingLocalMessages(data || []);
                const signature = getMessageSignature(messages);
                if (options.force || signature !== state.messageSignature) {
                    const box = el('conversation');
                    const nearBottom = box.scrollHeight - box.scrollTop - box.clientHeight < 90;
                    state.currentMessages = messages;
                    state.messageSignature = signature;
                    renderMessages(messages, { preserveScroll: !nearBottom && !options.force });
                    renderActionableSamples();
                    syncDetectedCustomerDataFromMessages(messages);
                }
            } finally {
                state.messagesLoading = false;
                if (state.messagesRefreshQueued) {
                    state.messagesRefreshQueued = false;
                    window.setTimeout(() => loadSelectedMessages().catch(() => null), 250);
                }
            }
        }

