                            ${editable ? `<button class="funnel-file-preview danger" data-custom-funnel-delete-code="${escapeHtml(item.code)}" type="button">Excluir</button>` : ''}
                            <button class="funnel-file-preview" data-custom-funnel-preview-code="${escapeHtml(item.code)}" type="button" title="Conferir antes de adicionar">${escapeHtml(customFunnelPreviewButtonLabel(item))}</button>
                            ${forBlock ? `<button class="funnel-file-add" data-custom-funnel-add-code="${escapeHtml(item.code)}" type="button" title="Adicionar este codigo ao bloco">Adicionar ao bloco</button>` : ''}
                        </span>
                    </div>
                `; }).join('') || '<button class="funnel-file-item" type="button" disabled>Nenhum item encontrado.</button>'}
            `;
        };

        const renderCustomFunnelManagerLibrary = () => {
            renderCustomFunnelLibraryList({
                targetId: 'customFunnelManagerLibraryList',
                searchId: 'customFunnelManagerSearch',
                forBlock: false
            });
            renderCustomFunnelLibraryList({
                targetId: 'customFunnelBlockLibraryList',
                searchId: 'customFunnelBlockSearch',
                forBlock: true
            });
        };

        const renderCustomFunnelManager = () => {
            const list = el('customFunnelManagerList');
            const detail = el('customFunnelManagerDetail');
            if (!list || !detail) return;
            renderCustomFunnelManagerLibrary();
            const blocks = customFunnelManagerBlocks();
            if (!blocks.length) {
                state.selectedCustomFunnelManagerValue = '';
                list.innerHTML = '<div class="custom-funnel-section-title">Blocos salvos</div><div class="custom-funnel-manager-empty">Nenhum bloco personalizado salvo ainda.</div>';
                detail.innerHTML = `
                    <div class="custom-funnel-manager-detail-title">
                        <strong>Sem bloco selecionado</strong>
                        <span>Monte um bloco nesta tela para liberar edicao, duplicacao ou exclusao.</span>
                    </div>
                    <div class="custom-funnel-manager-actions">
                        <button data-custom-funnel-manager-action="back" type="button">Voltar</button>
                    </div>
                `;
                return;
            }
            if (!selectedCustomFunnelManagerBlock()) {
                state.selectedCustomFunnelManagerValue = blocks[0].value;
            }
            const selected = selectedCustomFunnelManagerBlock();
            const selectedSteps = (selected?.steps || []).map((step, index) => `
                <li>
                    <strong>${escapeHtml(String(index + 1).padStart(2, '0'))}</strong>
                    <span>${escapeHtml(`${step.label || step.value || 'Item do bloco'} - ${funnelStepDelayLabel(step)}`)}</span>
                    <em>${escapeHtml(funnelStepActionLabel(step))}</em>
                </li>
            `).join('');
            list.innerHTML = `
                <div class="custom-funnel-section-title">Blocos salvos <span>${blocks.length}</span></div>
                ${blocks.map((block) => `
                <button class="custom-funnel-manager-card ${block.value === state.selectedCustomFunnelManagerValue ? 'active' : ''}" data-custom-funnel-manager-select="${escapeHtml(block.value)}" type="button">
                    <span class="custom-funnel-manager-code">${escapeHtml(block.code || 'B')}</span>
                    <span class="custom-funnel-manager-name">
                        <strong>${escapeHtml(block.label || 'Bloco personalizado')}</strong>
                        <span>${escapeHtml(block.detail || 'Sem detalhes')}</span>
                    </span>
                </button>
                `).join('')}
            `;
            detail.innerHTML = `
                <div class="custom-funnel-manager-detail-title">
                    <strong>${escapeHtml(selected?.label || 'Bloco selecionado')}</strong>
                    <span>${escapeHtml(selected?.detail || 'Escolha uma acao para este bloco.')}</span>
                </div>
                <ul class="custom-funnel-manager-steps">
                    ${selectedSteps || '<li><strong>00</strong><span>Nenhum item encontrado neste bloco.</span><em>vazio</em></li>'}
                </ul>
                <div class="custom-funnel-manager-actions">
                    <button data-custom-funnel-manager-action="edit" type="button">Editar</button>
                    <button class="copy" data-custom-funnel-manager-action="duplicate" type="button">Duplicar</button>
                    <button class="danger" data-custom-funnel-manager-action="delete" type="button">Excluir</button>
                    <button data-custom-funnel-manager-action="back" type="button">Voltar</button>
                </div>
            `;
        };

        const openCustomFunnelManager = () => {
            const drawer = document.querySelector('.composer-funnel-drawer');
            drawer?.classList.remove('side-open', 'manager-open');
            drawer?.style.removeProperty('--funnel-panel-left');
            drawer?.style.removeProperty('--funnel-panel-top');
            drawer?.style.removeProperty('--funnel-panel-width');
            drawer?.style.removeProperty('--funnel-panel-height');
            drawer?.style.removeProperty('--funnel-panel-max-height');
            if (drawer) drawer.open = false;
            document.body.classList.add('funnel-manager-active');
            el('funnelManagerPage')?.classList.remove('hidden');
            el('funnelManagerPage')?.setAttribute('aria-hidden', 'false');
            state.customFunnelManagerMode = 'browse';
            state.customFunnelManagerTab = state.customFunnelManagerTab || 'library';
            syncCustomFunnelManagerTypeTabs();
            syncCustomFunnelMessageType();
            syncCustomFunnelManagerNavigation();
            renderCustomFunnelManager();
            closeCustomFunnelMessageComposer();
        };

        const closeCustomFunnelManager = () => {
            document.body.classList.remove('funnel-manager-active');
            el('funnelManagerPage')?.classList.add('hidden');
            el('funnelManagerPage')?.setAttribute('aria-hidden', 'true');
            closeCustomFunnelMessageComposer();
        };

        const duplicateCustomFunnelBlock = (value = '') => {
            const block = (state.customFunnelBlocks || []).find((item) => item.value === value);
            if (!block) {
                showToast('Bloco personalizado nao encontrado');
                return;
            }
            const clone = {
                label: `${block.label || 'Bloco personalizado'} copia`,
                detail: block.detail || '',
                value: `custom_${Date.now()}_${Math.random().toString(16).slice(2, 8)}`,
                productKey: block.productKey || activeFunnelProductKey(),
                steps: (block.steps || []).map((step) => ({ ...step }))
            };
            state.customFunnelBlocks = normalizeCustomFunnelBlocks([
                ...(state.customFunnelBlocks || []),
                clone
            ]);
            const savedClone = state.customFunnelBlocks[state.customFunnelBlocks.length - 1];
            state.selectedCustomFunnelManagerValue = savedClone?.value || '';
            persistCustomFunnelBlocks();
            renderFooterAudioQuickList((state.audioTemplates || []).filter((template) => template.country === currentTemplateCountry()));
            renderCustomFunnelManagerLibrary();
            renderCustomFunnelManager();
            showToast('Bloco duplicado');
        };

        const handleCustomFunnelManagerAction = (action = '') => {
            if (action === 'back') {
                closeCustomFunnelManager();
                return;
            }
            const block = selectedCustomFunnelManagerBlock();
            if (!block) {
                showToast('Selecione um bloco personalizado');
                return;
            }
            if (action === 'edit') {
                editCustomFunnelBlock(block.value);
                el('customFunnelName')?.focus();
                return;
            }
            if (action === 'duplicate') {
                duplicateCustomFunnelBlock(block.value);
                return;
            }
            if (action === 'delete') {
                deleteCustomFunnelBlock(block.value);
                if (state.selectedCustomFunnelManagerValue === block.value) {
                    state.selectedCustomFunnelManagerValue = '';
                }
                renderCustomFunnelManager();
            }
        };

        const renderCustomFunnelDraft = () => {
            const box = el('customFunnelDraftList');
            if (!box) return;
            const steps = state.customFunnelDraftSteps || [];
            box.innerHTML = steps.length
                ? steps.map((step, index) => `
                    <article class="custom-funnel-timeline-card" draggable="true" data-custom-funnel-drag-index="${escapeHtml(index)}">
                        <div class="custom-funnel-timeline-head">
                            <em>${escapeHtml(step.code || step.typeLabel || step.type)}</em>
                            <strong>${escapeHtml(step.label || step.value || 'Item do bloco')}</strong>
                        </div>
                        <div class="custom-funnel-timeline-flow" aria-label="Sequencia do funil">
                            <span>${escapeHtml(funnelStepActionLabel(step))}</span>
                            <b>></b>
                            <span>${escapeHtml(funnelStepDelayLabel(step))}</span>
                            <b>></b>
                            <span>${escapeHtml(index < steps.length - 1 ? 'Proxima acao' : 'Fim do bloco')}</span>
                        </div>
                        <button class="custom-funnel-timeline-remove" data-custom-funnel-remove-step="${escapeHtml(index)}" type="button" title="Remover">Remover</button>
                    </article>
                `).join('')
                : '<span class="meta">Use + item e informe codigo como A08, M01 ou T02.</span>';
        };

        const blockDraftSteps = (block = {}) => {
            const items = footerFileItems((state.audioTemplates || []).filter((template) => template.country === currentTemplateCountry()));
            return (Array.isArray(block.steps) ? block.steps : [])
                .filter((step) => ['audio', 'media', 'draft'].includes(String(step.type || '')) && step.value)
                .map((step) => {
                    const item = items.find((candidate) => String(candidate.type) === String(step.type) && String(candidate.value) === String(step.value));
                    return {
                        code: item?.code || step.code || step.type,
                        type: step.type,
                        typeLabel: item?.typeLabel || step.typeLabel || step.type,
                        label: step.label || item?.label || step.value,
                        value: step.value,
                        waitAfterMs: Number(step.waitAfterMs || 0),
                        delayMode: String(step.delayMode || 'auto'),
                        delayMinMs: Number(step.delayMinMs || step.waitAfterMs || 0),
                        delayMaxMs: Number(step.delayMaxMs || 0),
                        simulateTyping: step.simulateTyping !== false,
                        recordedAudio: step.recordedAudio !== false
                    };
                });
        };

        const addCustomFunnelStepByCode = () => {
            const raw = window.prompt('Digite o codigo do item para adicionar ao bloco (ex.: A08, M01, T02):');
            const code = String(raw || '').trim().toUpperCase();
            addCustomFunnelStepFromCode(code);
        };

        const customFunnelDelayConfigFromInputs = () => {
            const mode = String(el('customFunnelStepDelayMode')?.value || 'auto');
            const minSeconds = Math.max(0, Math.min(600, Number(el('customFunnelStepDelaySeconds')?.value || 0)));
            const maxSeconds = Math.max(minSeconds, Math.min(600, Number(el('customFunnelStepDelayMaxSeconds')?.value || 0)));
            if (mode === 'fixed') {
                if (minSeconds <= 0) {
                    showToast('Informe o delay fixo em segundos');
                    return null;
                }
                return {
                    delayMode: 'fixed',
                    waitAfterMs: minSeconds * 1000,
                    delayMinMs: minSeconds * 1000,
                    delayMaxMs: 0
                };
            }
            if (mode === 'random') {
                if (minSeconds <= 0 || maxSeconds <= minSeconds) {
                    showToast('Delay randomico precisa de min e max validos');
                    return null;
                }
                return {
                    delayMode: 'random',
                    waitAfterMs: 0,
                    delayMinMs: minSeconds * 1000,
                    delayMaxMs: maxSeconds * 1000
                };
            }
            return {
                delayMode: 'auto',
                waitAfterMs: 0,
                delayMinMs: 0,
                delayMaxMs: 0
            };
        };

        const addCustomFunnelStepFromCode = (codeValue = '') => {
            const code = String(codeValue || '').trim().toUpperCase();
            if (!code) return;
            const country = currentTemplateCountry();
            const item = footerFileItems((state.audioTemplates || []).filter((template) => template.country === country))
                .find((candidate) => {
                    const candidateText = normalizeFunnelSearchText([
                        candidate.code,
                        candidate.label,
                        candidate.detail,
                        candidate.value,
                        candidate.mediaUrl,
                        candidate.previewUrl
                    ].filter(Boolean).join(' '));
                    const target = normalizeFunnelSearchText(code);
                    return candidateText === target || candidateText.includes(target) || target.includes(candidateText);
                });
            if (!item || item.type === 'block') {
                showToast('Codigo nao encontrado ou bloco dentro de bloco nao permitido');
                return;
            }
            const delayConfig = customFunnelDelayConfigFromInputs();
            if (!delayConfig) return;
            state.customFunnelDraftSteps = [
                ...(state.customFunnelDraftSteps || []),
                {
                    code: item.code,
                    type: item.type,
                    typeLabel: item.typeLabel,
                    label: item.label,
                    value: item.value,
                    ...delayConfig,
                    simulateTyping: item.type === 'draft',
                    recordedAudio: item.type === 'audio',
                    viewOnce: item.viewOnce === true
                }
            ].slice(0, 12);
            renderCustomFunnelDraft();
            showToast('Item adicionado ao bloco');
        };

        const saveCustomFunnelText = ({ addToBlock = false } = {}) => {
            const input = el('customFunnelTextInput');
            const titleInput = el('customFunnelTextTitleInput');
            const text = String(input?.value || '').trim();
            if (!text) {
                showToast('Digite o texto proprio antes de salvar');
                input?.focus();
                return;
            }
            const title = String(titleInput?.value || '').trim();
            const editingId = String(state.editingCustomFunnelTextId || '');
            const item = normalizeCustomFunnelTexts([{
                id: editingId || `text_${Date.now()}_${Math.random().toString(16).slice(2, 8)}`,
                label: title || customFunnelTextLabel(text),
                text
            }])[0];
            if (!item) return;
            state.customFunnelTexts = normalizeCustomFunnelTexts(editingId
                ? (state.customFunnelTexts || []).map((candidate) => String(candidate.id) === editingId ? item : candidate)
                : [
                    ...(state.customFunnelTexts || []),
                    item
                ]);
            const savedItem = (state.customFunnelTexts || []).find((candidate) => candidate.id === item.id) || item;
            if (editingId) {
                state.customFunnelBlocks = normalizeCustomFunnelBlocks((state.customFunnelBlocks || []).map((block) => ({
                    ...block,
                    steps: (block.steps || []).map((step) => String(step.value) === String(savedItem.value)
                        ? { ...step, label: savedItem.label }
                        : step)
                })));
                persistCustomFunnelBlocks();
            }
            persistCustomFunnelTexts();
            clearCustomFunnelTextEditor();
            closeCustomFunnelMessageComposer();
            renderFooterAudioQuickList((state.audioTemplates || []).filter((template) => template.country === currentTemplateCountry()));
            renderCustomFunnelManagerLibrary();
            if (addToBlock) addCustomFunnelStepFromCode(savedItem.code);
            showToast(addToBlock
                ? `Texto ${editingId ? 'atualizado' : 'salvo'} e adicionado: ${savedItem.code}`
                : `Texto ${editingId ? 'atualizado' : 'salvo'}: ${savedItem.code}`);
        };

        const pickCustomFunnelMessageFile = ({ addToBlock = false } = {}) => {
            const type = state.customFunnelMessageType || 'draft';
            state.customFunnelUploadAddToBlock = Boolean(addToBlock);
            if (type === 'audio') {
                el('customFunnelUploadAudioInput')?.click();
                return;
            }
            if (type === 'media') {
                el('customFunnelUploadMediaInput')?.click();
                return;
            }
            if (type === 'video') {
                el('customFunnelUploadMediaInput')?.click();
                return;
            }
            state.customFunnelUploadAddToBlock = false;
            showToast('Arquivo/documento entra em uma proxima camada. Use texto, audio ou midia agora.');
        };

        const createCustomFunnelMessage = ({ addToBlock = false } = {}) => {
            const type = state.customFunnelMessageType || 'draft';
            if (type === 'draft') {
                saveCustomFunnelText({ addToBlock });
                return;
            }
            if (state.customFunnelPendingFile) {
                state.customFunnelUploadAddToBlock = Boolean(addToBlock);
                uploadCustomFunnelFile(state.customFunnelPendingFile, state.customFunnelPendingFileKind || type);
                return;
            }
            pickCustomFunnelMessageFile({ addToBlock });
        };

        const saveCustomFunnelBlock = () => {
            const steps = state.customFunnelDraftSteps || [];
            if (!steps.length) {
                showToast('Adicione pelo menos um item ao bloco');
                return;
            }
            const label = (el('customFunnelName')?.value || '').trim() || `Bloco personalizado ${state.customFunnelBlocks.length + 1}`;
            const isEditingBlock = Boolean(state.editingCustomFunnelBlockValue);
            const value = state.editingCustomFunnelBlockValue || `custom_${Date.now()}_${Math.random().toString(16).slice(2, 8)}`;
            const existingBlock = isEditingBlock
                ? (state.customFunnelBlocks || []).find((block) => block.value === value)
                : null;
            const savedBlock = {
                label,
                detail: steps.map((step) => step.label).join(' + '),
                value,
                productKey: existingBlock?.productKey || activeFunnelProductKey(),
                steps: steps.map((step) => ({
                    type: step.type,
                    label: step.label,
                    value: step.value,
                    waitAfterMs: Number(step.waitAfterMs || 0),
                    delayMode: String(step.delayMode || 'auto'),
                    delayMinMs: Number(step.delayMinMs || step.waitAfterMs || 0),
                    delayMaxMs: Number(step.delayMaxMs || 0),
                    simulateTyping: step.simulateTyping !== false,
                    recordedAudio: step.recordedAudio !== false
                }))
            };
            const existingBlocks = state.editingCustomFunnelBlockValue
                ? (state.customFunnelBlocks || []).map((block) => block.value === value ? savedBlock : block)
                : [...(state.customFunnelBlocks || []), savedBlock];
            state.customFunnelBlocks = normalizeCustomFunnelBlocks(existingBlocks);
            persistCustomFunnelBlocks();
            state.customFunnelDraftSteps = [];
            state.editingCustomFunnelBlockValue = '';
            if (el('customFunnelName')) el('customFunnelName').value = '';
            renderCustomFunnelDraft();
            renderFooterAudioQuickList((state.audioTemplates || []).filter((template) => template.country === currentTemplateCountry()));
            renderCustomFunnelManager();
            showToast(isEditingBlock ? 'Bloco personalizado atualizado' : 'Bloco personalizado salvo');
        };

        const editCustomFunnelBlock = (value = '') => {
            const block = (state.customFunnelBlocks || []).find((item) => item.value === value);
            if (!block) {
                showToast('Bloco personalizado nao encontrado');
                return;
            }
            state.editingCustomFunnelBlockValue = block.value;
            state.customFunnelDraftSteps = blockDraftSteps(block).slice(0, 12);
            if (el('customFunnelName')) el('customFunnelName').value = block.label || '';
            setCustomFunnelManagerMode('browse');
            setCustomFunnelManagerTab('blocks');
            renderCustomFunnelDraft();
            showToast('Bloco carregado para edicao. Ajuste e clique em Salvar bloco.');
        };

        const deleteCustomFunnelBlock = (value = '') => {
            const block = (state.customFunnelBlocks || []).find((item) => item.value === value);
            if (!block) {
                showToast('Bloco personalizado nao encontrado');
                return;
            }
            if (!window.confirm(`Excluir o bloco "${block.label}"?`)) return;
            state.customFunnelBlocks = normalizeCustomFunnelBlocks((state.customFunnelBlocks || []).filter((item) => item.value !== value));
            if (state.editingCustomFunnelBlockValue === value) {
                state.editingCustomFunnelBlockValue = '';
                state.customFunnelDraftSteps = [];
                if (el('customFunnelName')) el('customFunnelName').value = '';
                renderCustomFunnelDraft();
            }
            persistCustomFunnelBlocks();
            renderFooterAudioQuickList((state.audioTemplates || []).filter((template) => template.country === currentTemplateCountry()));
            renderCustomFunnelManager();
            showToast('Bloco excluido');
        };

        const UNIVERSAL_INTRO_AUDIO_01_EC = '/media/templates/EC/01_B_Buenos_dias.ogg';
        const UNIVERSAL_INTRO_AUDIO_02_EC = '/media/templates/EC/01_C_Buenos_tardes.ogg';
        const TEX_ULTRA_UNIVERSAL_ENTRY_AUDIO_EC = '/media/templates/EC/CONHECER_NECESSIDADES_CLIENTES.ogg';
        const TEX_ULTRA_ENTRY_GREETING_EMOJIS = Object.freeze(['👋', '😊', '🙂', '🙏', '✅']);
        let texUltraEntryGreetingEmojiCursor = 0;

        const nextTexUltraPanelGreetingEmoji = () => {
            const emoji = TEX_ULTRA_ENTRY_GREETING_EMOJIS[
                texUltraEntryGreetingEmojiCursor % TEX_ULTRA_ENTRY_GREETING_EMOJIS.length
            ];
            texUltraEntryGreetingEmojiCursor = (texUltraEntryGreetingEmojiCursor + 1)
                % TEX_ULTRA_ENTRY_GREETING_EMOJIS.length;
            return emoji;
        };

        const texUltraPanelGreetingPeriod = (date = new Date()) => {
            const parts = new Intl.DateTimeFormat('en-US', {
                timeZone: 'America/Guayaquil',
                hour: '2-digit',
                hourCycle: 'h23'
            }).formatToParts(date instanceof Date ? date : new Date(date));
            const hour = Number(parts.find((part) => part.type === 'hour')?.value || 0);
            if (hour >= 5 && hour <= 11) return 'buenos días';
            if (hour >= 12 && hour <= 17) return 'buenas tardes';
            return 'buenas noches';
        };

        const texUltraPanelGreetingName = (chat = state.selectedChat || {}) => {
            const candidates = [chat.customerDraft?.name, chat.name]
                .map((value) => String(value || '').replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 80));
            return candidates.find((value) => value
                && !/^\+?[\d\s().-]{7,}$/.test(value)
                && !/^(cliente|customer|entrada vsl|desconocido|desconocida|unknown)$/i.test(value)) || '';
        };

        const buildTexUltraPanelGreeting = (chat = state.selectedChat || {}, date = new Date()) => {
            const name = texUltraPanelGreetingName(chat);
            const opening = name
                ? `Hola, ${name}, ${texUltraPanelGreetingPeriod(date)}.`
                : `Hola, ${texUltraPanelGreetingPeriod(date)}.`;
            return `${nextTexUltraPanelGreetingEmoji()} ${opening} Soy Ana López, asistente de la Dra. María Fernandes. Vi su mensaje y será un gusto atenderle personalmente. Estoy aquí para ayudarle. ¿En qué puedo ayudarle?`;
        };

        const footerFunnelBlocks = () => {
            const selectedProductKey = activeFunnelProductKey();
            const defaultBlocks = selectedProductKey === 'nitrix_ec' ? [{
                    code: 'B01',
                    type: 'block',
                    typeLabel: 'bloco',
                    label: 'Inicio completo Nitrix',
                    detail: 'Saudacao Ana Lopez + Prova 1 + Frasco Nitrix; audios da identidade anterior bloqueados',
                    value: 'nitrix_inicio_completo',
                    steps: [
                        { type: 'draft', label: 'Saudacao Ana Lopez', value: 'nitrix_ana_entry' },
                        { type: 'media', label: 'Prova 1', value: '/media/sales/shared/social_01.jpeg' },
                        { type: 'media', label: 'Frasco Nitrix', value: '/media/sales/ec/nitrix_bottle.png', waitAfterMs: 0 }
                    ]
                }, {
                    code: 'B02',
                    type: 'block',
                    typeLabel: 'bloco',
                    label: 'Frasco Nitrix',
                    detail: 'Imagem do produto Nitrix para atendimento manual',
                    value: 'nitrix_frasco',
                    steps: [
                        { type: 'media', label: 'Frasco Nitrix', value: '/media/sales/ec/nitrix_bottle.png', waitAfterMs: 0 }
                    ]
                }] : selectedProductKey === 'tex_ultra_ec' ? [{
                    code: 'B01',
                    type: 'block',
                    typeLabel: 'bloco',
                    label: 'Inicio completo Tex Ultra',
                    detail: 'Saudacao com nome + um audio universal + Prova 1 + Frasco Tex Ultra + Valores promocionais',
                    value: 'tex_ultra_inicio_completo',
                    steps: [
                        { type: 'draft', label: 'Saudacao personalizada', value: 'tex_ultra_personalized_entry' },
                        { type: 'audio', label: 'Inicio universal Tex Ultra', value: TEX_ULTRA_UNIVERSAL_ENTRY_AUDIO_EC },
                        { type: 'media', label: 'Prova 1', value: '/media/sales/shared/social_01.jpeg' },
                        { type: 'media', label: 'Frasco Tex Ultra', value: '/media/sales/ec/tex_ultra.png', waitAfterMs: 0 },
                        { type: 'draft', label: 'Valores promocionais · desde USD 35.99', value: 'tex_ultra_promotion_1' }
                    ]
                }] : [{
                    code: 'B01',
                    type: 'block',
                    typeLabel: 'bloco',
                    label: 'Inicio completo Vit Power',
                    detail: 'Saudacao personalizada + 4 arquivos; pausas de 18-30s no servidor',
                    value: 'vit_power_inicio_completo',
                    steps: [
                        { type: 'audio', label: 'Inicio universal 01', value: UNIVERSAL_INTRO_AUDIO_01_EC },
                        { type: 'audio', label: 'Inicio universal 02', value: UNIVERSAL_INTRO_AUDIO_02_EC },
                        { type: 'media', label: 'Prova 1', value: '/media/sales/shared/social_01.jpeg' },
                        { type: 'media', label: 'Frasco Vit Power', value: '/media/sales/ec/vit_power.jpeg', waitAfterMs: 0 }
                    ]
                }];
            const customBlocks = (state.customFunnelBlocks || [])
                .filter((block) => block.productKey === 'all' || block.productKey === selectedProductKey)
                .map((block, index) => ({ ...block, code: customFunnelCode(defaultBlocks.length + index) }));
            return [
                ...defaultBlocks,
                ...customBlocks
            ];
        };

        const sortedFooterAudioTemplates = (templates = []) => [...templates]
            .sort((a, b) => {
                const aLabel = `${a.label || ''} ${a.id || ''}`;
                const bLabel = `${b.label || ''} ${b.id || ''}`;
                const ag = footerFunnelGroupInfo(a);
                const bg = footerFunnelGroupInfo(b);
                if (ag.order !== bg.order) return ag.order - bg.order;
                const ai = footerAudioPriorityLabels.findIndex((pattern) => pattern.test(aLabel));
                const bi = footerAudioPriorityLabels.findIndex((pattern) => pattern.test(bLabel));
                const as = ai === -1 ? 999 : ai;
                const bs = bi === -1 ? 999 : bi;
                return as - bs || String(a.label || a.id || '').localeCompare(String(b.label || b.id || ''), undefined, { numeric: true, sensitivity: 'base' });
            });

        const footerAudioCodeForMediaUrl = (mediaUrl = '') => {
            const country = currentTemplateCountry();
            const templates = sortedFooterAudioTemplates((state.audioTemplates || []).filter((template) => template.country === country));
            const index = templates.findIndex((template) => String(template.mediaUrl || '') === String(mediaUrl || ''));
            return index === -1 ? '' : footerShortCode('A', index);
        };

        const footerFileItems = (templates = []) => [
            ...footerFunnelBlocks(),
            ...footerDraftFiles(),
            ...sortedFooterAudioTemplates(templates).map((template, index) => ({
                code: footerShortCode('A', index),
                type: 'audio',
                typeLabel: 'audio',
                label: funnelAudioLabel(template),
                detail: `${footerFunnelGroupInfo(template).label} - ${footerFileName(template.mediaUrl || template.previewUrl || template.id || '')}`,
                value: template.mediaUrl
            })),
            ...(state.customFunnelUploads || []),
            ...footerMediaFiles()
        ];

        const renderFunnelMemory = () => {
            const strip = el('funnelMemoryStrip');
            const list = el('funnelMemoryList');
            if (!strip || !list) return;
            const refs = (state.recentFunnelRefs || []).slice(0, 6);
            strip.classList.toggle('active', Boolean(refs.length));
            list.innerHTML = refs.map((item) => `
                <button
                    class="funnel-memory-chip"
                    data-footer-file-type="${escapeHtml(item.type)}"
                    data-footer-file-value="${escapeHtml(item.value)}"
                    type="button"
                    title="${escapeHtml(item.detail || item.label || '')}">
                    <strong>${escapeHtml(item.code || item.typeLabel || '')}</strong>
                    <span>${escapeHtml(item.label || item.value || '')}</span>
                </button>
            `).join('');
        };

        const rememberFunnelRef = (item = {}) => {
            if (!item.value && !item.label) return;
            const normalized = {
                code: item.code || '',
                type: item.type || 'draft',
                typeLabel: item.typeLabel || item.type || '',
                label: item.label || item.value || '',
                detail: item.detail || item.value || '',
                value: item.value || ''
            };
            state.recentFunnelRefs = [
                normalized,
                ...(state.recentFunnelRefs || []).filter((ref) => `${ref.type}:${ref.value}` !== `${normalized.type}:${normalized.value}`)
            ].slice(0, 6);
            renderFunnelMemory();
            renderComposerQuickStatusBar();
        };

        const findFooterFileItem = (type, value) => footerFileItems((state.audioTemplates || []).filter((template) => template.country === currentTemplateCountry()))
            .find((item) => {
                if (String(item.type) !== String(type)) return false;
                const target = normalizeFunnelSearchText(String(value || '').replace(/\.[a-z0-9]{2,5}$/i, ''));
                if (!target) return false;
                const candidateText = normalizeFunnelSearchText([
                    item.code,
                    item.label,
                    item.detail,
                    item.value,
                    item.mediaUrl,
                    item.previewUrl
                ].filter(Boolean).join(' '));
                return candidateText === target || candidateText.includes(target) || target.includes(candidateText);
            });

        const normalizeFunnelSearchText = (value = '') => String(value || '')
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .toLowerCase()
            .replace(/[^a-z0-9]+/g, ' ')
            .trim();

        const funnelSearchTokens = (value = '') => normalizeFunnelSearchText(value)
            .split(/\s+/)
            .filter(Boolean);

        const funnelSearchInitials = (value = '') => funnelSearchTokens(value)
            .map((token) => token[0] || '')
            .join('');

        const matchesFunnelSearch = (item = {}, rawSearch = '') => {
            const search = normalizeFunnelSearchText(rawSearch);
            if (!search) return true;
            const fields = [
                item.code,
                item.label,
                item.detail,
                item.typeLabel,
                item.value
            ].filter(Boolean);
            const haystack = normalizeFunnelSearchText(fields.join(' '));
            if (haystack.includes(search)) return true;
            const compactSearch = search.replace(/\s+/g, '');
            if (!compactSearch) return true;
            if (fields.some((field) => normalizeFunnelSearchText(field).replace(/\s+/g, '').includes(compactSearch))) return true;
            const tokens = funnelSearchTokens(fields.join(' '));
            if (tokens.some((token) => token.startsWith(compactSearch))) return true;
            const initialSets = fields.map(funnelSearchInitials).filter(Boolean);
            if (initialSets.some((initials) => initials.startsWith(compactSearch) || initials.includes(compactSearch))) return true;
            return tokens.filter((token) => token[0] === compactSearch[0]).some((token) => token.startsWith(compactSearch));
        };

        const syncFunnelSearchFromInput = () => {
            const input = el('funnelFileSearch');
            if (input) state.funnelSearchText = input.value || '';
            return state.funnelSearchText || '';
        };

        const restoreFunnelSearchInput = ({ focus = false } = {}) => {
            const input = el('funnelFileSearch');
            if (!input) return;
            const value = state.funnelSearchText || '';
            if (input.value !== value) input.value = value;
            if (focus) {
                input.focus();
                const caret = input.value.length;
                input.setSelectionRange?.(caret, caret);
            }
        };

        const quickStatusItems = () => {
            const countryTemplates = (state.audioTemplates || []).filter((template) => template.country === currentTemplateCountry());
            const all = footerFileItems(countryTemplates);
            const recent = (state.recentFunnelRefs || []).map((ref) => findFooterFileItem(ref.type, ref.value) || ref);
            const groups = [
                recent,
                all.filter((item) => item.type === 'block').slice(0, 4),
                all.filter((item) => item.type === 'audio').slice(0, 4),
                all.filter((item) => item.type === 'draft').slice(0, 3),
                all.filter((item) => item.type === 'media').slice(0, 3)
            ];
            const seen = new Set();
            return groups.flat().filter((item) => {
                const key = `${item.type}:${item.value}`;
                if (!item.value || seen.has(key)) return false;
                seen.add(key);
                return true;
            }).slice(0, 12);
        };

        const renderComposerQuickStatusBar = () => {
            const list = el('composerQuickStatusList');
            if (!list) return;
            if (!el('flowCorrectionStatus')) {
                list.innerHTML = `
                    <div id="flowCorrectionStatus" class="flow-status-chips">
                        <span class="meta">Dados OK aparecem aqui depois de fixados.</span>
                    </div>
                `;
            }
            renderFlowCorrectionStatus(state.selectedChat);
        };

        const renderFooterAudioQuickList = (templates = []) => {
            const box = el('footerAudioQuickList');
            if (!box) return;
            const search = String(syncFunnelSearchFromInput()).trim().toLowerCase();
            const typeFilter = state.funnelTypeFilter || 'all';
            const filteredItems = footerFileItems(templates)
                .filter((item) => {
                    if (typeFilter !== 'all' && String(item.type) !== typeFilter) return false;
                    return matchesFunnelSearch(item, search);
                });
            const items = filteredItems.slice(0, 80);
            const totalLabel = filteredItems.length > 80 ? '80+' : String(filteredItems.length);
            const canSendToCustomer = Boolean(state.selectedChat);
            const libraryHintText = canSendToCustomer
                ? 'Biblioteca pronta para envio ao cliente. Para criar ou editar blocos, use Gerenciar.'
                : 'Biblioteca de envio pronta. Selecione um cliente para liberar o envio.';
            box.innerHTML = `
                <div class="funnel-library-hint">
                    <span class="funnel-library-hint-text">${escapeHtml(libraryHintText)}</span>
                    ${filteredItems.length ? `<span class="funnel-library-total">Total: ${escapeHtml(totalLabel)}</span>` : ''}
                </div>
                ${items.map((item) => `
                <div class="funnel-file-item is-library-only">
                    <span class="funnel-file-code">${escapeHtml(item.code)}</span>
                    <span class="funnel-file-name">
                        <strong>${escapeHtml(item.label)}</strong>
                        <span>${escapeHtml(item.detail || item.value || '')}</span>
                    </span>
                    <span class="funnel-file-type">${escapeHtml(item.typeLabel)}</span>
                    <span class="funnel-file-actions">
                        <button
                            class="funnel-file-send"
                            data-footer-file-type="${escapeHtml(item.type)}"
                            data-footer-file-value="${escapeHtml(item.value)}"
                            type="button"
                            ${canSendToCustomer ? '' : 'disabled'}
                            title="${escapeHtml(canSendToCustomer ? 'Enviar ao cliente selecionado' : 'Selecione um cliente para enviar')}">
                            Enviar
                        </button>
                    </span>
                </div>
            `).join('') || '<div class="funnel-file-list-blank" aria-hidden="true"></div>'}
            `;
            renderFunnelMemory();
            renderComposerQuickStatusBar();
            restoreFunnelSearchInput();
        };

        const syncFunnelTypeTabs = () => {
            document.querySelectorAll('[data-funnel-type-filter]').forEach((button) => {
                button.classList.toggle('active', String(button.dataset.funnelTypeFilter || 'all') === String(state.funnelTypeFilter || 'all'));
            });
        };

        const openFunnelMasterPanel = ({ toggle = false } = {}) => {
            const drawer = document.querySelector('.composer-funnel-drawer');
            if (!drawer) return;
            if (toggle && drawer.classList.contains('side-open') && drawer.open) {
                closeFunnelSidePanel();
                drawer.open = false;
                return;
            }
            const operationPanel = el('operationPanel');
            const customerSection = operationPanel?.querySelector?.('.customer-section');
            const customerRect = customerSection?.getBoundingClientRect?.();
            const panelRect = operationPanel?.getBoundingClientRect?.();
            const viewportWidth = window.innerWidth || document.documentElement.clientWidth || 1280;
            const viewportHeight = window.innerHeight || document.documentElement.clientHeight || 720;
            const margin = 12;
            const anchorRect = customerRect && customerRect.width > 220 ? customerRect : panelRect;
            const anchorWidth = anchorRect?.width || 380;
            const width = Math.max(320, Math.min(560, anchorWidth - 12, viewportWidth - (margin * 2)));
            const maxLeft = Math.max(margin, viewportWidth - width - margin);
            const desiredLeft = anchorRect ? anchorRect.left + 6 : maxLeft;
            const left = Math.min(Math.max(margin, desiredLeft), maxLeft);
            const desiredTop = anchorRect ? anchorRect.top + 4 : margin;
            const top = Math.min(Math.max(margin, desiredTop), Math.max(margin, viewportHeight - 320));
            const bottomLimit = anchorRect
                ? Math.min(viewportHeight - margin, Math.max(anchorRect.bottom - 4, viewportHeight - margin))
                : viewportHeight - margin;
            const height = Math.max(320, bottomLimit - top);
            drawer.classList.add('side-open');
            drawer.style.setProperty('--funnel-panel-left', `${Math.round(left)}px`);
            drawer.style.setProperty('--funnel-panel-top', `${Math.round(top)}px`);
            drawer.style.setProperty('--funnel-panel-width', `${Math.round(width)}px`);
            drawer.style.setProperty('--funnel-panel-height', `${Math.round(height)}px`);
            drawer.style.setProperty('--funnel-panel-max-height', `${Math.round(height)}px`);
            drawer.open = true;
            if (activeFunnelProductKey() === 'vit_power_ec' && currentChatPhone()) {
                const selected = state.selectedChat;
                api('/api/whatsapp/b01-v216?phone=' + encodeURIComponent(currentChatPhone()))
                    .then(r => { if (state.selectedChat === selected) applyB01ProgressV216(r.job); }).catch(() => null);
            }
            renderFooterAudioQuickList((state.audioTemplates || []).filter((template) => template.country === currentTemplateCountry()));
            window.requestAnimationFrame(() => {
                restoreFunnelSearchInput({ focus: true });
            });
        };

        const closeFunnelSidePanel = () => {
            const drawer = document.querySelector('.composer-funnel-drawer');
            if (!drawer) return;
            drawer.classList.remove('side-open');
            drawer.style.removeProperty('--funnel-panel-left');
            drawer.style.removeProperty('--funnel-panel-top');
            drawer.style.removeProperty('--funnel-panel-width');
            drawer.style.removeProperty('--funnel-panel-height');
            drawer.style.removeProperty('--funnel-panel-max-height');
        };

        async function loadAudioTemplates() {
            if (!state.token) return;
            const country = currentTemplateCountry();
            const data = await api(`/api/whatsapp/templates?country=${encodeURIComponent(country)}`);
            const otherCountryTemplates = state.audioTemplates.filter((template) => template.country !== country);
            state.audioTemplates = [...otherCountryTemplates, ...(data.templates || [])];
            renderAudioTemplates();
            renderActionableSamples();
        }

        async function sendFunnelAudio(mediaUrl, button) {
            if (!state.selectedChat || state.busy || !mediaUrl) return;
            state.busy = true;
            const label = button.textContent;
            button.disabled = true;
            button.textContent = '...';
            const cleanLabel = label.replace(/\s+/g, ' ').trim();
            const pendingMessage = appendLocalMessage(`Enviando audio: ${cleanLabel}`, {
                type: 'audio',
                mediaUrl,
                mediaPreviewUrl: mediaUrl,
                deliveryStatus: 'sending'
            });
            try {
                const result = await api('/api/whatsapp/send', {
                    method: 'POST',
                    body: JSON.stringify({
                        phone: currentChatPhone(),
                        message: mediaUrl,
                        isMedia: true,
                        sessionId,
                        clientGeneratedId: pendingMessage?.clientGeneratedId || '',
                        sendMode: 'manual_panel',
                        allowAudioDedupeBypass: true,
                        country: currentTemplateCountry(),
                        recordedAudio: true
                    })
                });
                if (!result?.success) {
                    throw new Error(result?.error || 'WhatsApp nao confirmou o envio do audio.');
                }
                confirmPendingLocalMessage(pendingMessage?._id, result);
                rememberFunnelRef(findFooterFileItem('audio', mediaUrl) || {
                    type: 'audio',
                    typeLabel: 'audio',
                    label: cleanLabel,
                    value: mediaUrl
                });
                showToast('Audio do funil enviado');
                Promise.all([loadSelectedMessages({ force: true }), loadChats()]).catch(() => null);
                window.setTimeout(() => loadActionableSamples().catch(() => null), 900);
            } catch (error) {
                markPendingLocalMessageStatus(pendingMessage?._id, 'unconfirmed', error.message || 'Audio sem confirmacao da Z-API.');
                showToast(error.message);
            } finally {
                state.busy = false;
                button.disabled = false;
                button.textContent = label;
            }
        }

        async function sendFooterMedia(mediaUrl, button) {
            if (!state.selectedChat || state.busy || !mediaUrl) return;
            state.busy = true;
            const label = button.textContent;
            button.disabled = true;
            button.textContent = '...';
            const cleanLabel = label.replace(/\s+/g, ' ').trim();
            const mediaType = inferMediaType({ mediaUrl });
            const mediaItem = findFooterFileItem('media', mediaUrl) || {};
            const pendingMessage = appendLocalMessage(`Enviando ${mediaType === 'image' ? 'imagem' : mediaType === 'video' ? 'video' : 'midia'}: ${cleanLabel}`, {
                type: mediaType,
                mediaUrl,
                mediaPreviewUrl: mediaUrl,
                deliveryStatus: 'sending'
            });
            try {
                const result = await api('/api/whatsapp/send', {
                    method: 'POST',
                    body: JSON.stringify({
                        phone: currentChatPhone(),
                        message: mediaUrl,
                        isMedia: true,
                        sessionId,
                        clientGeneratedId: pendingMessage?.clientGeneratedId || '',
                        sendMode: 'manual_panel',
                        allowAudioDedupeBypass: true,
                        country: currentTemplateCountry(),
                        viewOnce: mediaItem.viewOnce === true
                    })
                });
                if (!result?.success) {
                    throw new Error(result?.error || 'WhatsApp nao confirmou o envio da midia.');
                }
                confirmPendingLocalMessage(pendingMessage?._id, result);
                rememberFunnelRef(mediaItem.value ? mediaItem : {
                    type: 'media',
                    typeLabel: inferMediaType({ mediaUrl }),
                    label: cleanLabel,
                    value: mediaUrl
                });
                showToast('Midia do funil enviada');
                Promise.all([loadSelectedMessages({ force: true }), loadChats()]).catch(() => null);
                window.setTimeout(() => loadActionableSamples().catch(() => null), 900);
            } catch (error) {
                markPendingLocalMessageStatus(pendingMessage?._id, 'unconfirmed', error.message || 'Midia sem confirmacao da Z-API.');
                showToast(error.message);
            } finally {
                state.busy = false;
                button.disabled = !state.selectedChat;
                button.textContent = label;
            }
        }

        const waitFunnelStep = (ms = 0) => new Promise((resolve) => window.setTimeout(resolve, Math.max(0, Number(ms) || 0)));

        const funnelProgressStatusLabel = (status = 'idle') => ({
            idle: 'Pronto',
            processing: 'Processando',
            sending: 'Enviando',
            done: 'Concluído',
            error: 'Erro'
        }[status] || 'Processando');

        const isFunnelTextStep = (step = {}) => String(step.type || '') === 'draft';

        const funnelProgressTypeKey = (step = {}) => {
            if (isFunnelTextStep(step)) return 'text';
            if (String(step.type || '') === 'audio') return 'audio';
            return 'media';
        };

        const funnelErrorMessage = (error) => String(error?.message || error || 'Erro no envio do bloco')
            .replace(/\s+/g, ' ')
            .trim()
            .slice(0, 180);

        const buildFunnelStepPayload = (step = {}, index = 0) => {
            const position = index + 1;
            const label = String(step.label || step.code || step.type || `item ${position}`).trim();
            if (isFunnelTextStep(step)) {
                const text = buildDraftTemplate(step.value);
                if (!text) throw new Error(`Texto vazio no item ${position}: ${label}`);
                return {
                    message: text,
                    isMedia: false,
                    type: 'text',
                    label,
                    delayTypingSeconds: step.simulateTyping === false ? 0 : funnelStepTypingSeconds(step)
                };
            }

            const mediaPath = String(step.value || '').trim();
            if (!mediaPath) throw new Error(`Midia vazia no item ${position}: ${label}`);
            if (!mediaPath.startsWith('/media/') && !mediaPath.startsWith('data:')) {
                throw new Error(`Midia invalida no item ${position}: use arquivo importado no funil`);
            }
            return {
                message: mediaPath,
                mediaPath,
                isMedia: true,
                type: String(step.type || '') === 'audio' ? 'audio' : inferMediaType({ mediaUrl: mediaPath }),
                label,
                recordedAudio: String(step.type || '') === 'audio' && step.recordedAudio !== false,
                viewOnce: step.viewOnce === true
            };
        };

        const renderFunnelProgress = () => {
            const progress = state.funnelProgress || {};
            const total = Math.max(0, Number(progress.total || 0));
            const sent = Math.max(0, Math.min(total, Number(progress.sent || 0)));
            const percent = total > 0 ? Math.round((sent / total) * 100) : 0;
            const status = progress.status || 'idle';
            const box = el('funnelProgressStatus');
            if (!box) return;
            box.dataset.status = status;
            box.classList.toggle('is-idle', status === 'idle' || (status === 'done' && total === 0));
            if (el('funnelProgressPercent')) el('funnelProgressPercent').textContent = `Enviando: ${percent}%`;
            if (el('funnelProgressFiles')) el('funnelProgressFiles').textContent = `Arquivos: ${sent}/${total} enviados`;
            if (el('funnelProgressBadge')) el('funnelProgressBadge').textContent = funnelProgressStatusLabel(status);
            if (el('funnelProgressFill')) el('funnelProgressFill').style.width = `${percent}%`;
            if (el('funnelProgressLabel')) el('funnelProgressLabel').textContent = progress.label || 'Pronto para enviar bloco';
            const activeType = progress.activeType || '';
            el('funnelProgressTypeText')?.classList.toggle('active', activeType === 'text');
            el('funnelProgressTypeAudio')?.classList.toggle('active', activeType === 'audio');
            el('funnelProgressTypeMedia')?.classList.toggle('active', activeType === 'media');
        };

        const setFunnelProgress = (patch = {}) => {
            state.funnelProgress = {
                ...(state.funnelProgress || {}),
                ...patch
            };
            renderFunnelProgress();
        };

        const applyB01ProgressV216 = (job) => {
            if (!job) return;
            const running = ['pending', 'sending'].includes(job.status);
            const seconds = job.nextAt ? Math.max(0, Math.ceil((new Date(job.nextAt) - Date.now()) / 1000)) : 0;
            setFunnelProgress({ status: job.status === 'done' ? 'done' : running ? 'sending' : 'error',
                sent: job.sent, total: 4, activeType: '',
                label: job.status === 'done' ? 'B01 concluido; arquivos aceitos pelo provedor'
                    : running ? `B01: ${job.sent}/4 aceitos. ${seconds ? 'Proximo item em ' + seconds + 's' : 'Aguardando confirmacao'}`
                    : `B01 pausado para conferencia: ${job.reason || job.status}. Nenhum reenvio automatico.` });
        };
        async function sendProtectedB01V216(phone, chatId) {
            let result = await api('/api/whatsapp/b01-v216', { method: 'POST', body: JSON.stringify({ phone }) });
            if (!result?.success) throw new Error(result?.error || 'B01 nao confirmado; consulte o progresso');
            for (let i = 0; i < 144; i += 1) {
                if (state.selectedChat !== chatId) return;
                applyB01ProgressV216(result.job);
                if (!['pending', 'sending'].includes(result.job?.status)) return;
                await waitFunnelStep(2500);
                result = await api('/api/whatsapp/b01-v216?phone=' + encodeURIComponent(phone));
            }
            showToast('B01 continua no servidor. Abra o funil para consultar o progresso.');
        }

        async function sendFunnelBlock(blockId, button) {
            if (!state.selectedChat || state.funnelBlockSending || !blockId) return;
            const block = footerFunnelBlocks().find((item) => item.value === blockId);
            if (!block?.steps?.length) {
                showToast('Bloco de funil nao encontrado');
                return;
            }

            const targetPhone = currentChatPhone();
            const targetChatId = state.selectedChat;
            if (!targetPhone) {
                showToast('Cliente sem telefone para envio');
                return;
            }

            state.funnelBlockSending = true;
            const originalHtml = button.innerHTML;
            button.disabled = true;
            button.textContent = 'Enviando bloco...';
            let sentCount = 0;
            let activePendingMessage = null;
            let activeStepConfirmed = false;
            setFunnelProgress({
                status: 'processing',
                sent: 0,
                total: block.steps.length,
                label: `Preparando ${block.code || 'bloco'} para ${targetPhone.slice(-4)}`,
                activeType: ''
            });

            try {
                if (blockId === 'vit_power_inicio_completo') {
                    await sendProtectedB01V216(targetPhone, targetChatId);
                    Promise.all([loadSelectedMessages({ force: true }), loadChats()]).catch(() => null);
                    return;
                }
                const payloads = block.steps.map((step, index) => buildFunnelStepPayload(step, index));
                for (let index = 0; index < block.steps.length; index += 1) {
                    const step = block.steps[index];
                    const payload = payloads[index];
                    const activeType = funnelProgressTypeKey(step);
                    setFunnelProgress({
                        status: 'sending',
                        sent: sentCount,
                        total: block.steps.length,
                        label: `${block.code || 'Bloco'} ${index + 1}/${block.steps.length}: ${payload.label}`,
                        activeType
                    });
                    activeStepConfirmed = false;
                    if (state.selectedChat === targetChatId) {
                        const previewMediaUrl = payload.mediaPath || step.value;
                        activePendingMessage = payload.isMedia
                            ? appendLocalMessage(`Bloco ${block.code}: ${index + 1}/${block.steps.length} ${payload.label}`, {
                                type: payload.type,
                                mediaUrl: previewMediaUrl,
                                mediaPreviewUrl: previewMediaUrl
                            })
                            : appendLocalMessage(payload.message, { type: 'text' });
                    }
                    const sendRequest = api('/api/whatsapp/send', {
                        method: 'POST',
                        body: JSON.stringify({
                            phone: targetPhone,
                            message: payload.message,
                            isMedia: payload.isMedia,
                            sessionId,
                            clientGeneratedId: activePendingMessage?.clientGeneratedId || '',
                            sendMode: 'manual_panel',
                            allowAudioDedupeBypass: true,
                            country: currentTemplateCountry(),
                            delayTypingSeconds: payload.delayTypingSeconds || 0,
                            recordedAudio: payload.recordedAudio === true,
                            viewOnce: payload.viewOnce === true,
                            funnelBlockStep: {
                                block: block.code || block.label || '',
                                index: index + 1,
                                total: block.steps.length,
                                action: funnelStepActionLabel(step),
                                delay: funnelStepDelayLabel(step)
                            }
                        })
                    });
                    const failsafeMs = funnelStepFailsafeMs();
                    const result = failsafeMs > 0
                        ? await Promise.race([
                            sendRequest,
                            waitFunnelStep(failsafeMs).then(() => ({ success: false, error: `Failsafe: etapa ${index + 1} excedeu o tempo limite` }))
                        ])
                        : await sendRequest;
                    if (!result?.success) {
                        throw new Error(result?.error || `WhatsApp nao confirmou: ${payload.label}`);
                    }
                    confirmPendingLocalMessage(activePendingMessage?._id, result);
                    activeStepConfirmed = true;
                    activePendingMessage = null;
                    sentCount = index + 1;
                    const rememberedValue = payload.mediaPath || step.value;
                    rememberFunnelRef(findFooterFileItem(step.type, rememberedValue) || {
                        type: step.type,
                        typeLabel: step.type === 'audio' ? 'audio' : inferMediaType({ mediaUrl: step.value }),
                        label: payload.label,
                        value: rememberedValue
                    });
                    setFunnelProgress({
                        status: 'sending',
                        sent: sentCount,
                        total: block.steps.length,
                        label: `${block.code || 'Bloco'} ${index + 1}/${block.steps.length} enviado`,
                        activeType
                    });
                    if (index < block.steps.length - 1) {
                        const delayMs = funnelBlockDelayMs(step, index);
                        showToast(`Proximo item em ${Math.round(delayMs / 1000)}s`);
                        await waitFunnelStep(delayMs);
                    }
                }

                rememberFunnelRef(block);
                setFunnelProgress({
                    status: 'done',
                    sent: sentCount,
                    total: block.steps.length,
                    label: `Concluido: ${block.label}`,
                    activeType: ''
                });
                showToast(`Bloco enviado: ${block.label}`);
                Promise.all([loadSelectedMessages({ force: true }), loadChats()]).catch(() => null);
                window.setTimeout(() => loadActionableSamples().catch(() => null), 900);
            } catch (error) {
                if (!activeStepConfirmed) {
                    markPendingLocalMessageStatus(
                        activePendingMessage?._id,
                        'unconfirmed',
                        error.message || 'Etapa do bloco sem confirmacao da Z-API.'
                    );
                }
                const message = funnelErrorMessage(error);
                setFunnelProgress({
                    status: 'error',
                    sent: sentCount,
                    total: block.steps.length,
                    label: message,
                    activeType: ''
                });
                showToast(message);
            } finally {
                state.funnelBlockSending = false;
                button.disabled = !state.selectedChat;
                button.innerHTML = originalHtml;
            }
        }

        const buildAvisos = (shipment) => {
            const a = shipment.automation || {};
            const items = [
                a.submittedToDroppiAt ? 'Dropi enviado' : '',
                shipment.review?.reviewStatus === 'manual_send_required' ? 'Pedir envio manual' : '',
                shipment.review?.reviewStatus === 'dropi_payment_required' ? 'Aguardando saldo Dropi' : '',
                shipment.review?.reviewStatus === 'manual_sent' ? 'Marcado enviado manual' : '',
                a.guiaNotifiedAt ? 'Guia avisada' : '',
                a.readyForPickupNotifiedAt ? 'Agencia avisada' : '',
                a.pickupProofRequestedAt ? 'Comprovante pedido' : '',
                a.bonusNotifiedAt ? 'Bonus enviado' : ''
            ].filter(Boolean);
            return items.join(' · ') || 'Sem avisos';
        };

        const dropiFilterLabels = {
            all_dropi: 'visao geral',
            confirmed: 'conferir e autorizar',
            not_sent: 'enviar para Dropi',
            sent: 'enviados',
            progress: 'revisar',
            returned: 'recuperar',
            buy_later: 'retomar',
            review_orders: 'Tecnico'
        };

        const shipmentStatus = (shipment) => String(shipment?.logistics?.status || '').toUpperCase();
        const isSentShipment = (shipment) => Boolean(shipment?.automation?.submittedToDroppiAt) || /GUIA_GENERADA|PREPARADO/.test(shipmentStatus(shipment));
        const isReturnedShipment = (shipment) => /DEVUELTO|RETURNED|DEVOLUCION|DEVOLUCAO|NO_RETIRADO/.test(shipmentStatus(shipment));
        const needsManualSend = (shipment) => shipment?.review?.manualOnly || shipment?.review?.reviewStatus === 'manual_send_required';
        const needsDropiPayment = (shipment) => shipment?.review?.reviewStatus === 'dropi_payment_required'
            || shipment?.automation?.browserCheckpoint === 'dropi_payment_required';
        const isProgressShipment = (shipment) => needsManualSend(shipment) || needsDropiPayment(shipment) || /PENDIENTE|MERCANCIA|BODEGA|DESPACHO|RUTA|REPARTO|PROCESAMIENTO|READY_FOR_PICKUP|NOVEDAD|AGENCIA/.test(shipmentStatus(shipment));

        const dropiSubmitPath = (country, orderId) => {
            return `/api/shipments/droppi/ec/orders/${encodeURIComponent(orderId)}/submit`;
        };

        const dropiPreparePath = (country, orderId) => {
            return `/api/shipments/droppi/ec/orders/${encodeURIComponent(orderId)}/prepare-manual`;
        };

        const dropiManualLinkPath = (country, orderId) => {
            return `/api/shipments/droppi/ec/orders/${encodeURIComponent(orderId)}/manual-link`;
        };

        const dropiSubmitStatusPath = (country, orderId) => {
            return `/api/shipments/droppi/ec/orders/${encodeURIComponent(orderId)}/submit-status`;
        };

        const manualDropiPrepareAvailable = ['localhost', '127.0.0.1'].includes(window.location.hostname);

        const dropiAuthorizePath = (country, orderId) => {
            return `/api/shipments/droppi/ec/orders/${encodeURIComponent(orderId)}/authorize-submit`;
        };

        async function submitDropiOrder(orderId, country) {
            if (!orderId) throw new Error('Pedido nao informado');
            let result = await api(dropiSubmitPath(country, orderId), {
                method: 'POST',
                body: JSON.stringify({ async: true })
            });
            if (result.submitQueued || result.processing) {
                const startedAt = Date.now();
                const maxWaitMs = 9 * 60 * 1000;
                while ((Date.now() - startedAt) < maxWaitMs) {
                    await new Promise((resolve) => setTimeout(resolve, 15000));
                    result = await api(dropiSubmitStatusPath(country, orderId));
                    if (result.alreadySubmitted || result.status === 'submitted') break;
                    if (result.manualSendRequired || result.paymentRequired || result.authorizationRequired) break;
                }
                if (result.submitQueued || result.processing) {
                    throw new Error(result.message || 'Dropi ainda esta processando. Atualize em instantes antes de reenviar.');
                }
            }
            if (result.manualSendRequired) return result;
            if (result.paymentRequired) return result;
            if (result.alreadySubmitted) return result;
            if (result.ok === false || result.success === false) {
                throw new Error(result.error || result.reason || 'Dropi nao confirmou o envio');
            }
            return result;
        }

        async function prepareDropiOrder(orderId, country) {
            if (!orderId) throw new Error('Pedido nao informado');
            const result = await api(dropiPreparePath(country, orderId), { method: 'POST' });
            if (result.alreadySubmitted) return result;
            if (result.ok === false || result.success === false) {
                throw new Error(result.error || result.reason || 'Nao consegui preparar a Dropi');
            }
            return result;
        }

        async function openManualDropiFallback(orderId, country, reason = '') {
            if (!orderId) throw new Error('Pedido nao informado');
            const qs = reason ? `?reason=${encodeURIComponent(reason)}` : '';
            const result = await api(`${dropiManualLinkPath(country, orderId)}${qs}`);
            if (result.alreadySubmitted) return result;
            if (result.copyText) {
                await navigator.clipboard?.writeText(result.copyText).catch(() => null);
            }
            if (result.dropiUrl) {
                window.open(result.dropiUrl, '_blank', 'noopener');
            }
            window.alert([
                'Nao foi pelo envio normal. Abri a Dropi em nova aba.',
                '',
                'Os dados do pedido foram copiados quando o navegador permitiu.',
                'Confira/cole os dados, ajuste o que precisar e confirme manualmente.',
                '',
                result.copyText || ''
            ].join('\n'));
            return result;
        }

        async function openDropiManualPath(orderId, country, reason = '') {
            if (manualDropiPrepareAvailable) {
                try {
                    const result = await prepareDropiOrder(orderId, country);
                    showToast(result.alreadySubmitted
                        ? 'Pedido ja estava enviado para Dropi.'
                        : 'Dropi aberta/preenchida. Confira e finalize manualmente.');
                    return result;
                } catch (error) {
                    showToast(`Preparo automatico falhou: ${error.message}. Abrindo caminho manual simples.`);
                }
            }
            return openManualDropiFallback(orderId, country, reason);
        }

        async function authorizeDropiOrder(orderId, country) {
            if (!orderId) throw new Error('Pedido nao informado');
            const result = await api(dropiAuthorizePath(country, orderId), {
                method: 'POST',
                body: JSON.stringify({ note: 'Autorizado no painel operacional Dropi' })
            });
            if (result.ok === false || result.success === false) {
                throw new Error(result.error || result.reason || 'Nao consegui autorizar o pedido');
            }
            return result;
        }

        const dropiSuccessId = (result) => result.dropiOrderId
            || result.result?.dropiResponse?.objects?.id
            || result.result?.dropiOrderId
            || result.result?.verifiedDropiOrderId
            || result.shipment?.raw?.droppiOrder?.id
            || '';

        const dropiSuccessMessage = (result) => {
            const dropiId = dropiSuccessId(result);
            if (result.alreadySubmitted) {
                return dropiId ? `Pedido ja estava enviado. ID ${dropiId}.` : 'Pedido ja estava enviado para Dropi.';
            }
            return dropiId ? `Enviado para Dropi. ID ${dropiId}.` : 'Enviado para Dropi com sucesso.';
        };

        const findLoadedOrder = (orderId) => state.orders.find((order) => order.orderId === orderId)
            || state.dropiItems.find((item) => item.type === 'order' && item.order?.orderId === orderId)?.order
            || null;

        const findLoadedShipment = (orderId) => state.shipments.find((shipment) => shipment.orderId === orderId)
            || state.dropiItems.find((item) => item.type === 'shipment' && item.shipment?.orderId === orderId)?.shipment
            || null;

        const selectedChatOrderFallback = (orderId, country) => {
            if (state.selectedChat?.orderId !== orderId) return null;
            return {
                orderId,
                country: country || state.selectedChat.country,
                status: state.selectedChat.orderStatus,
                customer: {
                    name: state.selectedChat.name,
                    phone: state.selectedChat.phone,
                    city: state.selectedChat.city,
                    province: state.selectedChat.province,
                    address: state.selectedChat.address
                }
            };
        };

        const orderConfirmData = (orderId, country) => {
            const order = findLoadedOrder(orderId) || selectedChatOrderFallback(orderId, country) || { orderId, country };
            const shipment = findLoadedShipment(orderId);
            const customer = order.customer || shipment?.client || {};
            const pkg = order.package || {};
            return {
                orderId: order.orderId || shipment?.orderId || orderId,
                country: order.country || shipment?.country || country || '',
                status: order.status || shipment?.logistics?.status || '',
                name: customer.name || shipment?.client?.name || '',
                phone: customer.phone || shipment?.client?.phone || '',
                province: customer.province || shipment?.client?.province || '',
                city: customer.city || shipment?.client?.city || '',
                address: customer.address || shipment?.client?.address || '',
                reference: customer.reference || shipment?.client?.reference || '',
                packageLabel: pkg.label || (pkg.quantity ? `${pkg.quantity} unidade(s)` : ''),
                quantity: pkg.quantity || shipment?.treatment?.unitsPurchased || '',
                total: order.total ?? '',
                currency: order.currency || 'USD'
            };
        };

        const blockBrazilTestDropi = (record) => {
            if (!isBrazilTestRecord(record)) return false;
            showToast(brazilTestMessage);
            return true;
        };

        const formatMoney = (value, currency) => {
            if (value === '' || value === null || value === undefined) return 'sem valor';
            const number = Number(value);
            if (!Number.isFinite(number)) return String(value);
            return `${number.toFixed(2)} USD`;
        };

        const formatDropiConfirmBlock = (data, index = null) => {
            const prefix = index === null ? '' : `${index + 1}. `;
            return [
                `${prefix}Pedido: ${data.orderId || 'sem ID'}${data.status ? ` · status ${data.status}` : ''}`,
                `Cliente: ${data.name || 'sem nome'}`,
                `Telefone: ${data.phone || 'sem telefone'}`,
                `Local: ${[data.province, data.city].filter(Boolean).join(' / ') || 'sem local'}`,
                `Endereco: ${data.address || 'sem endereco'}`,
                data.reference ? `Referencia: ${data.reference}` : '',
                `Pacote: ${data.packageLabel || (data.quantity ? `${data.quantity} unidade(s)` : 'sem pacote')}`,
                `Total: ${formatMoney(data.total, data.currency)}`
            ].filter(Boolean).join('\n');
        };

        const confirmDropiSubmission = (orderId, country) => {
            const data = orderConfirmData(orderId, country);
            if (blockBrazilTestDropi(data)) return false;
            return window.confirm([
                'Confirmar envio deste pedido para a Dropi?',
                '',
                formatDropiConfirmBlock(data),
                '',
                'Apos confirmar, o pedido sera processado na Dropi.'
            ].join('\n'));
        };

        const confirmBulkDropiSubmission = (orders) => {
            const blocked = orders.filter((order) => isBrazilTestRecord(orderConfirmData(order.orderId, order.country)));
            if (blocked.length) {
                showToast(`${blocked.length} pedido(s) BR teste bloqueado(s). Remova da selecao.`);
                return false;
            }
            const blocks = orders.map((order, index) => formatDropiConfirmBlock(orderConfirmData(order.orderId, order.country), index));
            return window.confirm([
                `Confirmar envio de ${orders.length} pedido(s) para a Dropi?`,
                '',
                blocks.join('\n\n'),
                '',
                'Apos confirmar, todos serao processados em sequencia.'
            ].join('\n'));
        };

        const manualDropiActionLabels = {
            'authorize-dropi': {
                title: 'Autorizar este pedido para envio na Dropi?',
                footer: 'Todo envio para Dropi exige autorizacao manual antes. Depois de autorizado, ele entra na etapa 2 Enviar para Dropi. Nada sera enviado agora.'
            },
            'requeue-dropi': {
                title: 'Voltar este pedido para a etapa Enviar para Dropi?',
                footer: 'Use quando o erro anterior ja foi corrigido. Nada sera enviado agora; ele apenas volta para a fila normal.'
            },
            'prepare-dropi': {
                title: 'Confirmar preparo manual deste pedido na Dropi?',
                footer: 'Apos confirmar, a automacao abrira/preenchera a Dropi para conferencia manual.'
            },
            'manual-dropi-link': {
                title: 'Abrir este pedido para finalizar manualmente na Dropi?',
                footer: 'A Dropi sera aberta para voce conferir, ajustar e confirmar manualmente. Depois marque Manual enviado.'
            },
            'mark-manual-sent': {
                title: 'Confirmar que este pedido JA foi enviado manualmente?',
                footer: 'Use somente se o pedido ja foi criado na Dropi fora do envio automatico.'
            },
            'manual-send-required': {
                title: 'Confirmar marcar este pedido para envio manual?',
                footer: 'Apos confirmar, ele saira da fila automatica e ficara para revisao/manual.'
            },
            'delete-fake': {
                title: 'Excluir este pedido fake do painel?',
                footer: 'So use para teste/fake. Se for pedido real, nao exclua. Pedido com guia ou Dropi ID sera bloqueado.'
            },
            'remove-from-confirmed': {
                title: 'Remover este pedido da fila de Confirmados?',
                footer: 'Use para pedido repetido, engano ou pedido que nao deve ir para Dropi agora. Ele volta para atendimento e nao sera apagado.'
            }
        };

        const confirmManualDropiAction = (orderId, country, action) => {
            const copy = manualDropiActionLabels[action];
            if (!copy) return true;
            const data = orderConfirmData(orderId, country);
            if (blockBrazilTestDropi(data)) return false;
            return window.confirm([
                copy.title,
                '',
                formatDropiConfirmBlock(data),
                '',
                copy.footer
            ].join('\n'));
        };

        const matchesSelectedOrSearch = (item) => {
            const search = el('shipmentSearch').value.trim().toLowerCase();
            const haystack = item.type === 'order'
                ? [
                    item.order.orderId,
                    item.order.customer?.name,
                    item.order.customer?.phone,
                    item.order.customer?.city,
                    item.order.customer?.province
                ].join(' ').toLowerCase()
                : [
                    item.shipment.orderId,
                    item.shipment.client?.name,
                    item.shipment.client?.phone,
                    item.shipment.client?.city,
                    item.shipment.client?.province,
                    item.shipment.logistics?.trackingNumber
                ].join(' ').toLowerCase();
            if (search) return haystack.includes(search);
            if (['all_dropi', 'confirmed', 'not_sent', 'sent', 'progress', 'review_orders'].includes(state.dropiFilter)) {
                return true;
            }
            const selectedPhone = String(state.selectedChat?.phone || '').replace(/\D/g, '');
            if (!selectedPhone) return true;
            const itemPhone = item.type === 'order'
                ? item.order.customer?.phone
                : item.shipment.client?.phone;
            return String(itemPhone || '').replace(/\D/g, '').endsWith(selectedPhone.slice(-9));
        };

        const selectedOrderForChat = (chat = state.selectedChat) => {
            const orderId = chat?.orderId || el('customerOrderInput')?.value?.trim() || '';
            if (!orderId) return null;
            return state.orders.find((order) => order.orderId === orderId) || null;
        };

        const renderOrderCard = (order) => {
            const isBuyLater = state.dropiFilter === 'buy_later';
            const followUpAt = order.purchaseIntent?.followUpAt;
            const canAuthorize = isOrderWaitingAuthorization(order);
            const canSubmit = isOrderWaitingDropi(order);
            const checked = state.selectedDropiOrders.has(order.orderId || '');
            const process = state.dropiProcessStatus[order.orderId || ''];
            const badge = process?.label || (isBuyLater ? (followUpAt ? 'agendado' : 'comprar depois') : order.status);
            const badgeKind = process?.kind === 'success' ? 'green'
                : process?.kind === 'error' ? 'red'
                    : process?.kind === 'manual' || process?.kind === 'running' ? 'orange'
                        : badgeClass(badge);
            const total = Number(order.total || 0);
            const amount = total ? `${order.currency || ''} ${total.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : 'sem valor';
            return `
                <article class="shipment-card order-card ${checked ? 'selected' : ''}">
                    <div class="row">
                        <label class="select-line">
                            ${canSubmit ? `<input type="checkbox" data-dropi-select="${escapeHtml(order.orderId || '')}" data-country="${escapeHtml(order.country || '')}" ${checked ? 'checked' : ''}>` : ''}
                            <span class="order-title">
                                <strong>${escapeHtml(compact(order.customer?.name, 'Cliente sem nome'))}</strong>
                                <span class="meta">${escapeHtml(order.orderId || '')} · ${escapeHtml(compact(order.customer?.phone, 'sem telefone'))}</span>
                            </span>
                        </label>
                        <span class="badge ${badgeKind}">${escapeHtml(badge || 'pedido')}</span>
                    </div>
                    <div class="order-detail-grid">
                        <div class="order-detail">
                            <span>Quantidade</span>
                            <strong>${escapeHtml(formatOrderPackageLabel(order.package))}</strong>
                        </div>
                        <div class="order-detail">
                            <span>Valor</span>
                            <strong>${escapeHtml(amount)}</strong>
                        </div>
                        <div class="order-detail">
                            <span>Cidade</span>
                            <strong>${escapeHtml(compact(order.customer?.city, 'sem cidade'))}</strong>
                        </div>
                        <div class="order-detail">
                            <span>Provincia</span>
                            <strong>${escapeHtml(compact(order.customer?.province, 'sem provincia'))}</strong>
                        </div>
                        <div class="order-detail full">
                            <span>Endereco completo</span>
                            <strong>${escapeHtml(compact(order.customer?.address, 'sem endereco'))}</strong>
                        </div>
                        <div class="order-detail full">
                            <span>Status do processo</span>
                            <strong>${escapeHtml(process?.message || (followUpAt ? 'Retomar em ' + formatTime(followUpAt) : 'Pronto para enviar para Dropi'))}</strong>
                        </div>
                    </div>
                    <div class="shipment-actions">
                        ${canAuthorize ? `<button class="primary" data-shipment-action="authorize-dropi" data-country="${escapeHtml(order.country || '')}" data-order="${escapeHtml(order.orderId || '')}" type="button">Autorizar pedido</button>` : ''}
                        ${canSubmit ? `<button class="primary" data-shipment-action="submit-dropi" data-country="${escapeHtml(order.country || '')}" data-order="${escapeHtml(order.orderId || '')}" type="button">Enviar para Dropi</button>` : ''}
                    </div>
                </article>
            `;
        };

        const getOrderProcessInfo = (order) => {
            const shipment = order.shipment || {};
            const localProcess = state.dropiProcessStatus[order.orderId || ''];
            if (localProcess) return localProcess;
            const dropiId = order.dropiOrderId || shipment.raw?.droppiOrder?.id || '';
            if (shipment.automation?.submittedToDroppiAt || dropiId) {
                return {
                    kind: 'success',
                    label: 'pedido enviado',
                    message: dropiId ? `Dropi ID ${dropiId}` : 'Enviado para Dropi'
                };
            }
            if (shipment.automation?.browserCheckpoint === 'manual_prepare_ready') {
                return {
                    kind: 'running',
                    label: 'preparado na Dropi',
                    message: 'Formulario aberto para conferir e enviar manualmente'
                };
            }
            if (needsDropiPayment(shipment)) {
                return {
                    kind: 'manual',
                    label: 'aguardando saldo',
                    message: shipment.automation?.browserLastError || 'Dropi bloqueou por saldo/credito insuficiente'
                };
            }
            if (shipment.review?.reviewStatus === 'manual_send_required' || shipment.review?.manualOnly) {
                return {
                    kind: 'manual',
                    label: 'manual',
                    message: shipment.automation?.browserLastError || 'Precisa envio manual'
                };
            }
            if (shipment.automation?.browserCheckpoint) {
                const checkpoint = shipment.automation.browserCheckpoint;
                const checkpointLabels = {
                    logged_in: 'em andamento',
                    prepared_submission: 'preparando',
                    manual_prepare_started: 'preparando',
                    manual_prepare_logged_in: 'preparando',
                    manual_prepare_ready: 'preparado na Dropi',
                    manual_prepare_failed: 'erro ao preparar',
                    dropi_payment_required: 'aguardando saldo',
                    submit_failed: 'erro'
                };
                const checkpointMessages = {
                    manual_prepare_ready: 'Formulario aberto para conferir e enviar manualmente',
                    dropi_payment_required: 'Dropi bloqueou por saldo/credito insuficiente'
                };
                return {
                    kind: checkpoint.includes('failed') ? 'error' : 'running',
                    label: checkpointLabels[checkpoint] || checkpoint,
                    message: shipment.automation?.browserLastError || checkpointMessages[checkpoint] || 'Processo iniciado'
                };
            }
            const tracking = shipment.logistics?.trackingNumber || '';
            const logisticsStatus = String(shipment.logistics?.status || '').toUpperCase();
            if (tracking || /GUIA_GENERADA|PREPARADO|PENDIENTE|MERCANCIA|BODEGA|DESPACHO|RUTA|REPARTO|READY_FOR_PICKUP|NOVEDAD|AGENCIA|ENTREGADO|DEVUELTO/.test(logisticsStatus)) {
                return {
                    kind: 'success',
                    label: tracking ? 'guia gerada' : (logisticsStatus || 'enviado'),
                    message: tracking ? `Guia ${tracking}` : 'Pedido ja saiu da fila de envio'
                };
            }
            return {
                kind: 'pending',
                label: 'pendente',
                message: 'Aguardando envio'
            };
        };

        const hasDropiGuideOrTracking = (order) => {
            const shipment = order.shipment || {};
            const status = String(shipment.logistics?.status || '').toUpperCase();
            return Boolean(shipment.logistics?.trackingNumber)
                || /GUIA_GENERADA|PREPARADO|PENDIENTE|MERCANCIA|BODEGA|DESPACHO|RUTA|REPARTO|READY_FOR_PICKUP|NOVEDAD|AGENCIA/.test(status);
        };

        const isDropiAuthorized = (order) => Boolean(order.shipment?.automation?.dropiSubmitAuthorizedAt);

        const getDropiStage = (order) => {
            const status = String(order.status || '').toLowerCase();
            const shipmentStatusValue = String(order.shipment?.logistics?.status || '').toUpperCase();
            if (['delivered', 'returned', 'cancelled'].includes(status)
                || /ENTREGADO|DEVUELTO|RETURN|CANCEL/.test(shipmentStatusValue)
                || order.shipment?.outcomes?.delivered
                || order.shipment?.outcomes?.returned) {
                return 'final';
            }
            const process = getOrderProcessInfo(order);
            if (process.kind === 'success' || hasDropiGuideOrTracking(order)) return 'sent';
            if (['manual', 'running', 'error'].includes(process.kind)) return 'review';
            if (['processing', 'shipped'].includes(status)) return 'review';
            if (status !== 'confirmed') return 'other';
            if (isDropiAuthorized(order)) return 'send';
            return 'authorize';
        };

        const isOrderWaitingAuthorization = (order) => getDropiStage(order) === 'authorize';
        const isOrderWaitingDropi = (order) => getDropiStage(order) === 'send';
        const isOrderSentDropi = (order) => getDropiStage(order) === 'sent';
        const isOrderReviewDropi = (order) => getDropiStage(order) === 'review';
        const isOrderNotSentDropi = (order) => ['authorize', 'send', 'review'].includes(getDropiStage(order));

        const orderTimeValue = (order) => {
            const value = order.entryAt || order.createdAt || order.draftCreatedAt || '';
            const time = value ? new Date(value).getTime() : 0;
            return Number.isFinite(time) ? time : 0;
        };

        const confirmedPeriodOptions = [
            ['today', 'Hoje'],
            ['yesterday', 'Ontem'],
            ['custom', 'Personalizado']
        ];

        const dateInputValue = (date = new Date()) => {
            const pad = (value) => String(value).padStart(2, '0');
            return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
        };

        const rangeFromDateInput = (value) => {
            const match = String(value || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
            if (!match) return null;
            const start = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
            if (Number.isNaN(start.getTime())) return null;
            start.setHours(0, 0, 0, 0);
            const end = new Date(start);
            end.setDate(end.getDate() + 1);
            return { start: start.getTime(), end: end.getTime() };
        };

        const orderDateValue = (order) => {
            const value = order.entryAt
                || order.createdAt
                || order.draftCreatedAt
                || order.shipment?.createdAt
                || '';
            const time = value ? new Date(value).getTime() : 0;
            return Number.isFinite(time) ? time : 0;
        };

        const periodRange = (period) => {
            if (period === 'custom') {
                return rangeFromDateInput(state.confirmedCustomDate) || periodRange('today');
            }
            const start = new Date();
            start.setHours(0, 0, 0, 0);
            const end = new Date(start);
            end.setDate(end.getDate() + 1);
            if (period === 'yesterday') {
                start.setDate(start.getDate() - 1);
                end.setDate(end.getDate() - 1);
            }
            return { start: start.getTime(), end: end.getTime() };
        };

        const isOrderInConfirmedPeriod = (order) => {
            const time = orderDateValue(order);
            if (!time) return state.confirmedPeriod !== 'today' && state.confirmedPeriod !== 'yesterday';
            const range = periodRange(state.confirmedPeriod);
            return time >= range.start && time < range.end;
        };

        const sortDropiQueueOrders = (orders) => [...orders].sort((a, b) => {
            const aPinned = state.pinnedDropiOrderIds.includes(a.orderId || '');
            const bPinned = state.pinnedDropiOrderIds.includes(b.orderId || '');
            if (aPinned !== bPinned) return aPinned ? -1 : 1;
            return orderTimeValue(b) - orderTimeValue(a);
        });

        const dropiPhoneKey = (order) => String(order.customer?.phone || '').replace(/\D/g, '').slice(-9);

        const dedupeDropiOrdersByPhone = (orders) => {
            const seen = new Set();
            return orders.filter((order) => {
                const key = dropiPhoneKey(order);
                if (!key) return true;
                if (seen.has(key)) return false;
                seen.add(key);
                return true;
            });
        };

        const processBadgeClass = (kind) => {
            if (kind === 'success') return 'sent';
            if (kind === 'manual' || kind === 'running') return 'orange';
            if (kind === 'error') return 'red';
            return '';
        };

        const orderReviewLabel = (order) => {
            const review = String(order.shipment?.review?.reviewReason
                || order.shipment?.review?.reviewStatus
                || order.reviewQueue?.reason
                || order.reviewQueue?.evidence
                || '').toLowerCase();
            const orderId = String(order.orderId || '').toUpperCase();
            const entryReason = String(order.entryReason || '').toLowerCase();
            if (orderId.includes('RECOMPRA')
                || entryReason.includes('repeat_purchase')
                || review.includes('recompra')) {
                return 'Conferir recompra';
            }
            if (review.includes('conferir')
                || review.includes('aguardando')
                || review.includes('awaiting_dropi_authorization')
                || review.includes('lead_confirmado')) {
                return 'Conferir pedido';
            }
            return '';
        };

        const renderOrderTable = (orders) => {
            const rows = orders.map((order) => {
                const inReviewModule = state.dropiFilter === 'review_orders';
                const checked = state.selectedDropiOrders.has(order.orderId || '');
                const process = getOrderProcessInfo(order);
                const stage = getDropiStage(order);
                const canAuthorize = stage === 'authorize' && !inReviewModule;
                const canSubmit = isOrderWaitingDropi(order);
                const canRetry = stage === 'review';
                const canRequeue = stage === 'review' && !hasDropiGuideOrTracking(order);
                const canPrepare = manualDropiPrepareAvailable && (stage === 'send' || stage === 'review');
                const canManualDropi = !hasDropiGuideOrTracking(order) && process.kind !== 'success';
                const canMarkManualSent = process.kind === 'manual' || order.status === 'confirmed';
                const total = Number(order.total || 0);
                const amount = total ? `${order.currency || ''} ${total.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : 'sem valor';
                const qty = formatOrderPackageLabel(order.package);
                const reviewEvidence = order.reviewQueue?.evidence || order.reviewQueue?.reason || '';
                const reviewLabel = orderReviewLabel(order);
                return `
                    <tr class="${checked ? 'selected' : ''}">
                        <td>${!inReviewModule && (canAuthorize || canSubmit) ? `<input type="checkbox" data-dropi-select="${escapeHtml(order.orderId || '')}" data-country="${escapeHtml(order.country || '')}" ${checked ? 'checked' : ''}>` : ''}</td>
                        <td class="cell-main">
                            <strong>${escapeHtml(compact(order.customer?.name, 'Cliente sem nome'))}</strong>
                            <div class="cell-sub">ID: ${escapeHtml(order.orderId || '')}</div>
                        </td>
                        <td>
                            <span class="badge ${badgeClass(order.status)}">${escapeHtml(order.status || 'pedido')}</span>
                            ${reviewLabel ? `<span class="badge orange">${escapeHtml(reviewLabel)}</span>` : ''}
                        </td>
                        <td class="cell-sub">${escapeHtml(compact(order.customer?.phone, 'sem telefone'))}</td>
                        <td class="cell-sub">
                            <strong>${escapeHtml([order.customer?.city, order.customer?.province].filter(Boolean).join(', ') || 'sem local')}</strong>
                            <div>${escapeHtml(compact(order.customer?.address, 'sem endereco'))}</div>
                        </td>
                        <td class="cell-sub">${escapeHtml(qty)}<br>${escapeHtml(amount)}</td>
                        <td>
                            <span class="badge ${inReviewModule ? 'orange' : processBadgeClass(process.kind)}">${escapeHtml(inReviewModule ? 'conferir' : process.label)}</span>
                            ${reviewLabel ? `<span class="status-note"><strong>${escapeHtml(reviewLabel)}</strong></span>` : ''}
                            <span class="status-note">${escapeHtml(inReviewModule ? (reviewEvidence || 'Conferir historico antes de enviar') : process.message)}</span>
                        </td>
                        <td>
                            <div class="order-table-actions">
                                ${!inReviewModule && stage === 'authorize' ? `<button data-shipment-action="send-to-review" data-country="${escapeHtml(order.country || '')}" data-order="${escapeHtml(order.orderId || '')}" type="button">Enviar para conferência</button>` : ''}
                                ${inReviewModule ? `<button class="primary" data-shipment-action="approve-review" data-country="${escapeHtml(order.country || '')}" data-order="${escapeHtml(order.orderId || '')}" type="button">Aprovar p/ Dropi</button>` : ''}
                                ${inReviewModule ? `<button class="danger" data-shipment-action="finalize-review" data-country="${escapeHtml(order.country || '')}" data-order="${escapeHtml(order.orderId || '')}" type="button">Arquivar</button>` : ''}
                                ${canAuthorize ? `<button class="primary" data-shipment-action="authorize-dropi" data-country="${escapeHtml(order.country || '')}" data-order="${escapeHtml(order.orderId || '')}" type="button">Autorizar</button>` : ''}
                                ${canSubmit ? `<button class="primary" data-shipment-action="submit-dropi" data-country="${escapeHtml(order.country || '')}" data-order="${escapeHtml(order.orderId || '')}" type="button">Enviar para Dropi</button>` : ''}
                                ${canRequeue ? `<button class="primary" data-shipment-action="requeue-dropi" data-country="${escapeHtml(order.country || '')}" data-order="${escapeHtml(order.orderId || '')}" type="button">Voltar p/ enviar</button>` : ''}
                                ${canPrepare ? `<button data-shipment-action="prepare-dropi" data-country="${escapeHtml(order.country || '')}" data-order="${escapeHtml(order.orderId || '')}" type="button">Preparar Dropi</button>` : ''}
                                ${canManualDropi ? `<button data-shipment-action="manual-dropi-link" data-country="${escapeHtml(order.country || '')}" data-order="${escapeHtml(order.orderId || '')}" type="button">Abrir Dropi manual</button>` : ''}
                                ${!canSubmit && canRetry ? `<button data-shipment-action="submit-dropi" data-country="${escapeHtml(order.country || '')}" data-order="${escapeHtml(order.orderId || '')}" type="button">Tentar direto</button>` : ''}
                                ${canMarkManualSent ? `<button class="success" data-shipment-action="mark-manual-sent" data-country="${escapeHtml(order.country || '')}" data-order="${escapeHtml(order.orderId || '')}" type="button">Manual enviado</button>` : ''}
                                ${process.kind !== 'success' ? `<button data-shipment-action="remove-from-confirmed" data-country="${escapeHtml(order.country || '')}" data-order="${escapeHtml(order.orderId || '')}" type="button">Remover fila</button>` : ''}
                                ${process.kind !== 'success' ? `<button data-shipment-action="manual-send-required" data-country="${escapeHtml(order.country || '')}" data-order="${escapeHtml(order.orderId || '')}" type="button">Marcar manual</button>` : ''}
                                ${process.kind !== 'success' ? `<button class="danger" data-shipment-action="delete-fake" data-country="${escapeHtml(order.country || '')}" data-order="${escapeHtml(order.orderId || '')}" type="button">Excluir fake</button>` : ''}
                            </div>
                        </td>
                    </tr>
                `;
            }).join('');
            return `
                <div class="order-table">
                    <table>
                        <thead>
                            <tr>
                                <th>Sel.</th>
                                <th>Cliente</th>
                                <th>Etapa</th>
                                <th>Contato</th>
                                <th>Localizacao / endereco</th>
                                <th>Pedido</th>
                                <th>Dropi</th>
                                <th>Acoes</th>
                            </tr>
                        </thead>
                        <tbody>${rows}</tbody>
                    </table>
                </div>
            `;
        };

        const renderShipmentCard = (shipment) => {
            const status = shipment.logistics?.status || 'sem status';
            const orderId = shipment.orderId || '';
            const canSubmit = !shipment.automation?.submittedToDroppiAt && !shipment.logistics?.trackingNumber;
            const canPrepare = manualDropiPrepareAvailable && canSubmit;
            const manualRequired = shipment.review?.reviewStatus === 'manual_send_required';
            return `
                <article class="shipment-card">
                    <div class="row">
                        <strong>${escapeHtml(orderId)}</strong>
                        <span class="badge ${manualRequired ? 'orange' : badgeClass(status)}">${escapeHtml(manualRequired ? 'envio manual' : status)}</span>
                    </div>
                    <div class="meta">${escapeHtml(compact(shipment.client?.name, 'Cliente'))} · ${escapeHtml(compact(shipment.client?.phone, 'sem telefone'))}</div>
                    <div class="meta">${escapeHtml([shipment.client?.city, shipment.client?.province].filter(Boolean).join(', ') || 'sem local')}</div>
                    <div class="meta">${escapeHtml(buildAvisos(shipment))}</div>
                    <div class="shipment-actions">
                        ${canSubmit ? `<button class="primary" data-shipment-action="submit-dropi" data-country="${escapeHtml(shipment.country || '')}" data-order="${escapeHtml(orderId)}" type="button">Enviar para Dropi</button>` : ''}
                        ${canPrepare ? `<button data-shipment-action="prepare-dropi" data-country="${escapeHtml(shipment.country || '')}" data-order="${escapeHtml(orderId)}" type="button">Preparar Dropi</button>` : ''}
                        ${manualRequired ? `<button class="success" data-shipment-action="mark-manual-sent" data-country="${escapeHtml(shipment.country || '')}" data-order="${escapeHtml(orderId)}" type="button">Marcar enviado manual</button>` : ''}
                        <button data-shipment-action="manual-send-required" data-country="${escapeHtml(shipment.country || '')}" data-order="${escapeHtml(orderId)}" type="button">Pedir envio manual</button>
                        <button data-shipment-action="panel-sync" data-order="${escapeHtml(orderId)}" type="button">Sincronizar Dropi</button>
                        <button data-shipment-action="notify-guide" data-order="${escapeHtml(orderId)}" type="button">Avisar guia</button>
                        <button data-shipment-action="notify-pickup" data-order="${escapeHtml(orderId)}" type="button">Avisar agencia</button>
                        <button data-shipment-action="request-pickup-proof" data-order="${escapeHtml(orderId)}" type="button">Pedir comprovante</button>
                        <button data-shipment-action="confirm-pickup" data-order="${escapeHtml(orderId)}" type="button">Confirmar retirada</button>
                        <button data-shipment-action="notify-bonus" data-order="${escapeHtml(orderId)}" type="button">Enviar bonus</button>
                        <button data-shipment-action="notify-returned" data-order="${escapeHtml(orderId)}" type="button">Devolvido</button>
                        ${canSubmit ? `<button class="danger" data-shipment-action="delete-fake" data-country="${escapeHtml(shipment.country || '')}" data-order="${escapeHtml(orderId)}" type="button">Excluir fake</button>` : ''}
                    </div>
                </article>
            `;
        };

        const renderDropiStagePanel = (orders) => {
            const counts = {
                authorize: orders.filter((order) => getDropiStage(order) === 'authorize').length,
                send: orders.filter((order) => getDropiStage(order) === 'send').length,
                review: orders.filter((order) => getDropiStage(order) === 'review').length,
                sent: orders.filter((order) => getDropiStage(order) === 'sent').length,
                final: orders.filter((order) => getDropiStage(order) === 'final').length
            };
            const activeByFilter = {
                confirmed: 'authorize',
                not_sent: 'send',
                progress: 'review',
                sent: 'sent'
            };
            const cards = [
                ['authorize', counts.authorize, '1 Conferir', 'cliente fechou, falta sua autorizacao'],
                ['send', counts.send, '2 Enviar para Dropi', 'autorizado e sem guia'],
                ['review', counts.review, '3 Revisar', 'erro, saldo, manual ou travado'],
                ['sent', counts.sent, '4 Enviado', 'ja tem guia/status Dropi']
            ].map(([key, count, title, subtitle]) => `
                <div class="dropi-stage ${activeByFilter[state.dropiFilter] === key ? 'active' : ''}">
                    <strong>${count}</strong>
                    <span>${escapeHtml(title)}</span>
                    <span>${escapeHtml(subtitle)}</span>
                </div>
            `).join('');
            el('dropiStagePanel').innerHTML = cards;
        };

        const renderConfirmedDropdown = (orders) => {
            const allPendingOrders = orders
                .filter((order) => ['authorize', 'send', 'review'].includes(getDropiStage(order)))
                .sort((a, b) => orderDateValue(b) - orderDateValue(a));
            const periodPendingOrders = allPendingOrders
                .filter(isOrderInConfirmedPeriod)
                .slice(0, 120);
            const periodOrders = orders.filter(isOrderInConfirmedPeriod);
            const authorizeCount = periodOrders.filter(isOrderWaitingAuthorization).length;
            const sendCount = periodOrders.filter(isOrderWaitingDropi).length;
            const reviewCount = periodOrders.filter(isOrderReviewDropi).length;
            const sentCount = periodOrders.filter(isOrderSentDropi).length;
            const periodOptions = confirmedPeriodOptions.map(([key, label]) => `
                <option value="${key}" ${state.confirmedPeriod === key ? 'selected' : ''}>${label}</option>
            `).join('');
            const customDate = state.confirmedCustomDate || dateInputValue();
            const rows = periodPendingOrders.map((order) => {
                const stage = getDropiStage(order);
                const process = getOrderProcessInfo(order);
                const reviewLabel = orderReviewLabel(order);
                const actionLabel = stage === 'authorize'
                    ? 'Liberar'
                    : stage === 'send'
                    ? 'Enviar'
                    : stage === 'review'
                    ? 'Revisar'
                    : 'Enviado';
                const action = stage === 'authorize'
                    ? 'authorize-dropi'
                    : stage === 'send'
                    ? 'submit-dropi'
                    : '';
                const amount = Number(order.total || 0)
                    ? `${order.currency || ''} ${Number(order.total || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
                    : 'sem valor';
                const actionButton = action
                    ? `<button class="primary" data-shipment-action="${action}" data-country="${escapeHtml(order.country || '')}" data-order="${escapeHtml(order.orderId || '')}" type="button">${actionLabel}</button>`
                    : `<button data-confirmed-stage="${escapeHtml(stage)}" type="button">${actionLabel}</button>`;
                const removeButton = process.kind !== 'success'
                    ? `<button data-shipment-action="remove-from-confirmed" data-country="${escapeHtml(order.country || '')}" data-order="${escapeHtml(order.orderId || '')}" type="button">Remover fila</button>`
                    : '';
                return `
                    <div class="confirmed-mini-row">
                        <div class="truncate">
                            <strong>${escapeHtml(compact(order.customer?.name, 'Cliente sem nome'))}</strong>
                            ${reviewLabel ? `<span class="badge orange">${escapeHtml(reviewLabel)}</span>` : ''}
                            <span class="meta">${escapeHtml(order.orderId || '')} · ${escapeHtml(compact(order.customer?.phone, 'sem telefone'))}</span>
                            <span class="meta">${escapeHtml([order.customer?.city, order.customer?.province].filter(Boolean).join(', ') || 'sem local')} · ${escapeHtml(formatOrderPackageLabel(order.package))} · ${escapeHtml(amount)}</span>
                            <span class="meta">${escapeHtml(process.message || process.label || '')}</span>
                        </div>
                        <div class="order-table-actions">${actionButton}${removeButton}</div>
                    </div>
                `;
            }).join('');
            el('confirmedDropdownPanel').innerHTML = `
                <details class="confirmed-dropdown" open>
                    <summary>
                        <span>Pedidos confirmados para Dropi</span>
                        <span class="badge ${periodPendingOrders.length ? 'orange' : 'green'}">${periodPendingOrders.length} de ${allPendingOrders.length}</span>
                    </summary>
                    <div class="confirmed-dropdown-body">
                        <div class="confirmed-periods">
                            <select id="confirmedPeriodSelect" aria-label="Periodo dos pedidos confirmados">
                                ${periodOptions}
                            </select>
                            <input id="confirmedCustomDateInput" type="date" value="${escapeHtml(customDate)}" ${state.confirmedPeriod === 'custom' ? '' : 'hidden'} aria-label="Data personalizada">
                            <button id="confirmedRefreshBtn" type="button">Atualizar</button>
                        </div>
                        <div class="confirmed-summary-grid">
                            <button class="confirmed-stage-pill" data-confirmed-stage="authorize" type="button"><strong>${authorizeCount}</strong><span>Conferir</span></button>
                            <button class="confirmed-stage-pill" data-confirmed-stage="send" type="button"><strong>${sendCount}</strong><span>Enviar</span></button>
                            <button class="confirmed-stage-pill" data-confirmed-stage="review" type="button"><strong>${reviewCount}</strong><span>Revisar</span></button>
                            <button class="confirmed-stage-pill" data-confirmed-stage="sent" type="button"><strong>${sentCount}</strong><span>Enviados</span></button>
                        </div>
                        <div class="meta">Mostra somente pedidos ainda pendentes de acao. Enviados ficam no estagio Enviados; entregues/devolvidos saem desta fila.</div>
                        <div class="confirmed-mini-list">${rows || '<div class="empty">Nenhum pedido pendente de acao neste periodo.</div>'}</div>
                    </div>
                </details>
            `;
        };

        const renderShipments = () => {
            const filtered = state.dropiItems.filter(matchesSelectedOrSearch).slice(0, 30);
            const allLoadedOrders = state.orders.length
                ? state.orders
                : state.dropiItems.filter((item) => item.type === 'order').map((item) => item.order);
            renderDropiStagePanel(allLoadedOrders);
            renderConfirmedDropdown(allLoadedOrders);
            if (['all_dropi', 'confirmed', 'not_sent', 'sent', 'progress', 'review_orders'].includes(state.dropiFilter)) {
                const orders = sortDropiQueueOrders(filtered.filter((item) => item.type === 'order').map((item) => item.order));
                el('shipmentList').innerHTML = orders.length
                    ? renderOrderTable(orders)
                    : `<div class="empty">Nenhum item em ${escapeHtml(dropiFilterLabels[state.dropiFilter] || 'Dropi')}.</div>`;
            } else {
                el('shipmentList').innerHTML = filtered.map((item) => (
                    item.type === 'order' ? renderOrderCard(item.order) : renderShipmentCard(item.shipment)
                )).join('') || `<div class="empty">Nenhum item em ${escapeHtml(dropiFilterLabels[state.dropiFilter] || 'Dropi')}.</div>`;
            }

            const visibleOrderIds = new Set(filtered
                .filter((item) => item.type === 'order' && !isBrazilTestRecord(item.order) && (isOrderWaitingDropi(item.order) || isOrderWaitingAuthorization(item.order)))
                .map((item) => item.order.orderId)
                .filter(Boolean));
            state.selectedDropiOrders.forEach((orderId) => {
                if (!state.dropiItems.some((item) => item.type === 'order' && item.order?.orderId === orderId)) {
                    state.selectedDropiOrders.delete(orderId);
                }
            });
            const selectedVisible = [...state.selectedDropiOrders].filter((orderId) => visibleOrderIds.has(orderId)).length;
            const selectedTotal = state.selectedDropiOrders.size;
            const allConfirmedIds = state.dropiItems
                .filter((item) => item.type === 'order' && (state.dropiFilter === 'confirmed'
                    ? isOrderWaitingAuthorization(item.order)
                    : isOrderWaitingDropi(item.order)) && !isBrazilTestRecord(item.order))
                .map((item) => item.order.orderId)
                .filter(Boolean);
            const stats = state.dropiOrderStats || {};
            const waitingCount = Number.isFinite(stats.waiting) ? stats.waiting : allLoadedOrders.filter(isOrderWaitingDropi).length;
            const authorizationCount = Number.isFinite(stats.authorization) ? stats.authorization : allLoadedOrders.filter(isOrderWaitingAuthorization).length;
            const sentCount = Number.isFinite(stats.sent) ? stats.sent : allLoadedOrders.filter(isOrderSentDropi).length;
            const reviewCount = Number.isFinite(stats.review) ? stats.review : allLoadedOrders.filter(isOrderReviewDropi).length;
            const totalCount = Number.isFinite(stats.total) ? stats.total : allLoadedOrders.length;
            const selectedIds = [...state.selectedDropiOrders].sort();
            const processLines = Object.entries(state.dropiProcessStatus)
                .slice(-20)
                .map(([orderId, info]) => `${orderId}: ${info.message || info.label || ''}`);
            el('bulkDropiBar').style.display = ['confirmed', 'not_sent'].includes(state.dropiFilter) ? 'grid' : 'none';
            el('bulkDropiSummary').textContent = selectedTotal
                ? `${selectedTotal} pedido(s) selecionado(s). ${selectedVisible} visivel(is) nesta lista.`
                : state.dropiFilter === 'confirmed'
                    ? `${allConfirmedIds.length} pedido(s) para conferir e autorizar.`
                    : `${allConfirmedIds.length} pedido(s) autorizados para enviar para Dropi.`;
            el('bulkDropiSelectedList').textContent = selectedIds.length
                ? `Selecionados: ${selectedIds.join(', ')}${processLines.length ? '\n\nProcessamento:\n' + processLines.join('\n') : ''}`
                : processLines.length ? `Processamento:\n${processLines.join('\n')}`
                : 'Nenhum pedido selecionado.';
            el('processSelectedDropiBtn').disabled = state.busy || selectedTotal === 0;
            el('selectAllDropiBtn').disabled = state.busy || allConfirmedIds.length === 0;
            el('selectVisibleDropiBtn').disabled = state.busy || visibleOrderIds.size === 0;
            el('clearDropiSelectionBtn').disabled = state.busy || selectedTotal === 0;

            el('processSelectedDropiBtn').textContent = state.dropiFilter === 'confirmed'
                ? 'Autorizar selecionados'
                : 'Enviar selecionados para Dropi';

            renderOperationalMetrics();
            el('metricDropi').textContent = String(sentCount);
            el('metricReview').textContent = String(reviewCount || state.dropiItems.filter((item) => (
                item.type === 'shipment' && (item.shipment.review?.manualOnly || !item.shipment.logistics?.trackingNumber)
            )).length);
            const countryLabel = selectedOperationalCountry();
            if (state.dropiFilter === 'review_orders') {
                el('processSummary').textContent = `${filtered.length} pedido(s) em painel tecnico. Aprove somente apos revisar historico.`;
            } else if (['all_dropi', 'confirmed', 'not_sent', 'sent', 'progress'].includes(state.dropiFilter)) {
                el('processSummary').textContent = `${totalCount} pedido(s): ${authorizationCount} para conferir, ${waitingCount} autorizados para Dropi, ${reviewCount} revisar, ${sentCount} enviados em ${countryLabel}.`;
            } else if (state.dropiFilter === 'buy_later') {
                el('processSummary').textContent = `${filtered.length} oportunidade(s) para retomar em ${countryLabel}.`;
            } else {
