                || ((previousSave, operation) => Promise.resolve(previousSave).catch(() => undefined).then(operation));
            const queuedSelectionScope = captureCustomerSelectionScope();
            const queuedEditRevision = state.customerFormEditRevision;
            const queuedSave = queueSave(
