        // V218: default only the year; day/month remain an explicit operator choice.
        function syncBuyLaterDatePartsV218() {
            const value = el('customerBuyLaterDateInput').value;
            const parts = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
            el('customerBuyLaterDayInput').value = parts ? String(Number(parts[3])) : '';
            el('customerBuyLaterMonthInput').value = parts ? String(Number(parts[2])) : '';
            el('customerBuyLaterYearInput').value = parts ? parts[1] : String(new Date().getFullYear());
        }
        const updateBuyLaterDatePartsV218 = () => {
            const day = el('customerBuyLaterDayInput');
            const month = el('customerBuyLaterMonthInput');
            const year = el('customerBuyLaterYearInput');
            const values = [year, month, day];
            const complete = values.every((field) => field.value && field.validity.valid)
                && /^\d{4}$/.test(year.value);
            const iso = complete ? `${year.value}-${month.value.padStart(2, '0')}-${day.value.padStart(2, '0')}` : '';
            el('customerBuyLaterDateInput').value = iso;
            stageBuyLaterEditV217();
        };
        const focusBuyLaterDateV218 = () => el('customerBuyLaterDayInput').focus();

        // V217: editing the segmented native date must never confirm or persist a status.
        const completeBuyLaterDateV217 = () => {
            const input = el('customerBuyLaterDateInput');
            const value = input?.value || '';
            if (!/^\d{4}-\d{2}-\d{2}$/.test(value) || !input.validity.valid) return false;
            const [year, month, day] = value.split('-').map(Number);
            if (year < 1000 || year > 9999) return false;
            const date = new Date(Date.UTC(year, month - 1, day));
            return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day;
        };
        const stageBuyLaterEditV217 = () => {
            if (!state.selectedChat || normalizePanelStatus(el('customerStatusInput').value) !== 'comprar_depois') return false;
            window.clearTimeout(state.statusAutoSaveTimer);
            window.clearTimeout(state.customerFieldAutoSaveTimer);
            state.statusAutoSaveSeq += 1;
            state.customerFieldAutoSaveSeq += 1;
            markCustomerFormDirty();
            el('customerSyncHint').textContent = completeBuyLaterDateV217()
                ? 'Data em edição. Clique em Salvar dados para confirmar o agendamento.'
                : 'Preencha dia e mês; o ano atual já está preenchido. Depois clique em Salvar dados.';
            el('customerSyncBadge').textContent = 'aguarda salvar';
            el('customerSyncBadge').className = 'badge orange';
            return true;
        };

