        async function processManualMessageQueue() {
            const now = Date.now();
            const queueRunningMs = now - Number(state.manualMessageQueueStartedAt || 0);
            if (state.manualMessageQueueProcessing && queueRunningMs < 45000) return;
            if (state.manualMessageQueueProcessing) {
                console.warn('[PANEL_SEND_QUEUE] fila manual destravada por timeout', {
                    queueRunningMs,
                    pending: (state.manualMessageQueue || []).length
                });
                state.manualMessageQueueProcessing = false;
            }
            state.manualMessageQueueProcessing = true;
            state.manualMessageQueueStartedAt = Date.now();
            state.sendingMessage = true;
            updateMessageComposerControls();
            try {
                while ((state.manualMessageQueue || []).length) {
                    const item = state.manualMessageQueue[0];
                    markPendingLocalMessageStatus(item.pendingId, 'sending');
                    try {
                        const result = await api('/api/whatsapp/send', {
                            method: 'POST',
                            body: JSON.stringify({
                                phone: item.phone,
                                message: item.text,
                                sessionId,
                                delayTypingSeconds: Number.isFinite(Number(item.delayTypingSeconds)) ? Number(item.delayTypingSeconds) : 0,
                                quotedMessageId: item.replyToId || '',
                                clientGeneratedId: item.pendingId || '',
                                sendMode: 'manual_panel',
                                country: state.country || 'EC'
                            })
                        });
                        if (!result?.success) {
                            throw new Error(result?.error || 'WhatsApp nao confirmou o envio. Verifique a conexao do celular.');
                        }
                        if (result?.handled) {
                            showToast(result.message || 'Comando aplicado');
                        }
                        if (item.pendingId && !result?.handled) confirmPendingLocalMessage(item.pendingId, result);
                        state.manualMessageQueue.shift();
                        loadSelectedMessages({ force: true }).catch(() => null);
                        window.setTimeout(() => loadActionableSamples().catch(() => null), 600);
                        loadChats().catch(() => null);
                    } catch (error) {
                        markPendingLocalMessageStatus(item.pendingId, 'request_failed', error.message);
                        state.manualMessageQueue.shift();
                        if (!String(el('messageInput')?.value || '').trim()) {
                            el('messageInput').value = item.text;
                        }
                        showToast(`Mensagem nao enviada; texto preservado: ${error.message}`);
                        break;
                    }
                }
            } finally {
                state.manualMessageQueueProcessing = false;
                state.manualMessageQueueStartedAt = 0;
                state.sendingMessage = (state.manualMessageQueue || []).length > 0;
                updateMessageComposerControls();
                el('messageInput').focus();
            }
        }

        async function sendMessage(event) {
            if (!event?.isTrusted || state.sendingMessage) return;
            if (state.editingOutboundMessage) return saveEditedOutboundMessage();
            const input = el('messageInput');
            const text = String(input.value || '').trim();
            if (!text) return;
            const shipmentPolicy = state.customerProfile?.shipment;
            if (
                window.VitalismenCleanChatV29?.containsPickupAuthorizationLanguage(text)
                && shipmentPolicy?.allowPickupLanguage !== true
            ) {
                showToast('PEDIDO AINDA NÃO ESTÁ LIBERADO PARA RETIRADA');
                return;
            }
            const replyTo = state.replyToMessage;
            const phone = currentChatPhone();
            if (!digitsOnlyText(phone)) {
                showToast('Selecione o cliente novamente: telefone da conversa nao foi localizado.');
                return;
            }
            const fingerprint = `${phone}:${text}:${replyTo?._id || ''}`;
            const now = Date.now();
            if (state.lastManualSendFingerprint === fingerprint && now - Number(state.lastManualSendAt || 0) < 2500) {
                return;
            }
            const internalPanelCommand = isInternalPanelCommandText(text);
            state.lastManualSendFingerprint = fingerprint;
            state.lastManualSendAt = now;
            input.value = '';
            state.sendingMessage = true;
            updateMessageComposerControls();
            const pending = internalPanelCommand
                ? null
                : appendLocalMessage(text, {
                    quotedMessage: replyTo,
                    deliveryStatus: 'sending'
                });
            clearReplyToMessage();
            try {
                const result = await api('/api/whatsapp/send', {
                    method: 'POST',
                    body: JSON.stringify({
                        phone: digitsOnlyText(phone),
                        message: text,
                        sessionId,
                        delayTypingSeconds: 0,
                        quotedMessageId: replyTo?._id || '',
                        clientGeneratedId: pending?.clientGeneratedId || '',
                        manualIntent: { confirmed: true, actionId: pending?.clientGeneratedId || '' },
                        sendMode: 'manual_panel',
                        country: state.country || 'EC'
                    })
                });
                if (result?.reconcileRequired) {
                    const error = new Error('Resultado incerto; conferir no WhatsApp antes de qualquer nova acao.');
                    error.response = result;
                    throw error;
                }
                if (!result?.success) {
                    throw new Error(result?.error || 'WhatsApp nao confirmou o envio. Verifique a conexao do celular.');
                }
                if (pending?._id) confirmPendingLocalMessage(pending._id, result);
                if (result?.handled) {
                    showToast(result.message || 'Comando aplicado');
                    if (pending?._id) removePendingLocalMessage(pending._id);
                }
                loadSelectedMessages({ force: true }).catch(() => null);
                loadChats().catch(() => null);
                window.setTimeout(() => loadActionableSamples().catch(() => null), 600);
            } catch (error) {
                if (error.response?.reconcileRequired) {
                    markPendingLocalMessageStatus(pending?._id, 'request_failed', 'Aguardando reconciliacao manual; nao reenviar.');
                    showToast('Resultado incerto; confira a conversa no WhatsApp. Nenhum reenvio automatico sera feito.');
                    return;
                }
                markPendingLocalMessageStatus(pending?._id, 'request_failed', error.message);
                if (!String(input.value || '').trim()) {
                    input.value = text;
                }
                showToast(`Mensagem nao enviada; texto preservado: ${error.message}`);
            } finally {
                state.sendingMessage = false;
                updateMessageComposerControls();
                input.focus();
            }
        }

        async function saveEditedOutboundMessage() {
            const editing = state.editingOutboundMessage;
            const input = el('messageInput');
            const text = String(input?.value || '').trim();
            if (!editing || !input || !text) return;
            if (text === String(editing.originalBody || '').trim()) {
                showToast('Altere o texto antes de salvar a edição.');
                return;
            }
            const phone = currentChatPhone();
            if (!digitsOnlyText(phone)) {
                showToast('Selecione o cliente novamente: telefone da conversa nao foi localizado.');
                return;
            }
            state.sendingMessage = true;
            updateMessageComposerControls();
            try {
                const result = await api(`/api/whatsapp/messages/${encodeURIComponent(phone)}/edit`, {
                    method: 'POST',
                    body: JSON.stringify({ messageId: editing.id, message: text })
                });
                if (!result?.success) throw new Error(result?.error || 'WhatsApp nao confirmou a edição.');
                const editedAt = result.editedAt || new Date().toISOString();
                state.currentMessages = (state.currentMessages || []).map((message) => (
                    String(message._id || '') === String(editing.id)
                        ? { ...message, body: result.body || text, editedAt, editCount: result.editCount || Number(message.editCount || 0) + 1 }
                        : message
                ));
                state.messageSignature = getMessageSignature(state.currentMessages);
                renderMessages(state.currentMessages, { preserveScroll: true });
                input.value = '';
                state.editingOutboundMessage = null;
