        const mimeFromFileName = (name = '') => {
            const ext = String(name || '').toLowerCase().split('.').pop() || '';
            const map = {
                jpg: 'image/jpeg',
                jpeg: 'image/jpeg',
                png: 'image/png',
                webp: 'image/webp',
                gif: 'image/gif',
                heic: 'image/heic',
                heif: 'image/heif',
                mp3: 'audio/mpeg',
                mpeg: 'audio/mpeg',
                ogg: 'audio/ogg',
                opus: 'audio/ogg',
                m4a: 'audio/mp4',
                aac: 'audio/aac',
                wav: 'audio/wav',
                webm: 'video/webm',
                mp4: 'video/mp4',
                mov: 'video/quicktime'
            };
            return map[ext] || '';
        };

        const effectiveFileMime = (file) => {
            const explicit = String(file?.type || '').toLowerCase();
            if (explicit && explicit !== 'application/octet-stream') return explicit;
            return mimeFromFileName(file?.name || '') || explicit;
        };

        const mediaKindFromFile = (file) => {
            const mime = effectiveFileMime(file);
            if (mime.startsWith('image/')) return 'imagem';
            if (mime.startsWith('video/')) return 'video';
            if (mime.startsWith('audio/')) return 'audio';
            return 'midia';
        };

        const mediaTypeFromFile = (file) => {
            const mime = effectiveFileMime(file);
            if (mime.startsWith('image/')) return 'image';
            if (mime.startsWith('video/')) return 'video';
            if (mime.startsWith('audio/')) return 'audio';
            return 'media';
        };

        const manualTypingDelaySeconds = (text = '') => {
            const chars = String(text || '').trim().length;
            if (!chars) return 0;
            return Math.max(2, Math.min(12, Math.ceil(chars / 18)));
        };

        const manualRecordingDelaySeconds = (file) => {
            const kind = mediaTypeFromFile(file);
            if (kind === 'audio') return 6;
            if (kind === 'video') return 4;
            if (kind === 'image') return 2;
            return 2;
        };

        const readFileAsDataUrl = (file) => new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = () => {
                const value = String(reader.result || '');
                const mime = effectiveFileMime(file);
                if (mime && value.startsWith('data:application/octet-stream;')) {
                    resolve(value.replace(/^data:application\/octet-stream;/, `data:${mime};`));
                    return;
                }
                if (mime && value.startsWith('data:;')) {
                    resolve(value.replace(/^data:;/, `data:${mime};`));
                    return;
                }
                resolve(value);
            };
            reader.onerror = () => reject(reader.error || new Error('Nao foi possivel ler o arquivo.'));
            reader.readAsDataURL(file);
        });

