                    : result.manualSendRequired
                    ? {
                        kind: 'manual',
                        label: 'envio manual',
                        message: result.message || 'Dropi pediu revisao. Veja o motivo no status do pedido.'
                    }
                    : {
                        kind: 'success',
                        label: 'pedido enviado',
