                    state.selectedChat.orderId = duplicateOrderId;
                    state.selectedChat.country = duplicateCountry;
                    setInputValue('customerOrderInput', duplicateOrderId);
                    if (!confirmManualDropiAction(duplicateOrderId, duplicateCountry, 'authorize-dropi')) return;
                    activeDropiOrderId = duplicateOrderId;
                    state.dropiProcessStatus[duplicateOrderId] = {
                        kind: 'running',
                        label: 'autorizando',
                        message: `Pedido ativo encontrado: ${duplicateOrderId}. Autorizando para etapa 2 Enviar para Dropi...`
                    };
                    el('detailDropi').textContent = `Pedido ativo encontrado: ${duplicateOrderId}. Autorizando para etapa 2 Enviar para Dropi...`;
                    state.dropiFilter = 'confirmed';
                    document.querySelectorAll('[data-dropi-filter]').forEach((item) => item.classList.toggle('active', item.dataset.dropiFilter === 'confirmed'));
                    renderShipments();
                    await authorizeDropiOrder(duplicateOrderId, duplicateCountry);
                    state.dropiProcessStatus[duplicateOrderId] = {
                        kind: 'pending',
                        label: 'autorizado',
                        message: 'Pedido autorizado. Agora clique novamente para enviar para Dropi.'
                    };
                    el('detailDropi').textContent = 'Pedido autorizado. Agora clique novamente para enviar para Dropi.';
                    showToast('Pedido autorizado. Agora clique novamente para enviar para Dropi.');
                    state.dropiFilter = 'not_sent';
                    document.querySelectorAll('[data-dropi-filter]').forEach((item) => item.classList.toggle('active', item.dataset.dropiFilter === 'not_sent'));
                    renderShipments();
                    await Promise.all([loadShipments(), loadChats()]);
                    return;
                }
                if (activeDropiOrderId) {
                    state.dropiProcessStatus[activeDropiOrderId] = {
                        kind: 'error',
                        label: 'erro',
                        message: error.message || 'Erro ao processar na Dropi'
                    };
                    renderShipments();
                }
                showToast(error.message);
            } finally {
                state.busy = false;
                renderSelectedDetails();
            }
        }

