        const localSearchHasMatch = (query = '') => dedupeChatsForPanel(state.chats)
            .some((chat) => chatMatchesSearch(chat, query));

        const runRemoteChatSearch = async (query, sequence) => {
            const descriptor = window.VitalismenRemoteChatSearchV65?.queryDescriptor?.(query) || { valid: false };
            if (!descriptor.valid || !state.token || localSearchHasMatch(query)) {
                if (sequence === state.remoteChatSearch.sequence) {
                    state.remoteChatSearch.loading = false;
                    state.remoteChatSearch.results = [];
                    state.remoteChatSearch.error = '';
                    renderChats();
                }
                return;
            }
            try {
                const response = await api(`/api/whatsapp/chats/search?q=${encodeURIComponent(query)}&limit=12`);
                if (sequence !== state.remoteChatSearch.sequence) return;
                state.remoteChatSearch.results = Array.isArray(response?.results)
                    ? response.results.map(mergeSavedCustomerDraftIntoChat)
                    : [];
                state.remoteChatSearch.error = '';
            } catch (error) {
                if (sequence !== state.remoteChatSearch.sequence) return;
                state.remoteChatSearch.results = [];
                state.remoteChatSearch.error = String(error?.message || 'falha de consulta');
            } finally {
                if (sequence === state.remoteChatSearch.sequence) {
                    state.remoteChatSearch.loading = false;
                    renderChats();
                }
            }
        };

        const scheduleRemoteChatSearch = () => {
            const query = String(el('chatSearch')?.value || '').trim().toLowerCase();
            const descriptor = window.VitalismenRemoteChatSearchV65?.queryDescriptor?.(query) || { valid: false };
            window.clearTimeout(state.remoteChatSearch.timer);
            state.remoteChatSearch.sequence += 1;
            const sequence = state.remoteChatSearch.sequence;
            state.remoteChatSearch.query = query;
            state.remoteChatSearch.error = '';
            if (!descriptor.valid || localSearchHasMatch(query)) {
                state.remoteChatSearch.results = [];
                state.remoteChatSearch.loading = false;
                renderChats();
                return;
            }
            state.remoteChatSearch.results = [];
            state.remoteChatSearch.loading = true;
            renderChats();
            state.remoteChatSearch.timer = window.setTimeout(
                () => runRemoteChatSearch(query, sequence),
