        const removePendingLocalMessage = (messageId) => {
            const id = String(messageId || '');
            if (!id) return;
            state.pendingLocalMessages = (state.pendingLocalMessages || []).filter((message) => String(message._id || '') !== id);
            state.currentMessages = (state.currentMessages || []).filter((message) => String(message._id || '') !== id);
            state.messageSignature = getMessageSignature(state.currentMessages);
            renderMessages(state.currentMessages, { preserveScroll: true });
        };

        const confirmPendingLocalMessage = (messageId, result = {}) => {
            const id = String(messageId || '');
            if (!id) return;
            const providerMessageId = String(result.providerMessageId || '').trim();
            const providerZaapId = String(result.providerZaapId || '').trim();
            const requestedStatus = String(result.deliveryStatus || '').trim().toLowerCase();
            const providerAccepted = ['provider_accepted', 'pending_confirmation'].includes(requestedStatus);
            const deliveryStatus = providerAccepted && !(providerMessageId || providerZaapId)
                ? 'request_failed'
                : (requestedStatus || 'request_failed');
            state.pendingLocalMessages = (state.pendingLocalMessages || []).map((message) => (
                String(message._id || '') === id
                    ? {
                        ...message,
                        _id: result.messageRecordId || message._id,
                        providerMessageId: providerMessageId || message.providerMessageId || '',
                        providerZaapId: providerZaapId || message.providerZaapId || '',
                        deliveryStatus,
                        sendError: deliveryStatus === 'request_failed'
                            ? (result.error || 'A Z-API não retornou um ID válido; envio não confirmado.')
                            : ''
                    }
                    : message
            ));
        };

        const inferMediaType = (attachment = {}) => {
            const explicit = String(attachment.type || '').toLowerCase();
            const url = String(attachment.mediaUrl || attachment.url || '').toLowerCase();
            if (/\.(jpe?g|png|webp|gif|heic|heif)(\?|#|$)/.test(url)) return 'image';
            if (/\.(mp3|ogg|opus|webm|m4a|aac|wav)(\?|#|$)/.test(url)) return 'audio';
            if (/\.(mp4|mov|m4v|avi|mkv)(\?|#|$)/.test(url)) return 'video';
            if (explicit && explicit !== 'media') return explicit;
            return explicit || 'media';
        };

        const panelMediaPath = (url = '') => {
            const value = String(url || '');
            if (!value) return value;
            const normalized = value.replace(/\\/g, '/');
            const marker = '/public/media/';
            const index = normalized.indexOf(marker);
            if (index !== -1) return `/media/${normalized.slice(index + marker.length)}`;
            return value;
        };

        const mediaUrlWithVersion = (url = '') => {
            const value = panelMediaPath(url);
            if (!value || !value.startsWith('/media/')) return value;
            return `${value}${value.includes('?') ? '&' : '?'}v=mediafix-20260517`;
        };

        const mediaPublicOrigin = () => {
            const host = String(window.location.hostname || '').toLowerCase();
            if (host === 'maxlien.shop' || host === 'www.maxlien.shop') return 'https://ec.maxlien.shop';
            return window.location.origin;
        };

        const absoluteMediaUrl = (url = '') => {
            const value = mediaUrlWithVersion(url);
            if (!value || /^(data:|blob:)/i.test(value)) return value;
            if (/^https?:\/\//i.test(value)) {
                try {
                    const parsed = new URL(value);
                    const sameSite = ['ec.maxlien.shop', 'maxlien.shop', window.location.hostname].includes(parsed.hostname);
                    return sameSite ? value : `/api/whatsapp/media-proxy?url=${encodeURIComponent(value)}`;
                } catch {
                    return value;
