        const protectedMediaRuntime = window.VitalismenAuthenticatedMedia;
        const authenticatedMediaObjectUrls = new Map();

        const clearAuthenticatedMediaObjectUrls = () => {
            for (const pending of authenticatedMediaObjectUrls.values()) {
                Promise.resolve(pending).then((objectUrl) => {
