        const markAuthenticatedMediaFailure = (node, reason = '') => {
            const shell = node.closest('[data-media-shell], [data-audio-player]');
            if (!shell) return;
            const kind = shell.dataset.mediaKind || 'media';
            const fallback = shell.querySelector('[data-auth-media-fallback]');
            if (fallback) {
                fallback.textContent = protectedMediaRuntime?.failureText({ kind, reason })
                    || mediaHealthFallbackText({}, kind, reason);
                fallback.classList.remove('hidden');
            }
            shell.classList.add('media-auth-error');
            const button = shell.querySelector('.wa-audio-play');
            if (button) button.disabled = true;
            const time = shell.querySelector('.wa-audio-time');
            if (time && (kind === 'audio' || kind === 'ptt')) time.textContent = 'Áudio indisponível';
            if (node.matches('img, video')) node.style.display = 'none';
