        const hydrateAuthenticatedMedia = (scope = document) => {
            if (!protectedMediaRuntime?.fetchObjectUrl || !state.token) return;
            scope.querySelectorAll('[data-auth-media-src]:not([data-auth-media-hydrated])').forEach((node) => {
                const source = node.dataset.authMediaSrc || '';
                if (!source) return;
                node.dataset.authMediaHydrated = 'pending';
                authenticatedMediaObjectUrl(source).then((objectUrl) => {
                    node.src = objectUrl;
                    node.dataset.authMediaHydrated = 'ready';
                    const shell = node.closest('[data-media-shell], [data-audio-player]');
                    shell?.querySelectorAll('[data-auth-media-link]').forEach((link) => {
                        link.href = objectUrl;
                    });
                    const fallback = shell?.querySelector('[data-auth-media-fallback]');
                    fallback?.classList.add('hidden');
                    const button = shell?.querySelector('.wa-audio-play');
                    if (button) button.disabled = false;
                    if (node.tagName === 'AUDIO' || node.tagName === 'VIDEO') node.load();
                }).catch((error) => {
