        const insertAtCursor = (field, text) => {
            if (!field || !text) return false;
            const currentValue = String(field.value || '');
            const selectionStart = Number(field.selectionStart);
            const selectionEnd = Number(field.selectionEnd);
            const start = Number.isFinite(selectionStart) ? selectionStart : currentValue.length;
            const end = Number.isFinite(selectionEnd) ? selectionEnd : currentValue.length;
            field.value = `${currentValue.slice(0, start)}${text}${currentValue.slice(end)}`;
            const next = start + text.length;
            field.focus();
            if (typeof field.setSelectionRange === 'function') field.setSelectionRange(next, next);
            try {
                field.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'insertText', data: text }));
            } catch {
                field.dispatchEvent(new Event('input', { bubbles: true }));
            }
            updateMessageComposerControls();
            return true;
