        const hideEmojiPanel = () => el('emojiPanel')?.classList.add('hidden');

        const renderEmojiPanel = () => {
            const panel = el('emojiPanel');
            if (!panel) return;
            const activeKey = panel.dataset.emojiCategory || 'faces';
            const query = String(el('emojiSearchInput')?.value || '').trim().toLowerCase();
