            const source = query
                ? emojiCategories.flatMap((category) => category.emojis.map((emoji) => ({ emoji, label: category.label })))
                    .filter((item) => item.emoji.includes(query) || item.label.toLowerCase().includes(query))
                    .map((item) => item.emoji)
                : activeCategory.emojis;
