                    ${uniqueEmojis.map((emoji) => `<button data-emoji="${escapeHtml(emoji)}" type="button" title="${escapeHtml(emoji)}">${escapeHtml(emoji)}</button>`).join('')}
                </div>
                <div class="emoji-panel-footer">
                    <button data-emoji-category="faces" type="button" title="Emoji">☺</button>
                    <button data-emoji-category="sales" type="button" title="Vendas">GIF</button>
                    <button data-emoji-category="symbols" type="button" title="Simbolos">◔</button>
                </div>
            `;
            el('emojiSearchInput')?.focus();
        };

        const toggleEmojiPanel = () => {
            const panel = el('emojiPanel');
            if (!panel) return;
            const opening = panel.classList.contains('hidden');
            if (opening) {
                panel.dataset.emojiCategory = panel.dataset.emojiCategory || 'faces';
                renderEmojiPanel();
                panel.classList.remove('hidden');
                return;
            }
            hideEmojiPanel();
        };

        const renderMediaAttachment = (attachment, message = {}) => {
            const mediaUrl = attachment?.mediaUrl || '';
            const type = inferMediaType(attachment);
            const label = escapeHtml(attachment.label || attachment.type || 'midia');
            if (!mediaUrl) {
                const typeLabel = type === 'audio' || type === 'ptt'
                    ? 'Audio'
                    : type === 'image'
                        ? 'Imagem'
                        : type === 'video'
                            ? 'Video'
                            : 'Midia';
                return `<div class="message-media-fallback">${escapeHtml(typeLabel)} registrado no WhatsApp, aguardando espelho do arquivo no painel</div>`;
            }
            const originalUrl = absoluteMediaUrl(mediaUrl);
            const previewUrl = attachment.mediaPreviewUrl ? absoluteMediaUrl(attachment.mediaPreviewUrl) : '';
            const src = escapeHtml(previewUrl || originalUrl);
            const original = escapeHtml(originalUrl);
            if (mediaHealthBlocksRendering(message)) {
                return `<div class="message-media-fallback">${escapeHtml(mediaHealthFallbackText(message, type))}</div>`;
            }
            if (type === 'audio' || type === 'ptt') {
                const audioSourceUrl = audioPrimarySourceUrl({
                    mediaUrl,
                    previewUrl: attachment.mediaPreviewUrl || ''
                }) || originalUrl;
                const fallbackUrl = audioFallbackUrl(audioSourceUrl) || (audioSourceUrl !== originalUrl ? originalUrl : '');
                const audioSrc = escapeHtml(audioSourceUrl);
                const fallback = escapeHtml(fallbackUrl);
                const protectedSource = isProtectedPanelMediaUrl(audioSourceUrl);
                return `
                    <div class="wa-audio-card no-avatar" data-audio-player data-media-shell data-media-kind="${escapeHtml(type)}">
                        <button class="wa-audio-play" type="button" aria-label="Tocar audio" ${protectedSource ? 'disabled' : ''}>${playIcon()}</button>
                        <div class="wa-audio-main">
                            <div class="wa-waveform-wrap">
                                <canvas class="wa-waveform-canvas" width="460" height="48"></canvas>
                            </div>
                            <div class="wa-audio-time">0:00</div>
                            <audio preload="metadata" controls="controls" ${protectedSource ? `data-auth-media-src="${audioSrc}"` : `src="${audioSrc}"`} data-original-src="${original}" data-fallback-src="${protectedSource ? '' : fallback}"></audio>
                            <div class="message-media-fallback hidden" data-auth-media-fallback></div>
                        </div>
                    </div>
                `;
            }
            if (type === 'image') {
                const protectedSource = isProtectedPanelMediaUrl(originalUrl);
                return `<div data-media-shell data-media-kind="image"><a ${protectedSource ? 'data-auth-media-link' : `href="${original}"`} target="_blank" rel="noopener" title="Abrir imagem"><img class="message-media-image" ${protectedSource ? `data-auth-media-src="${original}"` : `src="${original}"`} alt="${label}" loading="lazy" onerror="this.style.display='none';this.closest('[data-media-shell]').querySelector('[data-auth-media-fallback]').classList.remove('hidden')"></a><div class="message-media-fallback hidden" data-auth-media-fallback>${escapeHtml(mediaHealthFallbackText(message, 'image'))}</div></div>`;
            }
            if (type === 'video') {
                const protectedSource = isProtectedPanelMediaUrl(originalUrl);
                return `<div data-media-shell data-media-kind="video"><video class="message-media-video" controls preload="none" ${protectedSource ? `data-auth-media-src="${original}"` : `src="${original}"`}></video><div class="message-media-fallback hidden" data-auth-media-fallback>${escapeHtml(mediaHealthFallbackText(message, 'video'))}</div></div>`;
            }
            if (isProtectedPanelMediaUrl(originalUrl)) {
                return `<div data-media-shell data-media-kind="media"><a class="message-media-link" data-auth-media-link target="_blank" rel="noopener"><span data-auth-media-src="${original}"></span>${label}</a><div class="message-media-fallback hidden" data-auth-media-fallback>${escapeHtml(mediaHealthFallbackText(message, 'media'))}</div></div>`;
            }
            return `<a class="message-media-link" href="${original}" target="_blank" rel="noopener">${label}</a>`;
        };

        const missingMediaShouldRender = (message = {}) => {
            const type = String(message.type || '').toLowerCase();
            if (!message.hasMedia && !['audio', 'ptt', 'image', 'video', 'media'].includes(type)) return false;
            const body = String(message.body || '').trim();
            return !body || /^\[(audio|ptt|image|imagem|video|media|midia|document|documento|sticker|figurinha)\]$/i.test(body);
        };

        const renderMessageMedia = (message) => {
            const attachments = Array.isArray(message.mediaAttachments) && message.mediaAttachments.length
                ? message.mediaAttachments
                : (message.mediaUrl ? [{
                    type: message.type || 'media',
                    label: message.body || message.type || 'midia',
                    mediaUrl: message.mediaUrl,
                    mediaPreviewUrl: message.mediaPreviewUrl || ''
                }] : (missingMediaShouldRender(message) ? [{
                    type: message.type || 'media',
                    label: message.body || message.type || 'midia',
                    mediaUrl: '',
                    mediaPreviewUrl: ''
                }] : []));
            if (!attachments.length) return '';
            return `<div class="message-media">${attachments.map((attachment) => renderMediaAttachment(attachment, message)).join('')}</div>`;
        };

        const messageHasReadableCustomerImage = (message = {}) => {
            if (message.isFromMe || !message._id) return false;
            const attachments = Array.isArray(message.mediaAttachments) && message.mediaAttachments.length
                ? message.mediaAttachments
                : (message.mediaUrl ? [{
                    type: message.type || 'media',
                    mediaUrl: message.mediaUrl
                }] : []);
            return attachments.some((attachment) => (
                attachment.mediaUrl && inferMediaType(attachment) === 'image'
            ));
        };

        const audioContextState = { context: null, peaks: new Map() };

        const getAudioContext = () => {
            const AudioContextCtor = window.AudioContext || window.webkitAudioContext;
            if (!AudioContextCtor) return null;
            if (!audioContextState.context) audioContextState.context = new AudioContextCtor();
            return audioContextState.context;
        };

        const formatAudioTime = (seconds = 0) => {
            const safe = Number.isFinite(seconds) ? Math.max(0, seconds) : 0;
            const minutes = Math.floor(safe / 60);
            const remainder = Math.floor(safe % 60);
            return `${minutes}:${String(remainder).padStart(2, '0')}`;
        };

        const fallbackPeaks = (src = '', count = 72) => {
            let hash = 0;
            for (const char of String(src || 'audio')) hash = ((hash << 5) - hash) + char.charCodeAt(0);
            return Array.from({ length: count }, (_, index) => 0.18 + ((Math.abs(hash + index * 31) % 82) / 100));
        };

        const loadAudioPeaks = async (src = '', count = 72) => {
            if (!src) return fallbackPeaks(src, count);
            if (audioContextState.peaks.has(src)) return audioContextState.peaks.get(src);
            const promise = (async () => {
                const context = getAudioContext();
                if (!context) return fallbackPeaks(src, count);
                const response = await fetch(src, { cache: 'force-cache' });
                const arrayBuffer = await response.arrayBuffer();
                const audioBuffer = await context.decodeAudioData(arrayBuffer.slice(0));
                const channel = audioBuffer.getChannelData(0);
                const blockSize = Math.max(1, Math.floor(channel.length / count));
                return Array.from({ length: count }, (_, index) => {
                    const start = index * blockSize;
                    const end = Math.min(channel.length, start + blockSize);
                    let sum = 0;
                    for (let i = start; i < end; i += 1) sum += Math.abs(channel[i]);
                    return Math.max(0.08, Math.min(1, (sum / Math.max(1, end - start)) * 4.2));
                });
            })().catch(() => fallbackPeaks(src, count));
            audioContextState.peaks.set(src, promise);
            return promise;
        };

        const activeAudioPlayback = {
            src: '',
            currentTime: 0,
            playing: false,
            updatedAt: 0
        };

        const rememberAudioPlayback = (audio) => {
            if (!audio) return;
            activeAudioPlayback.src = audio.currentSrc || audio.src || '';
            activeAudioPlayback.currentTime = audio.currentTime || 0;
            activeAudioPlayback.playing = !audio.paused && !audio.ended;
            activeAudioPlayback.updatedAt = Date.now();
        };

        const restoreAudioPlayback = async (audio) => {
            if (!audio || !activeAudioPlayback.playing) return;
            const src = audio.currentSrc || audio.src || '';
            if (!src || src !== activeAudioPlayback.src || Date.now() - activeAudioPlayback.updatedAt > 5000) return;
            try {
                if (Number.isFinite(activeAudioPlayback.currentTime) && activeAudioPlayback.currentTime > 0) {
                    audio.currentTime = activeAudioPlayback.currentTime;
                }
                await audio.play();
            } catch {
                audio.setAttribute('controls', 'controls');
            }
        };

        const drawAudioWaveform = (canvas, peaks = [], progress = 0) => {
            const ctx = canvas?.getContext?.('2d');
            if (!ctx) return;
            const width = canvas.width;
            const height = canvas.height;
            const barGap = 3;
            const barWidth = Math.max(2, Math.floor((width - (peaks.length - 1) * barGap) / Math.max(1, peaks.length)));
            ctx.clearRect(0, 0, width, height);
            peaks.forEach((peak, index) => {
                const x = index * (barWidth + barGap);
                const active = index / Math.max(1, peaks.length - 1) <= progress;
                const barHeight = Math.max(4, Math.round(peak * (height - 8)));
                const y = Math.round((height - barHeight) / 2);
                ctx.fillStyle = active ? '#128c7e' : '#8fa9b3';
                ctx.globalAlpha = active ? 0.98 : 0.62;
                const radius = Math.min(barWidth / 2, 3);
                if (typeof ctx.roundRect === 'function') {
                    ctx.beginPath();
                    ctx.roundRect(x, y, barWidth, barHeight, radius);
                    ctx.fill();
                } else {
                    ctx.fillRect(x, y, barWidth, barHeight);
                }
            });
            ctx.globalAlpha = 1;
        };

        const initializeAudioPlayers = (scope = document) => {
            scope.querySelectorAll('[data-audio-player]:not([data-ready])').forEach((card) => {
                card.dataset.ready = 'true';
                const audio = card.querySelector('audio');
                const canvas = card.querySelector('.wa-waveform-canvas');
                const button = card.querySelector('.wa-audio-play');
                const time = card.querySelector('.wa-audio-time');
                if (!audio || !canvas || !button) return;
                const switchAudioFallback = () => {
                    const fallback = audio.dataset.fallbackSrc || '';
                    const current = audio.currentSrc || audio.src || '';
                    if (!fallback || fallback === current || card.dataset.fallbackTried === 'true') return false;
                    card.dataset.fallbackTried = 'true';
                    card.classList.remove('audio-error');
                    const position = Number.isFinite(audio.currentTime) ? audio.currentTime : 0;
                    audio.src = fallback;
                    audio.load();
                    if (position > 0) {
                        audio.addEventListener('loadedmetadata', () => {
                            try {
                                audio.currentTime = Math.min(position, audio.duration || position);
                            } catch { }
                        }, { once: true });
                    }
                    return true;
                };
                const playWithFallback = async () => {
                    try {
                        await audio.play();
                        return true;
                    } catch (error) {
                        if (switchAudioFallback()) {
                            try {
                                await audio.play();
                                return true;
                            } catch { }
                        }
                        audio.setAttribute('controls', 'controls');
                        card.classList.add('audio-error');
                        if (time) time.textContent = 'Audio indisponivel';
                        return false;
                    }
                };
                let peaks = fallbackPeaks(audio.currentSrc || audio.src);
                drawAudioWaveform(canvas, peaks, 0);
                let loadingPeaks = false;
                const hydrateAudioPeaks = () => {
                    if (loadingPeaks || card.dataset.peaksReady === 'true') return;
                    loadingPeaks = true;
                    loadAudioPeaks(audio.currentSrc || audio.src).then((loadedPeaks) => {
                        peaks = loadedPeaks;
                        card.dataset.peaksReady = 'true';
                        drawAudioWaveform(canvas, peaks, audio.duration ? audio.currentTime / audio.duration : 0);
                    }).finally(() => {
                        loadingPeaks = false;
                    });
                };
                button.addEventListener('click', async () => {
                    try {
                        if (!audio.paused) {
                            audio.pause();
                            return;
                        }
                        document.querySelectorAll('[data-audio-player] audio').forEach((item) => {
                            if (item !== audio) item.pause();
                        });
                        hydrateAudioPeaks();
                        await playWithFallback();
                    } catch {
                        audio.setAttribute('controls', 'controls');
                    }
                });
                audio.addEventListener('error', () => {
                    if (switchAudioFallback()) {
                        hydrateAudioPeaks();
                    } else {
                        audio.setAttribute('controls', 'controls');
                        card.classList.add('audio-error');
                        if (time) time.textContent = 'Audio indisponivel';
                    }
                });
                audio.addEventListener('play', () => {
                    rememberAudioPlayback(audio);
                    button.innerHTML = pauseIcon();
                    card.classList.add('playing');
                    card.classList.remove('audio-error');
                });
                audio.addEventListener('pause', () => {
                    rememberAudioPlayback(audio);
                    button.innerHTML = playIcon();
                    card.classList.remove('playing');
                });
                audio.addEventListener('ended', () => {
                    activeAudioPlayback.playing = false;
                    button.innerHTML = playIcon();
                    card.classList.remove('playing');
                });
                audio.addEventListener('timeupdate', () => {
                    rememberAudioPlayback(audio);
                    const progress = audio.duration ? audio.currentTime / audio.duration : 0;
                    drawAudioWaveform(canvas, peaks, progress);
                    if (time) time.textContent = formatAudioTime(audio.currentTime || 0);
                });
                audio.addEventListener('loadedmetadata', () => {
                    if (time) time.textContent = formatAudioTime(audio.duration || 0);
                    restoreAudioPlayback(audio);
                });
            });
        };

        const isTechnicalMediaReference = (message) => {
            const body = String(message?.body || '').trim();
            if (!body) return false;
            if (isPanelMediaStatusLine(body)) return true;
            const cleaned = body
                .replace(/^\[(AUDIO|IMAGEM|IMAGE|VIDEO|MEDIA)\]\s*[\wÁÉÍÓÚáéíóúÑñ-]+\s*$/gim, '')
                .replace(/^\s*(audio|áudio|image|imagem|video|vídeo)\s*:\s*\/media\/\S+\s*$/gim, '')
                .trim();
            return cleaned === '';
        };

        const isPanelMediaStatusLine = (line = '') => {
            const normalized = String(line || '')
                .normalize('NFD')
                .replace(/[\u0300-\u036f]/g, '')
                .replace(/\s+/g, ' ')
                .trim()
                .toLowerCase();
            return /^(enviando )?(audio|imagem|image|video|midia)( enviado)?(: .*)?$/.test(normalized)
                || /^audio\/midia (aprovado )?enviado( pelo funil)?$/.test(normalized);
        };

        const messageAudioTranscript = (message = {}) => String(
            message.audioTranscript
            || message.audioTranslation
            || message.audioTranscription?.text
            || message.metadata?.audioTranscript
            || ''
        ).trim();

        const isTechnicalZapiAlertMessage = (message = {}) => (
            String(message?.provider || '') === 'zapi_chat_watchdog'
            || /^ALERTA: o WhatsApp conectado/i.test(String(message?.body || ''))
        );

        // Historico interno do painel: permanece no banco para auditoria, mas nunca e uma
        // mensagem enviada/recebida pelo cliente. Sem este filtro, cada salvamento de status
        // aparece como balao verde e esconde a conversa real do atendente.
        const isInternalPanelStatusAuditMessage = (message = {}) => (
            String(message?.type || '').toLowerCase() === 'system'
            && /^\[PAINEL\]\s*Status alterado no Painel Unificado(?:\s*-|\s*$)/i
                .test(String(message?.body || '').trim())
        );

        const cleanDisplayMessageBody = (message, hasMedia = false) => {
            if (isTechnicalZapiAlertMessage(message)) return '';
            const body = String(message?.body || '');
            const transcript = messageAudioTranscript(message);
            if (!body) return transcript || '';
            const cleaned = body
                .replace(/<span\b[^>]*class=["'][^"']*chat-status-pill[^"']*["'][^>]*>[\s\S]*?<\/span>/gi, '')
                .replace(/<(img|audio|video|source)\b[^>]*(src|href)=["'][^"']*\/media\/[^"']*["'][^>]*>/gi, '')
                .replace(/<a\b[^>]*href=["'][^"']*\/media\/[^"']*["'][^>]*>[\s\S]*?<\/a>/gi, '')
                .split('\n')
                .map((line) => line.trim())
                .filter((line) => line && !/^\[(AUDIO|IMAGEM|IMAGE|VIDEO|MEDIA)\]\s*[\wÁÉÍÓÚáéíóúÑñ-]+$/i.test(line))
                .filter((line) => !/^(audio|áudio|image|imagem|video|vídeo)\s*:\s*\/media\/\S+/i.test(line))
                .join('\n')
                .trim();
            if (!cleaned && transcript) return transcript;
            if (/^\[(audio|ptt|media|midia)\]$/i.test(cleaned) && transcript) return transcript;
            if (cleaned !== body.trim()) return cleaned;
            if (!hasMedia) return body;
            return cleaned;
        };

        const messagePreviewText = (message) => (
            isTechnicalZapiAlertMessage(message)
                ? ''
                : (
                    messageAudioTranscript(message)
                    ||
                    cleanDisplayMessageBody(message, Boolean(message?.mediaUrl || message?.mediaAttachments?.length))
                    || message?.body
                    || message?.type
                    || 'Mensagem'
                )
        );

        const renderQuotedPreview = (message) => {
            const quotedBody = String(message?.quotedBody || '').trim();
            if (!quotedBody) return '';
            const who = message.quotedFromMe ? 'atendente' : 'cliente';
            const quotedId = String(message?.quotedMessageId || '');
            const jumpAttr = quotedId ? ` data-message-jump="${escapeHtml(quotedId)}"` : '';
            return `<div class="quoted-preview"${jumpAttr} title="Ir para a mensagem original"><strong>${escapeHtml(who)}</strong>${escapeHtml(quotedBody.slice(0, 180))}</div>`;
        };

        const cssEscape = (value) => (
            window.CSS?.escape
                ? window.CSS.escape(String(value || ''))
                : String(value || '').replace(/["\\]/g, '\\$&')
        );

        const scrollToLoadedMessage = (messageId, { quiet = false } = {}) => {
            const id = String(messageId || '');
            if (!id) return false;
            const row = document.querySelector(`[data-message-id="${cssEscape(id)}"]`);
            if (!row) {
                if (!quiet) showToast('Mensagem original nao esta carregada neste trecho do historico');
                return false;
            }
            row.scrollIntoView({ behavior: 'smooth', block: 'center' });
            row.classList.add('message-jump-highlight');
            window.setTimeout(() => row.classList.remove('message-jump-highlight'), 1800);
            return true;
        };

        const scrollToMessage = async (messageId) => {
            if (scrollToLoadedMessage(messageId, { quiet: true })) return true;
            await loadSelectedMessages({ force: true, limit: 300 });
            if (scrollToLoadedMessage(messageId, { quiet: true })) return true;
            showToast('Mensagem original nao apareceu no historico carregado');
            return false;
        };

        const canDeletePanelMessage = (message) => Boolean(
            message?.isFromMe
            || message?.isBot
            || ['bot', 'system'].includes(String(message?.from || '').toLowerCase())
        );

        const WHATSAPP_EDIT_WINDOW_MS = 15 * 60 * 1000;
        const messageTimestampMs = (message = {}) => {
            return parsePanelDateMs(message.timestamp || message.createdAt);
        };
        const outboundEditAvailability = (message = {}) => {
            if (!message?.isFromMe || message?.isBot || !['chat', 'text'].includes(String(message.type || '').toLowerCase())) {
                return { show: false, allowed: false, reason: '' };
            }
            if (String(message.provider || '').toLowerCase() !== 'zapi' || !String(message.providerMessageId || message.providerPayload?.messageId || message.providerPayload?.id || '').trim()) {
                return { show: true, allowed: false, reason: 'Esta mensagem nao possui ID editavel da Z-API.' };
            }
            const sentAtMs = messageTimestampMs(message);
            if (!sentAtMs || Date.now() - sentAtMs > WHATSAPP_EDIT_WINDOW_MS) {
                return { show: true, allowed: false, reason: 'O WhatsApp permite editar apenas nos primeiros 15 minutos.' };
            }
            return { show: true, allowed: true, reason: 'Editar esta mensagem no WhatsApp' };
        };

        const updateReplyContext = () => {
            const context = el('replyContext');
            const textBox = el('replyContextText');
            if (!context || !textBox) return;
            const reply = state.replyToMessage;
            if (!reply) {
                context.classList.remove('active');
                textBox.textContent = '';
                return;
            }
            const who = reply.isFromMe ? 'atendente' : 'cliente';
            textBox.textContent = `Respondendo ${who}: ${messagePreviewText(reply).slice(0, 160)}`;
            context.classList.add('active');
        };

        const updateEditMessageContext = () => {
            const context = el('editMessageContext');
            const textBox = el('editMessageContextText');
            if (!context || !textBox) return;
            const editing = state.editingOutboundMessage;
            if (!editing) {
                context.classList.remove('active');
                textBox.textContent = '';
                return;
            }
            textBox.textContent = 'Editando mensagem enviada — altere o texto e clique em Salvar edição';
            context.classList.add('active');
        };

        const clearEditingOutboundMessage = ({ clearInput = false } = {}) => {
            state.editingOutboundMessage = null;
            if (clearInput) {
                const input = el('messageInput');
                if (input) input.value = '';
            }
            updateEditMessageContext();
            updateMessageComposerControls();
        };

        const startEditingOutboundMessage = (messageId) => {
            const message = (state.currentMessages || []).find((item) => String(item._id || '') === String(messageId || ''));
            const availability = outboundEditAvailability(message || {});
            if (!message || !availability.allowed) {
                showToast(availability.reason || 'Esta mensagem nao pode mais ser editada.');
                return;
            }
            const input = el('messageInput');
            if (!input) return;
            state.replyToMessage = null;
            updateReplyContext();
            state.editingOutboundMessage = {
                id: String(message._id || ''),
                originalBody: String(message.body || '')
            };
            input.value = String(message.body || '');
            input.focus();
            input.setSelectionRange(0, input.value.length);
            updateEditMessageContext();
            updateMessageComposerControls();
        };

        const setReplyToMessage = (messageId) => {
            const message = (state.currentMessages || []).find((item) => String(item._id || '') === String(messageId || ''));
            if (!message) return;
            clearEditingOutboundMessage();
            state.replyToMessage = message;
            updateReplyContext();
            el('messageInput').focus();
        };

        const clearReplyToMessage = () => {
            state.replyToMessage = null;
            updateReplyContext();
        };

        async function deletePanelMessage(messageId) {
            if (!state.selectedChat || !messageId) return;
            const message = (state.currentMessages || []).find((item) => String(item._id || '') === String(messageId));
            if (!message || !canDeletePanelMessage(message)) {
                showToast('Só apago mensagens do bot/atendente no painel');
                return;
            }
            const ok = window.confirm('Apagar esta mensagem? O sistema vai tentar apagar tambem no WhatsApp do cliente quando a Z-API permitir. Se nao permitir, ela sai do painel e fica registrada em auditoria.');
            if (!ok) return;
            try {
                const result = await api(`/api/whatsapp/messages/${encodeURIComponent(currentChatPhone())}/delete`, {
                    method: 'POST',
                    body: JSON.stringify({ messageId, deleteFromWhatsApp: true })
                });
                if (!result?.success) throw new Error(result?.error || 'Nao consegui apagar a mensagem.');
                state.currentMessages = (state.currentMessages || []).filter((item) => String(item._id || '') !== String(messageId));
                state.messageSignature = getMessageSignature(state.currentMessages);
                renderMessages(state.currentMessages, { preserveScroll: true });
                if (state.replyToMessage?._id === messageId) clearReplyToMessage();
                const zapi = result.zapiDelete || {};
                if (zapi.ok) {
                    showToast('Mensagem removida do WhatsApp e do painel');
                } else if (zapi.skipped === 'provider_message_id_missing') {
                    showToast('Mensagem removida do painel. Z-API nao retornou ID para apagar no WhatsApp.');
                } else if (zapi.attempted) {
                    showToast(`Mensagem removida do painel. WhatsApp nao confirmou apagamento: ${zapi.error || 'erro Z-API'}`);
                } else {
                    showToast('Mensagem removida do painel');
                }
                loadChats().catch(() => null);
            } catch (error) {
                showToast(error.message);
            }
        }

        const actionableSignature = (items = []) => (items || [])
            .map((item) => `${item._id}:${item.status}:${item.updatedAt || item.createdAt}`)
            .join('|');

        const observerQuickProfile = () => {
            const conversation = latestConversationText().toUpperCase();
            const rules = [
                { key: 'closing', label: 'Quantidade escolhida', match: /QUIERO\s+(1|2|3|4|6|UNO|UNA|UN|DOS|TRES|CUATRO|SEIS)|CONFIRMO|SEPAR|PEDIDO|LISTO|BONUS|GUIA/, draft: 'close', media: 'product' },
                { key: 'trust', label: 'Cliente inseguro', match: /ESTAFA|GOLPE|SEGURO|CONFIAN|ENTREGA|AGENCIA|DOMICILIO|SERVIENTREGA/, draft: 'proof', media: 'proof' },
                { key: 'price', label: 'Falando de preco', match: /PRECIO|CUANTO|VALOR|CUESTA|PROMOCION|CARO/, draft: 'offer', media: 'product' },
                { key: 'product', label: 'Avaliando produto', match: /FUNCIONA|BENEFICIO|RESULTADO|NATURAL|TOMAR|PRODUCTO|PRODUTO/, draft: 'proof', media: 'product' },
                { key: 'logistics', label: 'Perto dos dados', match: /CIUDAD|PROVINCIA|DIRECCION|REFERENCIA|AGENCIA|DOMICILIO|LLEGA|DEMORA/, draft: 'data', media: 'proof' }
            ];
            return rules.find((rule) => rule.match.test(conversation))
                || { key: 'general', label: 'Observando inicio', draft: 'data', media: 'product' };
        };

        const observerQuickMedia = (profile) => {
            const media = footerMediaFiles();
            if (profile?.media === 'product') return media.find((item) => item.code === 'M01') || media[0];
            return media.find((item) => /Prova 1/i.test(item.label)) || media[1] || media[0];
        };

        const observerLabCountry = () => selectedPanelCountry();

        const observerLabRender = () => {
            const tab = state.observerLabTab || 'best';
            const data = state.observerLabData || {};
            const cache = data.cache || {};
            const summary = data.summary || {};
            const isBest = tab === 'best';
            const isStrategy = tab === 'strategy';
            const isCache = tab === 'cache';
            const items = isBest
                ? (Array.isArray(data.items) ? data.items : [])
                : isStrategy
                    ? (Array.isArray(data.examples) ? data.examples : [])
                    : (Array.isArray(data.snapshots) ? data.snapshots : []);
            const cacheLabel = cache.hit ? 'cache' : data.generatedAt ? 'novo' : 'vazio';
            const summaryBits = isBest
                ? [
                    `retornados ${summary.returned || items.length || 0}`,
                    `campeoes ${summary.champions || 0}`,
                    `fortes ${summary.strongCandidates || 0}`
                ]
                : isStrategy
                    ? [
                        `exemplos ${summary.examples || items.length || 0}`,
                        `prontidao ${summary.readiness || 0}%`,
                        `memorias ${summary.memories || 0}`
                    ]
                    : [
                        `snapshots ${items.length || 0}`,
                        `pais ${observerLabCountry()}`
                    ];
            const rowsHtml = items.slice(0, 8).map((item) => {
                if (isCache) {
                    return `
                        <div class="observer-step">
                            <strong>${escapeHtml(item.type || 'snapshot')} · ${escapeHtml(item.country || '')}</strong>
                            <span class="meta">${escapeHtml(item.key || '')}</span>
                            <div>${escapeHtml(item.summary ? JSON.stringify(item.summary).slice(0, 220) : 'Sem resumo')}</div>
                        </div>
                    `;
                }
                const title = item.title || item.lead?.name || item.phone || 'Atendimento';
                const score = item.score || item.bestAttendance?.score || '';
                const customer = item.customerEntry || item.customerText || item.bestAttendance?.customerEntry || '';
                const reply = item.bestReply || item.winningReply || item.bestAttendance?.bestReply || '';
                const lesson = item.implantationLessonPt || item.lessonPt || item.bestAttendance?.implantationLessonPt || '';
                return `
                    <div class="observer-step">
                        <strong>${escapeHtml(title)}${score ? ` · ${escapeHtml(score)}/100` : ''}</strong>
                        <span class="meta">${escapeHtml(item.classification || item.result || item.stage || '')}</span>
                        ${customer ? `<div>${escapeHtml('CL: ' + customer)}</div>` : ''}
                        ${reply ? `<div>${escapeHtml('AT: ' + reply)}</div>` : ''}
                        ${lesson ? `<span class="meta">${escapeHtml(lesson)}</span>` : ''}
