            const attendanceClass = attendance?.score10 >= 10 ? 'green' : attendance?.score10 >= 9 ? 'orange' : attendance ? 'red' : 'orange';
            const attendanceHtml = `
                <details class="observer-compact-section" ${attendance ? 'open' : ''}>
                    <summary class="observer-compact-summary">
