                    <div class="observer-compact-content">
                        ${attendance ? `
                            <div class="actionable-card-body">${escapeHtml(`${attendance.label} · ${attendance.percent}/100 · ${attendance.summary?.humanMessages || 0} respostas humanas · ${attendance.summary?.audioCount || 0} audio(s)`)}</div>
                            ${(attendance.missing || []).length ? `<div class="actionable-card-script">${(attendance.missing || []).map((item) => `${escapeHtml(item.label)}: ${escapeHtml(item.fix)}`).join('<br>')}</div>` : '<div class="actionable-card-script">Atendimento pronto para virar skill validada.</div>'}
                            ${attendance.score10 >= 10 ? `
                                <details class="observer-action-menu">
                                    <summary>Acoes</summary>
                                    <div class="observer-action-panel">
                                        <button class="success" data-observer-save-attendance-skill="1" type="button" ${state.observerSavingAttendanceSkill ? 'disabled' : ''}>${state.observerSavingAttendanceSkill ? 'Salvando...' : 'Guardar no banco de skills'}</button>
                                    </div>
                                </details>
                            ` : attendance.score10 === 9 ? `
                                <div class="actionable-card-body">Falta pouco: aplique os ajustes acima para tentar chegar em 10/10 e 100/100.</div>
                            ` : `
                                <div class="actionable-card-body">Use as correcoes acima antes de salvar como skill.</div>
                            `}
                        ` : '<div class="actionable-card-body">Clique em Dar nota para o Observador avaliar de 0 a 10.</div>'}
                    </div>
                </details>
            `;
            const observerCountry = currentTemplateCountry();
            const audioHtml = `
                <details class="observer-compact-section">
                    <summary class="observer-compact-summary">
                        <span>Audios recomendados</span>
                        <span class="badge green">${escapeHtml(audio.recommendations.length)} sugestoes</span>
                    </summary>
                    <div class="observer-compact-content">
                        <div class="actionable-card-body">O Observador sugere audio por etapa. Abra um item para ouvir, enviar ou dar nota.</div>
                        <div class="observer-audio-grid">
                        ${audio.recommendations.map((item) => `
                            <details class="observer-audio-card recommended">
                                <summary>
                                    <strong class="observer-audio-name">${escapeHtml(`${footerAudioCodeForMediaUrl(item.mediaUrl) ? footerAudioCodeForMediaUrl(item.mediaUrl) + ' - ' : ''}${item.title || funnelAudioLabel(item)}`)}</strong>
                                    <span class="badge green">${escapeHtml(Math.round(Number(item.confidence || 0) * 100))}%</span>
                                </summary>
                                <div>${escapeHtml(`${footerAudioCodeForMediaUrl(item.mediaUrl) ? footerAudioCodeForMediaUrl(item.mediaUrl) + ' - ' : ''}${funnelAudioLabel(item)}`)}</div>
                                <span class="meta">${escapeHtml(item.reason || '')}</span>
                                ${item.previewUrl ? `<audio controls preload="none" src="${escapeHtml(absoluteMediaUrl(item.previewUrl))}"></audio>` : ''}
                                ${state.observerAudioScores[item.mediaUrl] ? `
                                    <div class="actionable-card-script">
                                        <strong>${escapeHtml('Nota ' + state.observerAudioScores[item.mediaUrl].scores.total + ' / ' + state.observerAudioScores[item.mediaUrl].grade)}</strong><br>
                                        ${escapeHtml(state.observerAudioScores[item.mediaUrl].verdict)}<br>
                                        ${escapeHtml('Etapa: ' + state.observerAudioScores[item.mediaUrl].stage)}<br>
                                        ${escapeHtml('Forcas: ' + (state.observerAudioScores[item.mediaUrl].strengths || []).join(', '))}<br>
                                        ${escapeHtml('Melhorar: ' + (state.observerAudioScores[item.mediaUrl].improvements || []).join(', '))}
                                        ${state.observerAudioScores[item.mediaUrl].suggestedRecordingScript ? `<br><br>${escapeHtml('Sugestao de regravacao: ' + state.observerAudioScores[item.mediaUrl].suggestedRecordingScript)}` : ''}
                                    </div>
                                ` : ''}
                                <details class="observer-action-menu">
                                    <summary>Acoes</summary>
                                    <div class="observer-action-panel">
                                        <button class="success" data-observer-audio-template="${escapeHtml(item.mediaUrl)}" type="button">Enviar</button>
                                        <button data-observer-audio-score="${escapeHtml(item.mediaUrl)}" data-observer-audio-label="${escapeHtml(funnelAudioLabel(item))}" type="button" ${state.observerAudioScoring === item.mediaUrl ? 'disabled' : ''}>${state.observerAudioScoring === item.mediaUrl ? 'Analisando...' : 'Dar nota'}</button>
                                    </div>
                                </details>
                            </details>
                        `).join('') || `<div class="observer-audio-card"><strong>Nenhum audio carregado</strong><span class="meta">${escapeHtml(`Clique em uma conversa ${observerCountry} ou atualize os templates para o Observador recomendar audios.`)}</span></div>`}
                        ${audio.recordSuggestions.map((item) => `
                            <details class="observer-audio-card record">
                                <summary>
                                    <strong class="observer-audio-name">${escapeHtml('Gravar: ' + item.title)}</strong>
                                    <span class="badge orange">novo</span>
                                </summary>
                                <span class="meta">${escapeHtml(item.reason)}</span>
                                <div>${escapeHtml(item.recordSuggestion)}</div>
                            </details>
                        `).join('')}
                        </div>
                    </div>
