        };

        async function loadActionableSamples(options = {}) {
            if (!state.token || !state.selectedChat || state.actionablesLoading) return;
            const now = Date.now();
            if (!options.force && state.actionablesLastLoadedAt && now - state.actionablesLastLoadedAt < 12000) return;
            const requestKey = currentContactStateKey();
            state.actionablesLoading = true;
            try {
                const params = new URLSearchParams({
                    chatId: currentContactStateKey(),
                    phone: currentChatPhone(),
                    limit: '12',
                    _: String(Date.now())
                });
                const result = await api(`/api/observation/actionables?${params.toString()}`);
                if (!state.selectedChat || currentContactStateKey() !== requestKey) return;
                state.actionablesLastLoadedAt = Date.now();
                const items = result.actionables || [];
                const nextSignature = actionableSignature(items);
                if (nextSignature !== state.actionableSignature) {
                    state.actionableSamples = items;
                    state.actionableSignature = nextSignature;
                    renderActionableSamples();
                    if ((state.currentMessages || []).length) {
                        renderMessages(state.currentMessages, { preserveScroll: true });
                    }
                }
            } catch (error) {
                if (!/Login necessario/i.test(error.message || '')) console.warn(error);
            } finally {
                state.actionablesLoading = false;
            }
        }

        async function loadObserverLab(tab = state.observerLabTab || 'best', options = {}) {
            if (!state.token || state.observerLabLoading) return;
            const now = Date.now();
            state.observerLabTab = tab;
            if (!options.force && state.observerLabData && state.observerLabLastLoadedAt && now - state.observerLabLastLoadedAt < 60000) {
                renderActionableSamples();
                return;
            }
            state.observerLabLoading = true;
            renderActionableSamples();
            try {
                const country = observerLabCountry();
                const refresh = options.refresh ? '&refresh=1' : '';
                const endpoint = tab === 'strategy'
                    ? `/api/observation/strategic-center?country=${encodeURIComponent(country)}&focus=sales&limit=12${refresh}`
                    : tab === 'cache'
                        ? `/api/observation/intelligence-snapshots?country=${encodeURIComponent(country)}&limit=20`
                        : `/api/observation/best-attendances?country=${encodeURIComponent(country)}&focus=sales&days=30&limit=12&scanLimit=160${refresh}`;
                state.observerLabData = await api(endpoint);
                state.observerLabLastLoadedAt = Date.now();
            } catch (error) {
                state.observerLabData = {
                    ok: false,
                    summary: { warning: error.message || 'Erro ao carregar banco do Observador' },
                    items: []
                };
                showToast(error.message);
            } finally {
                state.observerLabLoading = false;
                renderActionableSamples();
            }
        }

        async function handleActionableAction(kind, actionableId) {
            if (!actionableId || state.busy) return;
            let feedbackReason = '';
            if (kind === 'feedback') {
                feedbackReason = window.prompt('O que esta errado nesta dica? Escreva a decisao correta para o Observador aprender.') || '';
                if (!feedbackReason.trim()) return;
            }
            state.busy = true;
            try {
                const endpoint = kind === 'save'
                    ? `/api/observation/actionables/${encodeURIComponent(actionableId)}/save-skill`
                    : kind === 'feedback'
                        ? `/api/observation/actionables/${encodeURIComponent(actionableId)}/feedback`
                    : kind === 'apply'
                        ? `/api/observation/actionables/${encodeURIComponent(actionableId)}/apply`
                        : `/api/observation/actionables/${encodeURIComponent(actionableId)}/discard`;
                const editedScript = kind === 'apply'
                    ? document.querySelector(`[data-actionable-script="${actionableId}"]`)?.value?.trim()
                    : '';
                const body = kind === 'apply'
                    ? JSON.stringify({ sessionId: 'zapi', overrideScript: editedScript })
                    : kind === 'feedback'
                        ? JSON.stringify({ type: 'wrong_tip', reason: feedbackReason.trim() })
                        : undefined;
                await api(endpoint, { method: 'POST', body });
                state.actionableSamples = (state.actionableSamples || []).filter((item) => String(item._id) !== String(actionableId));
                state.actionableSignature = actionableSignature(state.actionableSamples);
                renderActionableSamples();
                if (kind === 'save') showToast('Skill guardada na biblioteca');
                if (kind === 'apply') {
                    showToast('Script enviado pela Z-API');
                    loadSelectedMessages({ force: true }).catch(() => null);
                    loadChats().catch(() => null);
                }
                if (kind === 'discard') showToast('Amostra descartada');
                if (kind === 'feedback') showToast('Dica errada anotada para o Observador');
            } catch (error) {
                showToast(error.message);
            } finally {
                state.busy = false;
            }
        }

        const copyActionableScriptToComposer = (actionableId) => {
            const actionable = (state.actionableSamples || []).find((item) => String(item._id) === String(actionableId));
            const script = actionable?.suggestedScript || actionable?.templateDraft || '';
            if (!script) {
                showToast('Dica sem texto pronto');
                return;
            }
            el('messageInput').value = script;
            el('messageInput').focus();
            showToast('Dica colocada no campo de resposta');
        };

        const focusActionableDetails = (actionableId) => {
            const details = document.querySelector('.observer-nba-more');
            if (details) details.open = true;
            const card = document.querySelector(`[data-actionable-script="${actionableId}"]`)?.closest('.actionable-card');
            if (card) {
                card.open = true;
                card.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
            }
        };

        const setObserverHintStatus = (target, text = '', active = true) => {
            const hint = target?.closest?.('.message-observer-hover');
            const status = hint?.querySelector?.('[data-observer-hint-status]');
            const label = hint?.querySelector?.('[data-observer-hint-status-text]');
            if (!status || !label) return;
            label.textContent = text;
            status.classList.toggle('active', Boolean(active));
            if (active && text && !/enviando|preparando|carregando/i.test(text)) {
                window.setTimeout(() => status.classList.remove('active'), 1800);
            }
        };

        const audioHaystack = (template = {}) => `${template.label || ''} ${template.id || ''} ${funnelAudioLabel(template)}`.toUpperCase();

        const observerAudioMatches = (candidates = []) => {
            const wanted = (Array.isArray(candidates) ? candidates : [])
                .map((candidate) => String(candidate || '').trim())
                .filter(Boolean);
            if (!wanted.length) return [];
            const country = currentTemplateCountry();
            const templates = sortedFooterAudioTemplates((state.audioTemplates || []).filter((template) => template.country === country));
            const used = new Set();
            const matches = [];
            for (const candidate of wanted) {
                const needle = candidate.toUpperCase();
                const found = templates.find((template) => !used.has(template.mediaUrl) && audioHaystack(template).includes(needle));
                if (found) {
                    used.add(found.mediaUrl);
                    matches.push({
                        code: footerAudioCodeForMediaUrl(found.mediaUrl),
                        label: funnelAudioLabel(found),
                        mediaUrl: found.mediaUrl
                    });
                }
                if (matches.length >= 3) break;
            }
            return matches;
        };

        const observerHintText = (source = {}) => [
            source.title,
            source.subtitle,
            source.category,
            source.strategy,
            source.body,
            source.suggestedScript,
            source.templateDraft,
            source.detectedArgument,
            source.context?.customerQuestion,
            ...(source.context?.audioCandidates || []),
            ...(source.context?.mediaCandidates || []),
            ...(source.audioCandidates || []),
            ...(source.mediaCandidates || [])
        ].filter(Boolean).join(' ').toUpperCase();

        const observerDefaultAudioCandidates = (source = {}) => {
            const text = observerHintText(source);
            if (/AGENCIA|DOMICILIO|DIRECCION|REFERENCIA|SERVIENTREGA|ENTREGA|SEGUR|LLEGA|DEMORA|GUIA|RASTREO/.test(text)) {
                return ['TEMPO DEMORA', 'PERGUNTA AGENCIA DOMICILIO', 'ENVIO AGENCIA 100 SEGURO'];
            }
            if (/PRECIO|PRECO|VALOR|CUESTA|COSTO|PROMOCION|CARO/.test(text)) {
                return ['TRATAMENTO Y PRECIOS', 'QUANTOS FRASCOS'];
            }
            if (/CANTIDAD|QUANTIDADE|FRASCO|FRASCOS|BOTELLA|BOTELLAS|KIT|UNIDADES/.test(text)) {
                return ['QUANTOS FRASCOS', 'NOME CIUDAD', 'TRATAMENTO Y PRECIOS'];
            }
            if (/FUNCIONA|PRODUCTO|PRODUTO|NATURAL|TOMAR|RESULTADO|PROVA|PRUEBA|DEPOIMENTO|TESTIMONIO/.test(text)) {
                return ['FUNCIONA VIT POWER', 'COMO SE TOMA', 'DEPOIMENTO AUDIO PRODUTO'];
            }
            if (/NOME|NOMBRE|CIUDAD|PROVINCIA/.test(text)) {
                return ['NOME CIUDAD', 'PROVINCIA'];
            }
            return ['FUNCIONA VIT POWER', 'TRATAMENTO Y PRECIOS'];
        };

        const observerFunnelBlockMatches = (actionable = {}) => {
            const text = observerHintText(actionable);
            const customBlocks = footerFunnelBlocks()
                .filter((block) => block.custom)
                .filter((block) => {
                    const haystack = `${block.label || ''} ${block.detail || ''} ${(block.steps || []).map((step) => step.label).join(' ')}`.toUpperCase();
                    return text.split(/\s+/).filter((word) => word.length >= 5).some((word) => haystack.includes(word));
                })
                .slice(0, 3);
            if (customBlocks.length) return customBlocks;
            if (/FUNCIONA|PRODUCTO|PRODUTO|NATURAL|PROVA|PRUEBA|RESULTADO|DEPOIMENTO|TESTIMONIO/.test(text)) {
                return footerFunnelBlocks().filter((block) => ['B01', 'B02', 'B03'].includes(block.code)).slice(0, 2);
            }
            if (/PRECIO|PRECO|VALOR|CUESTA|CANTIDAD|QUANTIDADE|FRASCO|BOTELLA|KIT/.test(text)) {
                return footerFunnelBlocks().filter((block) => ['B02', 'B03'].includes(block.code)).slice(0, 2);
            }
            return [];
        };

        const observerMediaMatches = (source = {}) => {
            const candidates = Array.isArray(source.mediaCandidates) ? source.mediaCandidates : [];
            const text = observerHintText(source);
            const files = footerMediaFiles();
            if (!text.trim()) return [];
            const wantedCodes = [];
            const push = (code) => {
                if (!wantedCodes.includes(code)) wantedCodes.push(code);
            };
            if (/PRODUTO|PRODUCTO|FRASCO|BOTELLA|PRECIO|CANTIDAD|QUANTIDADE|KIT/.test(text)) push('M01');
            if (/PROVA|PRUEBA|DEPOIMENTO|TESTIMONIO|FUNCIONA|RESULTADO|NATURAL|SABER MAS/.test(text)) {
                push('M02');
                push('M03');
            }
            if (/VIDEO/.test(text)) push('M06');
            if (!wantedCodes.length && candidates.length) push('M01');
            return wantedCodes
                .map((code) => files.find((item) => item.code === code))
                .filter(Boolean)
                .slice(0, 3);
        };

        const audioRecommendationRules = () => ([
            {
                key: 'quantity',
                title: 'Quantidade escolhida',
                matchConversation: /QUIERO\s+(1|2|3|4|6|UNO|UNA|UN|DOS|TRES|CUATRO|SEIS)|\b(1|2|3|4|6)\s*(FRASCOS|BOTELLAS|UNIDADES)\b/i,
                templateMatch: /QUANTOS FRASCOS|1 BOTELLA|3 BOTELLAS|6 BOTELLAS|TRATAMENTO Y PRECIOS/i,
                reason: 'Cliente escolheu quantidade; confirme frascos, preco oficial e peca os dados sem voltar para explicacao longa.',
                recordSuggestion: 'Audio curto confirmando a quantidade escolhida, valor oficial e proximo passo de dados para entrega.'
            },
            {
                key: 'trust',
                title: 'Confiança antes do fechamento',
                matchConversation: /ESTAFA|GOLPE|SEGURO|CONFIAN|ENTREGA|AGENCIA|DOMICILIO|SERVIENTREGA/i,
                templateMatch: /ENVIO AGENCIA 100 SEGURO|ENTREGA SEGURA|SERVIENTREGA|AGENCIA|DEPOIMENTO/i,
                reason: 'Cliente precisa sentir seguranca antes de enviar dados ou aceitar a compra.',
                recordSuggestion: 'Audio curto da Doutora Maria Fernandes validando a entrega segura: explicar que o pedido tem rastreio, pode ser retirado em agencia e que a equipe acompanha ate a entrega.'
            },
            {
                key: 'price',
                title: 'Oferta em audio',
                matchConversation: /PRECIO|CUANTO|VALOR|CUESTA|PROMOCION|CARO/i,
                templateMatch: /TRATAMENTO Y PRECIOS|BOTELLA|BOTELLAS|QUANTOS FRASCOS|PROMOCAO/i,
                reason: 'Quando preco aparece, audio ajuda a ancorar valor e reduzir comparacao fria.',
                recordSuggestion: 'Audio de oferta com 1, 3 e 6 unidades, destacando melhor custo por unidade, bonus e envio gratis acima da quantidade definida.'
            },
            {
                key: 'product',
                title: 'Produto e prova',
                matchConversation: /FUNCIONA|BENEFICIO|RESULTADO|NATURAL|TOMAR|COMO SE TOMA|PRODUTO|PRODUCTO/i,
                templateMatch: /FUNCIONA VIT POWER|DEPOIMENTO|100 NATURAL|COMO SE TOMA|COMO TOMAR|TEMPO RESULTADO/i,
                reason: 'Cliente ainda esta avaliando o produto; audio cria presenca humana e mais confianca.',
                recordSuggestion: 'Audio explicando em espanhol simples como o produto funciona, como tomar e quando esperar resultados, sem promessa exagerada.'
            },
            {
                key: 'logistics',
                title: 'Logistica e dados',
                matchConversation: /CIUDAD|PROVINCIA|DIRECCION|REFERENCIA|AGENCIA|DOMICILIO|LLEGA|DEMORA/i,
                templateMatch: /NOME CIUDAD|PROVINCIA|PERGUNTA AGENCIA DOMICILIO|ENDERECO|TEMPO DEMORA|DOMICILIO/i,
                reason: 'Cliente esta perto do pedido; audio orienta dados sem parecer mecanico.',
                recordSuggestion: 'Audio pedindo nome completo, cidade, provincia e se prefere agencia ou domicilio, com tom calmo e objetivo.'
            },
            {
                key: 'closing',
                title: 'Fechamento e retirada',
                matchConversation: /CONFIRMO|QUIERO|SEPAR|PEDIDO|LISTO|BONUS|GUIA|PAGOU|RETIRADA/i,
                templateMatch: /AGRADECIMENTO|BONUS|GUIA|PEDIDO ENVIADO|OBRIGADO|CONFIRMACION/i,
                reason: 'Cliente ja esta quente; audio final reforca compromisso e reduz arrependimento.',
                recordSuggestion: 'Audio de fechamento confirmando pedido, bonus e proximo passo de entrega, com agradecimento pessoal.'
            }
        ]);

        const latestConversationText = () => (state.currentMessages || [])
            .slice(-12)
            .map((message) => cleanDisplayMessageBody(message, Boolean(message.mediaUrl || message.mediaAttachments?.length)))
            .join(' ');

        const observerAudioRecommendations = () => {
            if (!state.selectedChat) return { recommendations: [], recordSuggestions: [] };
            const country = currentTemplateCountry();
            const templates = (state.audioTemplates || [])
                .filter((template) => template.country === country)
                .sort((a, b) => audioTemplatePriority(a) - audioTemplatePriority(b)
                    || String(a.label || a.id || '').localeCompare(String(b.label || b.id || ''), undefined, { numeric: true, sensitivity: 'base' }));
            const conversation = latestConversationText();
            const rules = audioRecommendationRules();
            const activeRules = rules.filter((rule) => rule.matchConversation.test(conversation));
            const selectedRules = activeRules.length ? activeRules : rules.slice(0, 3);
            const used = new Set();
            const recommendations = [];
            const recordSuggestions = [];

            for (const rule of selectedRules) {
                const found = templates.find((template) => !used.has(template.mediaUrl) && rule.templateMatch.test(audioHaystack(template)));
                if (found) {
                    used.add(found.mediaUrl);
                    recommendations.push({
                        ...found,
                        title: rule.title,
                        reason: rule.reason,
                        confidence: activeRules.includes(rule) ? 0.9 : 0.68
                    });
                } else {
                    recordSuggestions.push(rule);
                }
                if (recommendations.length >= 3) break;
            }

            if (!recommendations.length && templates.length) {
                for (const template of templates.slice(0, 3)) {
                    recommendations.push({
                        ...template,
                        title: 'Audio prioritario',
                        reason: 'Sugestao geral enquanto o Observador junta mais contexto da conversa.',
                        confidence: 0.55
                    });
                }
            }

            return { recommendations, recordSuggestions: recordSuggestions.slice(0, 2) };
        };

        async function generateObserverFunnel() {
            if (!state.selectedChat || state.observerAnalyzing) return;
            state.observerAnalyzing = true;
            renderActionableSamples();
            try {
                const result = await api('/api/observation/conversation-funnel', {
                    method: 'POST',
                    body: JSON.stringify({
                        chatId: currentContactStateKey(),
                        phone: currentChatPhone()
                    })
                });
                state.observerBlueprint = result.blueprint || null;
                renderActionableSamples();
                showToast('Funil perfeito gerado pelo Observador');
            } catch (error) {
                showToast(error.message);
            } finally {
                state.observerAnalyzing = false;
                renderActionableSamples();
            }
        }

        async function scoreObserverAudio(mediaUrl, label = '') {
            if (!state.selectedChat || !mediaUrl || state.observerAudioScoring) return;
            state.observerAudioScoring = mediaUrl;
            renderActionableSamples();
            try {
                const result = await api('/api/observation/audio-score', {
                    method: 'POST',
                    body: JSON.stringify({
                        mediaUrl,
                        label,
                        chatId: currentContactStateKey(),
                        phone: currentChatPhone()
                    })
