                state.observerAudioScores = {
                    ...(state.observerAudioScores || {}),
                    [mediaUrl]: result.score
                };
                renderActionableSamples();
                showToast(`Nota do audio: ${result.score?.scores?.total || 0}/${result.score?.grade || ''}`);
            } catch (error) {
                showToast(error.message);
            } finally {
                state.observerAudioScoring = '';
                renderActionableSamples();
            }
        }

