        const observerActionableForMessage = (messageId) => {
            const id = String(messageId || '');
            if (!id) return null;
            const items = (state.actionableSamples || []).filter((item) => String(item.type || '') === 'warning');
            return items.find((item) => String(item.sourceMessageId || '') === id)
                || items.find((item) => (item.relatedMessageIds || []).some((relatedId) => String(relatedId) === id))
                || null;
        };

        const inlineMessageObserverHintsEnabled = false;

        const quickMessageStrategyHint = (message = {}) => {
            const body = cleanDisplayMessageBody(message, Boolean(message?.mediaUrl || message?.mediaAttachments?.length)) || messagePreviewText(message);
            const text = String(body || '').replace(/\s+/g, ' ').trim();
            const upper = text.toUpperCase();
            const customerName = state.selectedChat?.name || 'senor';
            const productInfo = frontendProductInfo();
            if (!text) return null;

            if (/NOMBRE\s+COMPLETO|ME\s+LLAMO|SOY\s+[A-Z]/i.test(text)) {
                return {
                    title: 'Estrategia sugerida',
                    subtitle: 'capturar dato y avanzar',
                    body: 'El cliente ya dio nombre o intencion. Fije el dato en la ficha y avance al siguiente campo sin volver a explicar el producto.',
                    script: `Perfecto, ${customerName}. Ya lo anote aqui. Ahora me confirma por favor su ciudad y provincia para revisar la entrega?`,
                    audioCandidates: ['NOME CIUDAD', 'PROVINCIA']
                };
            }
            if (/\b(SI|S[IÍ]|OK|PERFECTO|LISTO|DE ACUERDO|CONFIRMO)\b/i.test(text)) {
                return {
                    title: 'Estrategia sugerida',
                    subtitle: 'cerrar sin reabrir duda',
                    body: 'El cliente acepto. No vuelva a vender. Confirme el pedido y pida el dato faltante mas proximo.',
                    script: `Excelente, ${customerName}. Para dejar su pedido listo hoy, me confirma nombre completo, ciudad/provincia y si prefiere agencia o domicilio?`,
                    audioCandidates: ['AGRADECIMENTO', 'PERGUNTA AGENCIA DOMICILIO'],
                    mediaCandidates: ['Produto']
                };
            }
            if (/\b(UN MES|1 FRASCO|UNA BOTELLA|UN FRASCO|DOS|2 FRASCOS|TRES|3 FRASCOS|SEIS|6 FRASCOS)\b/i.test(text)) {
                return {
                    title: 'Estrategia sugerida',
                    subtitle: 'cantidad elegida',
                    body: 'El cliente ya eligio cantidad. Confirme el kit, refuerce envio discreto y conduzca directo a datos.',
                    script: `Perfecto, le dejo separado ese kit. Para generar el envio discreto por ${productInfo.carrier}, me confirma su ciudad y departamento/provincia?`,
                    audioCandidates: ['QUANTOS FRASCOS', 'NOME CIUDAD'],
                    mediaCandidates: ['Produto']
                };
            }
            if (/\b(PRECIO|CUANTO|CUESTA|VALOR|COSTO|PROMOCION|CARO)\b/i.test(text)) {
                return {
                    title: 'Estrategia sugerida',
                    subtitle: 'precio directo + siguiente paso',
                    body: 'Responda precio en seco, sin historia larga, y cierre com uma pergunta logistica para mover o funil.',
                    script: `Claro. Hoy tenemos ${productInfo.priceLine}. Para que ciudad seria el envio?`,
                    audioCandidates: productInfo.priceAudioCandidates,
                    mediaCandidates: ['Produto']
                };
            }
            if (/\b(CIUDAD|PROVINCIA|AMBATO|QUITO|GUAYAQUIL|CUENCA|AGENCIA|DOMICILIO|DIRECCION|REFERENCIA|CASTILLO|SERVIENTREGA)\b/i.test(text)) {
                return {
                    title: 'Estrategia sugerida',
                    subtitle: 'logistica de cierre',
                    body: 'Cliente esta em dados/logistica. Confirme o que entendeu e peca apenas o proximo dado faltante.',
                    script: `Perfecto, ${customerName}. Entonces lo dejamos para esa zona. Me confirma si desea retirar en agencia o recibir en domicilio?`,
                    audioCandidates: ['ENVIO AGENCIA 100 SEGURO', 'PERGUNTA AGENCIA DOMICILIO'],
                    mediaCandidates: ['Produto']
                };
            }
            if (/\b(LLEGA|DEMORA|CUANDO|DIA|D[IÍ]A|ENTREGA|GUIA|RASTREO)\b/i.test(text)) {
                return {
                    title: 'Estrategia sugerida',
                    subtitle: 'prazo + confirmacao',
                    body: 'Responda primeiro a duvida de prazo e logo conduza para confirmacao de envio.',
                    script: 'Normalmente llega entre martes y miercoles, segun la agencia. Si desea, puedo dejarlo listo ahora con envio discreto.',
                    audioCandidates: ['TEMPO DEMORA', 'ENVIO AGENCIA 100 SEGURO'],
                    mediaCandidates: ['Produto']
                };
            }
            if (/\b(FUNCIONA|PRODUCTO|PRODUCTO|NATURAL|COMO SE TOMA|TOMAR|RESULTADO|INFORMACION|SABER MAS)\b/i.test(text)) {
                return {
                    title: 'Estrategia sugerida',
                    subtitle: 'prova antes de preco',
                    body: 'Cliente ainda esta avaliando. Use explicacao curta, prova/Audio e uma pergunta simples para seguir.',
                    script: `Claro. ${productInfo.name} es un suplemento natural de apoyo masculino, usado de forma progresiva. Le puedo enviar la informacion corta y luego revisamos el kit mas indicado para usted.`,
                    audioCandidates: productInfo.useAudioCandidates,
                    mediaCandidates: ['Produto', 'Prova 1', 'Prova 2']
