            return {
                title: 'Estrategia sugerida',
                subtitle: 'responder e conduzir',
                body: 'Responda a duvida do cliente na primeira frase e conduza para o proximo dado do pedido.',
                script: `Entiendo, ${customerName}. Para ayudarle sin error, me confirma si su duda es sobre precio, entrega, como tomar o el pedido?`,
                audioCandidates: [...productInfo.useAudioCandidates, ...productInfo.priceAudioCandidates],
                mediaCandidates: ['Produto', 'Prova 1']
