        const renderMessageObserverHint = (messageId, message = {}) => {
            if (!inlineMessageObserverHintsEnabled) return '';
            const actionable = observerActionableForMessage(messageId);
            if (!actionable) {
                const hint = quickMessageStrategyHint(message);
                if (!hint) return '';
                const audioMatches = observerAudioMatches(hint.audioCandidates || observerDefaultAudioCandidates(hint));
                const mediaMatches = observerMediaMatches(hint);
                const blockMatches = observerFunnelBlockMatches(hint);
                return `
                    <div class="message-observer-hover">
                        <div class="message-observer-head">
                            <div class="message-observer-title">
                                <strong>${escapeHtml(hint.title)}</strong>
                                <span>${escapeHtml(hint.subtitle)}</span>
                            </div>
                            <button class="message-observer-close" data-observer-hint-close="1" type="button" title="Fechar dica">x</button>
                        </div>
                        <div class="actionable-card-body">${escapeHtml(hint.body)}</div>
                        <button class="message-observer-script" data-observer-suggested-script="${escapeHtml(hint.script)}" type="button">${escapeHtml(hint.script)}</button>
                        ${audioMatches.length ? `
                            <div class="message-observer-audios">
                                ${audioMatches.map((item) => `
                                    <button class="message-observer-audio" data-observer-audio-template="${escapeHtml(item.mediaUrl)}" type="button" title="${escapeHtml(item.label)}">
                                        ${escapeHtml(`${item.code ? item.code + ' - ' : ''}${item.label}`)}
                                    </button>
                                `).join('')}
                            </div>
                        ` : ''}
                        ${mediaMatches.length ? `
                            <div class="message-observer-audios">
                                ${mediaMatches.map((item) => `
                                    <button class="message-observer-audio" data-observer-media-template="${escapeHtml(item.value)}" type="button" title="${escapeHtml(item.detail || item.label)}">
                                        ${escapeHtml(`${item.code ? item.code + ' - ' : ''}${item.label}`)}
                                    </button>
                                `).join('')}
                            </div>
                        ` : ''}
                        ${blockMatches.length ? `
                            <div class="message-observer-audios">
                                ${blockMatches.map((item) => `
                                    <button class="message-observer-audio" data-observer-block-template="${escapeHtml(item.value)}" type="button" title="${escapeHtml(item.detail || item.label)}">
                                        ${escapeHtml(`${item.code ? item.code + ' - ' : ''}${item.label}`)}
                                    </button>
                                `).join('')}
                            </div>
