                bubble.classList.remove('show-observer-hint');
                bubble.querySelectorAll('.message-observer-hover').forEach((hint) => {
                    hint.classList.remove('pinned');
                    hint.style.removeProperty('--observer-left');
                    hint.style.removeProperty('--observer-top');
                    hint.style.display = '';
                });
            });
        };

        const positionObserverHint = (bubble, hint) => {
            if (!bubble || !hint) return;
            const bubbleRect = bubble.getBoundingClientRect();
            const hintRect = hint.getBoundingClientRect();
            const margin = 12;
            const viewportWidth = window.innerWidth || document.documentElement.clientWidth || 1280;
            const viewportHeight = window.innerHeight || document.documentElement.clientHeight || 720;
            const width = Math.min(hintRect.width || 360, viewportWidth - (margin * 2));
            const height = Math.min(hintRect.height || 280, viewportHeight - (margin * 2));
            let left = bubbleRect.right + 10;
            if (left + width > viewportWidth - margin) left = bubbleRect.left - width - 10;
            if (left < margin) left = Math.min(Math.max(margin, bubbleRect.left), viewportWidth - width - margin);
            let top = bubbleRect.top - height + 24;
            if (top < margin || bubbleRect.top < 160) top = bubbleRect.bottom + 8;
            if (top + height > viewportHeight - margin) top = Math.max(margin, viewportHeight - height - margin);
            hint.style.setProperty('--observer-left', `${Math.round(left)}px`);
            hint.style.setProperty('--observer-top', `${Math.round(top)}px`);
