        const footerShortCode = (prefix, index) => `${prefix}${(index + 1).toString(36).toUpperCase().padStart(2, '0').slice(-2)}`;

        const footerFileName = (value = '') => {
            const cleanValue = String(value || '').split('?')[0].split('#')[0];
            const file = cleanValue.split('/').filter(Boolean).pop() || cleanValue;
            try {
                return decodeURIComponent(file).replace(/\.[a-z0-9]{2,5}$/i, '').replace(/[_-]+/g, ' ').trim();
