        const customFunnelUploadKind = (item = {}) => {
            const type = String(item.mediaType || item.type || '').toLowerCase();
            const value = String(item.mediaUrl || item.value || '').toLowerCase();
            if (type.includes('image') || type.includes('video') || type.includes('media')) return 'media';
            if (type.includes('audio') || /\.(mp3|ogg|opus|m4a|aac|wav|webm)(\?|#|$)/.test(value)) return 'audio';
            return 'media';
        };

        const customFunnelFilterKey = (item = {}) => {
            if (item.type === 'audio') return 'audio';
            if (item.type === 'draft') return 'draft';
            const type = String(item.mediaType || item.typeLabel || '').toLowerCase();
            const value = String(item.mediaUrl || item.value || '').toLowerCase();
            if (type.includes('video') || /\.(mp4|webm|mov|m4v)(\?|#|$)/.test(value)) return 'video';
            if (type.includes('image') || /\.(jpg|jpeg|png|webp|gif|heic|heif)(\?|#|$)/.test(value)) return 'image';
            if (item.type === 'media') return 'image';
            return String(item.type || 'item');
        };

        const normalizeCustomFunnelUploads = (items = []) => (Array.isArray(items) ? items : [])
            .map((item, index) => {
                const value = String(item.mediaUrl || item.value || '').trim();
                if (!value) return null;
                const id = String(item.id || `upload_${Date.now()}_${index}_${Math.random().toString(16).slice(2, 6)}`);
                const kind = customFunnelUploadKind(item);
