                const label = String(item.label || customFunnelUploadLabel(value)).trim();
                return {
                    id,
                    code: customFunnelUploadCode(index),
                    type: kind,
                    typeLabel: kind === 'audio' ? 'audio proprio' : (mediaType === 'video' ? 'video proprio' : 'midia propria'),
