        const uploadCustomFunnelFile = async (file, expectedKind = 'media') => {
            if (!file) return;
            const mime = String((typeof effectiveFileMime === 'function' ? effectiveFileMime(file) : file.type) || '').toLowerCase();
            const name = String(file.name || '');
            const isAudio = mime.startsWith('audio/') || /\.(mp3|mpeg|ogg|opus|m4a|aac|wav|webm)$/i.test(name);
            const isImage = mime.startsWith('image/') || /\.(jpg|jpeg|png|webp|gif|heic|heif)$/i.test(name);
            const isVideo = mime.startsWith('video/') || /\.(mp4|mov|webm|m4v)$/i.test(name);
            if (expectedKind === 'audio' && !isAudio) {
                showToast('Escolha um arquivo de audio: MP3, OGG, OPUS, M4A, AAC, WAV ou WEBM.');
                return;
            }
            if (expectedKind === 'media' && !isImage) {
                showToast('Escolha uma imagem: JPG, PNG, WEBP ou GIF.');
                return;
            }
            if (expectedKind === 'video' && !isVideo) {
                showToast('Escolha um video: MP4, MOV ou WEBM.');
                return;
            }
            if (file.size > customFunnelUploadMaxMb * 1024 * 1024) {
                showToast(`Arquivo muito grande. Use ate ${customFunnelUploadMaxMb} MB.`);
                return;
            }
            try {
                setCustomFunnelUploadBusy(true);
                showToast('Importando arquivo para o funil...');
                const title = String(el('customFunnelTextTitleInput')?.value || '').trim();
                const headers = {
                    'Content-Type': 'application/octet-stream',
                    'X-File-Name': encodeURIComponent(file.name || 'arquivo'),
                    'X-File-Label': encodeURIComponent(title || customFunnelUploadLabel(file.name)),
                    'X-File-Mime': encodeURIComponent(mime || '')
                };
                if (state.token) headers.Authorization = `Bearer ${state.token}`;
                const response = await fetch('/api/whatsapp/funnel-media-upload-binary', {
                    method: 'POST',
                    cache: 'no-store',
                    headers,
                    body: file
                });
                const result = await response.json().catch(() => ({}));
                if (!response.ok) throw new Error(result.error || result.message || `Erro ${response.status}`);
                const item = normalizeCustomFunnelUploads([{
                    id: `upload_${Date.now()}_${Math.random().toString(16).slice(2, 8)}`,
                    label: title || result.label || result.fileName || customFunnelUploadLabel(file.name),
                    detail: file.name || result.fileName || result.mediaUrl,
                    value: result.mediaUrl,
                    mediaUrl: result.mediaUrl,
                    mediaType: expectedKind === 'video'
                        ? 'video'
                        : (result.mediaType || (expectedKind === 'audio' ? 'audio' : 'image'))
                }])[0];
                if (!item?.value) throw new Error('Upload sem URL de midia.');
                state.customFunnelUploads = normalizeCustomFunnelUploads([
                    ...(state.customFunnelUploads || []),
                    item
                ]);
                const savedItem = (state.customFunnelUploads || []).find((candidate) => String(candidate.id) === String(item.id)) || item;
                persistCustomFunnelUploads();
                state.customFunnelManagerTypeFilter = expectedKind === 'video' ? 'video' : customFunnelFilterKey(savedItem);
                state.customFunnelManagerTab = 'library';
                syncCustomFunnelManagerTypeTabs();
                renderFooterAudioQuickList((state.audioTemplates || []).filter((template) => template.country === currentTemplateCountry()));
                renderCustomFunnelManagerLibrary();
