                state.customFunnelUploadAddToBlock = false;
                state.customFunnelPendingFile = null;
                state.customFunnelPendingFileKind = '';
                setCustomFunnelUploadBusy(false);
                clearCustomFunnelTextEditor();
                closeCustomFunnelMessageComposer();
                showToast(`${savedItem.code} importado${wasAddToBlock ? ' e adicionado ao bloco' : ''}.`);
            } catch (error) {
