            const isImage = mime.startsWith('image/') || /\.(jpg|jpeg|png|webp|gif|heic|heif)$/i.test(file.name || '');
            const isVideo = mime.startsWith('video/') || /\.(mp4|mov|webm|m4v)$/i.test(file.name || '');
            if (expectedKind === 'audio' && !isAudio) {
