                { code: 'M06', type: 'media', typeLabel: 'video', label: 'Video', detail: footerFileName('/media/sales/shared/prova_social_video_boquet.mp4'), value: '/media/sales/shared/prova_social_video_boquet.mp4', viewOnce: true },
