        const randomBetween = (min, max) => Math.floor(min + Math.random() * (max - min + 1));

        const funnelBlockDelayMs = (step = {}, index = 0) => {
            const stepMode = String(step.delayMode || '').toLowerCase();
            const fixedMs = Math.max(0, Number(step.waitAfterMs || step.delayMinMs || 0));
            const minMs = Math.max(0, Number(step.delayMinMs || step.waitAfterMs || 0));
            const maxMs = Math.max(minMs, Number(step.delayMaxMs || 0));
            if (stepMode === 'random' && maxMs > 0) return randomBetween(minMs, maxMs);
            if (stepMode === 'fixed' && fixedMs > 0) return fixedMs;
            if (fixedMs > 0) return fixedMs;
            const mode = el('funnelPacingMode')?.value || 'safe';
            if (mode === 'safe') {
                return 0;
            }
            if (mode === 'manual') {
                const seconds = Math.min(90, Math.max(5, Number(el('funnelManualDelaySeconds')?.value || 15)));
                return seconds * 1000;
            }
            if (mode === 'slow') {
                return randomBetween(18000, 30000);
            }
            return randomBetween(4000, 8000);
        };

        const funnelStepDelayLabel = (step = {}) => {
            const mode = String(step.delayMode || 'auto');
            const minSeconds = Math.round(Number(step.delayMinMs || step.waitAfterMs || 0) / 1000);
            const maxSeconds = Math.round(Number(step.delayMaxMs || 0) / 1000);
            if (mode === 'random' && maxSeconds > 0) return `Delay randomico ${minSeconds}-${maxSeconds}s`;
            if (mode === 'fixed' && minSeconds > 0) return `Delay fixo ${minSeconds}s`;
            return 'Delay inteligente automatico';
