            ['/media/templates/EC/INICIO_01.ogg', '/media/templates/EC/01_B_Buenos_dias.ogg'],
            ['/media/templates/EC/INICIO_01.mp3', '/media/templates/EC/01_B_Buenos_dias.mp3'],
            ['/media/templates/EC/Inicio_02.ogg', '/media/templates/EC/01_C_Buenos_tardes.ogg'],
            ['/media/templates/EC/Inicio_02.mp3', '/media/templates/EC/01_C_Buenos_tardes.mp3'],
            ['/media/templates/EC/INICIO_02.ogg', '/media/templates/EC/01_C_Buenos_tardes.ogg'],
            ['/media/templates/EC/INICIO_02.mp3', '/media/templates/EC/01_C_Buenos_tardes.mp3']
        ]);

        const normalizeLegacyFunnelMediaValue = (value = '') => {
            const cleanValue = String(value || '').trim();
            if (!cleanValue) return cleanValue;
            if (legacyFunnelMediaAliases.has(cleanValue)) return legacyFunnelMediaAliases.get(cleanValue);
            const lower = cleanValue.toLowerCase();
            for (const [legacy, replacement] of legacyFunnelMediaAliases.entries()) {
                if (legacy.toLowerCase() === lower) return replacement;
            }
            return cleanValue;
        };

        const knownVitPowerCustomBlockValues = new Set([
            'custom_1780182896042_1b91ef',
            'custom_1780196676304_4b628b',
            'custom_1780268918250_4add3e'
        ]);

        const customFunnelBlockProductKey = (block = {}) => {
            const explicit = String(block.productKey || '').trim().toLowerCase();
            if (explicit === 'all') return 'all';
            if (['tex_ultra_ec', 'nitrix_ec', 'vit_power_ec'].includes(explicit)) return explicit;
            if (knownVitPowerCustomBlockValues.has(String(block.value || ''))) return 'vit_power_ec';
            const haystack = [
                block.label,
                block.detail,
                block.value,
                ...(Array.isArray(block.steps) ? block.steps.flatMap((step) => [step.label, step.value]) : [])
            ].filter(Boolean).join(' ').toLowerCase();
            if (/tex[\s_-]*ultra|tex_ultra/.test(haystack)) return 'tex_ultra_ec';
            if (/nitrix|nitric|oxide/.test(haystack)) return 'nitrix_ec';
            if (/vit[\s_-]*power|funciona_vit_power|como_se_toma_vit_power/.test(haystack)) return 'vit_power_ec';
            return 'all';
        };

        const normalizeCustomFunnelBlocks = (blocks = []) => (Array.isArray(blocks) ? blocks : [])
            .map((block, index) => {
                const steps = (Array.isArray(block.steps) ? block.steps : [])
                    .filter((step) => ['audio', 'media', 'draft'].includes(String(step.type || '')) && step.value)
                    .map((step) => ({
                        type: step.type,
                        label: step.label || step.value,
                        value: normalizeLegacyFunnelMediaValue(step.value),
                        waitAfterMs: Number(step.waitAfterMs || 0),
                        delayMode: String(step.delayMode || 'auto'),
                        delayMinMs: Number(step.delayMinMs || step.waitAfterMs || 0),
                        delayMaxMs: Number(step.delayMaxMs || 0),
                        simulateTyping: step.simulateTyping !== false,
                        recordedAudio: step.recordedAudio !== false,
                        viewOnce: step.viewOnce === true
                    }));
                if (!steps.length) return null;
                return {
                    code: customFunnelCode(index + 1),
                    type: 'block',
                    typeLabel: 'bloco',
                    label: block.label || `Bloco ${index + 2}`,
                    detail: block.detail || steps.map((step) => step.label).join(' + '),
                    value: block.value || `custom_${Date.now()}_${index}`,
                    productKey: customFunnelBlockProductKey(block),
                    steps,
                    custom: true
                };
            })
            .filter(Boolean)
            .slice(0, 12);

        const loadCustomFunnelBlocks = () => {
            try {
                state.customFunnelBlocks = normalizeCustomFunnelBlocks(JSON.parse(window.localStorage?.getItem(customFunnelStorageKey) || '[]'));
            } catch {
                state.customFunnelBlocks = [];
            }
        };

        const persistCustomFunnelBlocks = () => {
            const payload = (state.customFunnelBlocks || []).map((block) => ({
                label: block.label,
                detail: block.detail,
                value: block.value,
                productKey: block.productKey,
                steps: block.steps
            }));
            window.localStorage?.setItem(customFunnelStorageKey, JSON.stringify(payload));
        };

        const customFunnelManagerBlocks = () => state.customFunnelBlocks || [];

        const selectedCustomFunnelManagerBlock = () => customFunnelManagerBlocks()
            .find((block) => block.value === state.selectedCustomFunnelManagerValue) || null;

        const syncCustomFunnelManagerTypeTabs = () => {
            document.querySelectorAll('[data-manager-funnel-type-filter]').forEach((button) => {
                button.classList.toggle('active', String(button.dataset.managerFunnelTypeFilter || 'all') === String(state.customFunnelManagerTypeFilter || 'all'));
            });
        };

        const setCustomFunnelManagerMode = (mode = 'browse') => {
            state.customFunnelManagerMode = mode === 'composer' ? 'composer' : 'browse';
            const view = el('customFunnelManagerView');
            if (view) view.dataset.managerMode = state.customFunnelManagerMode;
            const tabs = el('customFunnelManagerTabs');
            if (tabs) tabs.classList.toggle('is-muted', state.customFunnelManagerMode === 'composer');
        };

        const setCustomFunnelManagerTab = (tab = 'library') => {
            const normalized = ['library', 'blocks', 'settings'].includes(String(tab)) ? String(tab) : 'library';
            state.customFunnelManagerTab = normalized;
            const view = el('customFunnelManagerView');
            if (view) view.dataset.managerTab = normalized;
            document.querySelectorAll('[data-custom-funnel-manager-tab]').forEach((button) => {
                button.classList.toggle('active', button.dataset.customFunnelManagerTab === normalized);
            });
            document.querySelectorAll('[data-manager-pane]').forEach((pane) => {
                pane.classList.toggle('active', pane.dataset.managerPane === normalized && state.customFunnelManagerMode !== 'composer');
            });
            if (normalized === 'blocks') {
                renderCustomFunnelDraft();
                renderCustomFunnelManager();
                window.requestAnimationFrame(() => el('customFunnelBlockSearch')?.focus());
            } else if (normalized === 'library') {
                renderCustomFunnelManagerLibrary();
                window.requestAnimationFrame(() => el('customFunnelManagerSearch')?.focus());
            }
        };

        const syncCustomFunnelManagerNavigation = () => {
            setCustomFunnelManagerMode(state.customFunnelManagerMode || 'browse');
            setCustomFunnelManagerTab(state.customFunnelManagerTab || 'library');
        };

        const customFunnelManagerLibraryItems = () => footerFileItems((state.audioTemplates || []).filter((template) => template.country === currentTemplateCountry()))
            .filter((item) => item.type !== 'block');

        const customFunnelPreviewKind = (item = {}) => {
            if (item.type === 'audio') return 'audio';
            if (item.type === 'draft') return 'texto';
            if (item.type === 'media') {
                const value = String(item.value || '').toLowerCase();
                if (/\.(mp4|webm|mov|m4v)(\?|#|$)/.test(value) || String(item.typeLabel || '').toLowerCase().includes('video')) {
                    return 'video';
                }
                return 'imagem';
            }
            return 'item';
        };

        const customFunnelPreviewButtonLabel = (item = {}) => {
            const kind = customFunnelPreviewKind(item);
            if (kind === 'audio') return 'Ouvir';
            if (kind === 'texto') return 'Ler';
            if (kind === 'video') return 'Ver video';
            if (kind === 'imagem') return 'Ver imagem';
            return 'Previa';
        };

        const renderCustomFunnelPreview = (item = null) => {
            const panel = el('customFunnelPreviewPanel');
            if (!panel) return;
            if (!item) {
                state.customFunnelSelectedLibraryCode = '';
                panel.innerHTML = `
                    <div class="custom-funnel-preview-empty">
                        <strong>Previa do item</strong>
                        <span>Use Ouvir, Ler, Ver imagem ou Ver video para conferir antes de montar o funil.</span>
                    </div>
                `;
                return;
            }
            state.customFunnelSelectedLibraryCode = item.code || '';
            const kind = customFunnelPreviewKind(item);
            const title = `${item.code || ''} - ${item.label || item.typeLabel || 'Item'}`.trim();
            const detail = item.detail || item.value || '';
            const source = escapeHtml(absoluteMediaUrl(item.value || ''));
            const text = item.type === 'draft' ? buildDraftTemplate(item.value) : '';
            let body = `<div class="custom-funnel-preview-text">${escapeHtml(detail)}</div>`;
            if (kind === 'audio') {
                body = `<audio controls preload="none" src="${source}"></audio>`;
            } else if (kind === 'video') {
                body = `<video controls preload="metadata" src="${source}"></video>`;
            } else if (kind === 'imagem') {
                body = `<img src="${source}" alt="${escapeHtml(item.label || 'Midia do funil')}">`;
            } else if (kind === 'texto') {
                body = `<div class="custom-funnel-preview-text">${escapeHtml(text || detail || 'Texto sem conteudo.')}</div>`;
            }
            panel.innerHTML = `
                <div class="custom-funnel-preview-content">
                    <strong>${escapeHtml(title)}</strong>
                    <span>${escapeHtml(detail)}</span>
                    ${body}
                </div>
            `;
            renderCustomFunnelManagerLibrary();
        };

        const isCustomFunnelTextItem = (item = {}) => String(item.value || '').startsWith('custom_text:');
        const isCustomFunnelUploadItem = (item = {}) => /^U\d+/i.test(String(item.code || ''));
        const isEditableCustomFunnelItem = (item = {}) => isCustomFunnelTextItem(item) || isCustomFunnelUploadItem(item);

        const updateCustomFunnelBlockStepLabels = (value = '', label = '') => {
            if (!value || !label) return;
            state.customFunnelBlocks = normalizeCustomFunnelBlocks((state.customFunnelBlocks || []).map((block) => ({
                ...block,
                steps: (block.steps || []).map((step) => String(step.value) === String(value)
                    ? { ...step, label }
                    : step)
            })));
            persistCustomFunnelBlocks();
        };

        const editCustomFunnelLibraryItem = (code = '') => {
            const item = customFunnelManagerLibraryItems().find((entry) => String(entry.code) === String(code || ''));
            if (!item) {
                showToast('Item nao encontrado');
                return;
            }
            if (isCustomFunnelTextItem(item)) {
                editCustomFunnelText(item.value);
                return;
            }
            if (isCustomFunnelUploadItem(item)) {
                const upload = (state.customFunnelUploads || []).find((candidate) => String(candidate.code) === String(item.code));
                if (!upload) return;
                const nextTitle = window.prompt('Titulo do arquivo:', upload.label || item.label || '');
                if (nextTitle === null) return;
                const label = String(nextTitle || '').trim();
                if (!label) {
                    showToast('Titulo vazio nao salvo');
                    return;
                }
                state.customFunnelUploads = normalizeCustomFunnelUploads((state.customFunnelUploads || []).map((candidate) => (
                    String(candidate.code) === String(item.code)
                        ? { ...candidate, label, detail: candidate.detail || label }
                        : candidate
                )));
                persistCustomFunnelUploads();
                updateCustomFunnelBlockStepLabels(item.value, label);
                renderFooterAudioQuickList((state.audioTemplates || []).filter((template) => template.country === currentTemplateCountry()));
                renderCustomFunnelManagerLibrary();
                renderCustomFunnelManager();
                showToast('Arquivo atualizado');
            }
        };

        const deleteCustomFunnelLibraryItem = (code = '') => {
            const item = customFunnelManagerLibraryItems().find((entry) => String(entry.code) === String(code || ''));
            if (!item || !isEditableCustomFunnelItem(item)) {
                showToast('Este item fixo nao pode ser excluido aqui');
                return;
            }
            if (!window.confirm(`Excluir "${item.label || item.code}" da biblioteca?`)) return;
            if (isCustomFunnelTextItem(item)) {
                const id = String(item.value || '').replace(/^custom_text:/, '');
                state.customFunnelTexts = normalizeCustomFunnelTexts((state.customFunnelTexts || []).filter((candidate) => String(candidate.id) !== id));
                persistCustomFunnelTexts();
            } else if (isCustomFunnelUploadItem(item)) {
                state.customFunnelUploads = normalizeCustomFunnelUploads((state.customFunnelUploads || []).filter((candidate) => String(candidate.code) !== String(item.code)));
                persistCustomFunnelUploads();
            }
            state.customFunnelBlocks = normalizeCustomFunnelBlocks((state.customFunnelBlocks || []).map((block) => ({
                ...block,
                steps: (block.steps || []).filter((step) => String(step.value) !== String(item.value))
            })));
            persistCustomFunnelBlocks();
            if (state.customFunnelSelectedLibraryCode === item.code) renderCustomFunnelPreview(null);
            renderFooterAudioQuickList((state.audioTemplates || []).filter((template) => template.country === currentTemplateCountry()));
            renderCustomFunnelManagerLibrary();
            renderCustomFunnelManager();
            showToast('Item excluido da biblioteca');
        };

        const renderCustomFunnelLibraryList = ({ targetId = 'customFunnelManagerLibraryList', searchId = 'customFunnelManagerSearch', forBlock = false } = {}) => {
            const box = el(targetId);
            if (!box) return;
            const search = String(el(searchId)?.value || '').trim().toLowerCase();
            const typeFilter = state.customFunnelManagerTypeFilter || 'all';
            const items = customFunnelManagerLibraryItems()
                .filter((item) => {
                    if (typeFilter !== 'all' && customFunnelFilterKey(item) !== typeFilter) return false;
                    if (!search) return true;
                    const haystack = `${item.code} ${item.label} ${item.detail} ${item.typeLabel}`.toLowerCase();
                    return haystack.includes(search);
                })
                .slice(0, 100);
            box.innerHTML = `
                <div class="funnel-library-hint">${forBlock
                    ? 'Biblioteca de montagem: clique em Adicionar ao bloco para criar a sequencia.'
                    : 'Biblioteca pronta: edite arquivos proprios, confira preview ou use a aba Blocos para montar funis.'}</div>
                ${items.map((item) => {
                    const editable = isEditableCustomFunnelItem(item);
                    const selected = String(item.code || '') === String(state.customFunnelSelectedLibraryCode || '');
                    return `
                    <div class="funnel-file-item is-library-only ${selected ? 'selected' : ''}">
                        <span class="funnel-file-code">${escapeHtml(item.code)}</span>
                        <span class="funnel-file-name">
                            <strong>${escapeHtml(item.label)}</strong>
                            <span>${escapeHtml(item.detail || item.value || '')}</span>
                        </span>
                        <span class="funnel-file-type">${escapeHtml(item.typeLabel)}</span>
                        <span class="funnel-file-actions">
                            ${editable ? `<button class="funnel-file-preview" data-custom-funnel-edit-code="${escapeHtml(item.code)}" type="button">Editar</button>` : ''}
                            ${editable ? `<button class="funnel-file-preview danger" data-custom-funnel-delete-code="${escapeHtml(item.code)}" type="button">Excluir</button>` : ''}
                            <button class="funnel-file-preview" data-custom-funnel-preview-code="${escapeHtml(item.code)}" type="button" title="Conferir antes de adicionar">${escapeHtml(customFunnelPreviewButtonLabel(item))}</button>
                            ${forBlock ? `<button class="funnel-file-add" data-custom-funnel-add-code="${escapeHtml(item.code)}" type="button" title="Adicionar este codigo ao bloco">Adicionar ao bloco</button>` : ''}
                        </span>
                    </div>
                `; }).join('') || '<button class="funnel-file-item" type="button" disabled>Nenhum item encontrado.</button>'}
            `;
        };

        const renderCustomFunnelManagerLibrary = () => {
            renderCustomFunnelLibraryList({
                targetId: 'customFunnelManagerLibraryList',
                searchId: 'customFunnelManagerSearch',
                forBlock: false
            });
            renderCustomFunnelLibraryList({
                targetId: 'customFunnelBlockLibraryList',
                searchId: 'customFunnelBlockSearch',
                forBlock: true
            });
        };

        const renderCustomFunnelManager = () => {
            const list = el('customFunnelManagerList');
            const detail = el('customFunnelManagerDetail');
            if (!list || !detail) return;
            renderCustomFunnelManagerLibrary();
            const blocks = customFunnelManagerBlocks();
            if (!blocks.length) {
                state.selectedCustomFunnelManagerValue = '';
                list.innerHTML = '<div class="custom-funnel-section-title">Blocos salvos</div><div class="custom-funnel-manager-empty">Nenhum bloco personalizado salvo ainda.</div>';
                detail.innerHTML = `
                    <div class="custom-funnel-manager-detail-title">
                        <strong>Sem bloco selecionado</strong>
                        <span>Monte um bloco nesta tela para liberar edicao, duplicacao ou exclusao.</span>
                    </div>
                    <div class="custom-funnel-manager-actions">
                        <button data-custom-funnel-manager-action="back" type="button">Voltar</button>
                    </div>
                `;
                return;
            }
            if (!selectedCustomFunnelManagerBlock()) {
                state.selectedCustomFunnelManagerValue = blocks[0].value;
            }
            const selected = selectedCustomFunnelManagerBlock();
            const selectedSteps = (selected?.steps || []).map((step, index) => `
                <li>
                    <strong>${escapeHtml(String(index + 1).padStart(2, '0'))}</strong>
                    <span>${escapeHtml(`${step.label || step.value || 'Item do bloco'} - ${funnelStepDelayLabel(step)}`)}</span>
                    <em>${escapeHtml(funnelStepActionLabel(step))}</em>
                </li>
            `).join('');
            list.innerHTML = `
                <div class="custom-funnel-section-title">Blocos salvos <span>${blocks.length}</span></div>
                ${blocks.map((block) => `
                <button class="custom-funnel-manager-card ${block.value === state.selectedCustomFunnelManagerValue ? 'active' : ''}" data-custom-funnel-manager-select="${escapeHtml(block.value)}" type="button">
                    <span class="custom-funnel-manager-code">${escapeHtml(block.code || 'B')}</span>
                    <span class="custom-funnel-manager-name">
                        <strong>${escapeHtml(block.label || 'Bloco personalizado')}</strong>
                        <span>${escapeHtml(block.detail || 'Sem detalhes')}</span>
                    </span>
                </button>
                `).join('')}
            `;
            detail.innerHTML = `
                <div class="custom-funnel-manager-detail-title">
                    <strong>${escapeHtml(selected?.label || 'Bloco selecionado')}</strong>
                    <span>${escapeHtml(selected?.detail || 'Escolha uma acao para este bloco.')}</span>
                </div>
                <ul class="custom-funnel-manager-steps">
                    ${selectedSteps || '<li><strong>00</strong><span>Nenhum item encontrado neste bloco.</span><em>vazio</em></li>'}
                </ul>
                <div class="custom-funnel-manager-actions">
                    <button data-custom-funnel-manager-action="edit" type="button">Editar</button>
                    <button class="copy" data-custom-funnel-manager-action="duplicate" type="button">Duplicar</button>
                    <button class="danger" data-custom-funnel-manager-action="delete" type="button">Excluir</button>
                    <button data-custom-funnel-manager-action="back" type="button">Voltar</button>
                </div>
            `;
        };

        const openCustomFunnelManager = () => {
            const drawer = document.querySelector('.composer-funnel-drawer');
            drawer?.classList.remove('side-open', 'manager-open');
            drawer?.style.removeProperty('--funnel-panel-left');
            drawer?.style.removeProperty('--funnel-panel-top');
            drawer?.style.removeProperty('--funnel-panel-width');
            drawer?.style.removeProperty('--funnel-panel-height');
            drawer?.style.removeProperty('--funnel-panel-max-height');
            if (drawer) drawer.open = false;
            document.body.classList.add('funnel-manager-active');
            el('funnelManagerPage')?.classList.remove('hidden');
            el('funnelManagerPage')?.setAttribute('aria-hidden', 'false');
            state.customFunnelManagerMode = 'browse';
            state.customFunnelManagerTab = state.customFunnelManagerTab || 'library';
            syncCustomFunnelManagerTypeTabs();
            syncCustomFunnelMessageType();
            syncCustomFunnelManagerNavigation();
            renderCustomFunnelManager();
            closeCustomFunnelMessageComposer();
        };

        const closeCustomFunnelManager = () => {
            document.body.classList.remove('funnel-manager-active');
            el('funnelManagerPage')?.classList.add('hidden');
            el('funnelManagerPage')?.setAttribute('aria-hidden', 'true');
            closeCustomFunnelMessageComposer();
        };

        const duplicateCustomFunnelBlock = (value = '') => {
            const block = (state.customFunnelBlocks || []).find((item) => item.value === value);
            if (!block) {
                showToast('Bloco personalizado nao encontrado');
                return;
            }
            const clone = {
                label: `${block.label || 'Bloco personalizado'} copia`,
                detail: block.detail || '',
                value: `custom_${Date.now()}_${Math.random().toString(16).slice(2, 8)}`,
                productKey: block.productKey || activeFunnelProductKey(),
                steps: (block.steps || []).map((step) => ({ ...step }))
            };
            state.customFunnelBlocks = normalizeCustomFunnelBlocks([
                ...(state.customFunnelBlocks || []),
                clone
            ]);
            const savedClone = state.customFunnelBlocks[state.customFunnelBlocks.length - 1];
            state.selectedCustomFunnelManagerValue = savedClone?.value || '';
            persistCustomFunnelBlocks();
            renderFooterAudioQuickList((state.audioTemplates || []).filter((template) => template.country === currentTemplateCountry()));
            renderCustomFunnelManagerLibrary();
            renderCustomFunnelManager();
            showToast('Bloco duplicado');
        };

        const handleCustomFunnelManagerAction = (action = '') => {
            if (action === 'back') {
                closeCustomFunnelManager();
                return;
            }
            const block = selectedCustomFunnelManagerBlock();
            if (!block) {
                showToast('Selecione um bloco personalizado');
                return;
            }
            if (action === 'edit') {
                editCustomFunnelBlock(block.value);
                el('customFunnelName')?.focus();
                return;
            }
            if (action === 'duplicate') {
                duplicateCustomFunnelBlock(block.value);
                return;
            }
            if (action === 'delete') {
                deleteCustomFunnelBlock(block.value);
                if (state.selectedCustomFunnelManagerValue === block.value) {
                    state.selectedCustomFunnelManagerValue = '';
                }
                renderCustomFunnelManager();
            }
        };

        const renderCustomFunnelDraft = () => {
            const box = el('customFunnelDraftList');
            if (!box) return;
            const steps = state.customFunnelDraftSteps || [];
            box.innerHTML = steps.length
                ? steps.map((step, index) => `
                    <article class="custom-funnel-timeline-card" draggable="true" data-custom-funnel-drag-index="${escapeHtml(index)}">
                        <div class="custom-funnel-timeline-head">
                            <em>${escapeHtml(step.code || step.typeLabel || step.type)}</em>
                            <strong>${escapeHtml(step.label || step.value || 'Item do bloco')}</strong>
                        </div>
                        <div class="custom-funnel-timeline-flow" aria-label="Sequencia do funil">
                            <span>${escapeHtml(funnelStepActionLabel(step))}</span>
                            <b>></b>
                            <span>${escapeHtml(funnelStepDelayLabel(step))}</span>
                            <b>></b>
                            <span>${escapeHtml(index < steps.length - 1 ? 'Proxima acao' : 'Fim do bloco')}</span>
                        </div>
                        <button class="custom-funnel-timeline-remove" data-custom-funnel-remove-step="${escapeHtml(index)}" type="button" title="Remover">Remover</button>
                    </article>
                `).join('')
                : '<span class="meta">Use + item e informe codigo como A08, M01 ou T02.</span>';
        };

        const blockDraftSteps = (block = {}) => {
            const items = footerFileItems((state.audioTemplates || []).filter((template) => template.country === currentTemplateCountry()));
            return (Array.isArray(block.steps) ? block.steps : [])
                .filter((step) => ['audio', 'media', 'draft'].includes(String(step.type || '')) && step.value)
                .map((step) => {
                    const item = items.find((candidate) => String(candidate.type) === String(step.type) && String(candidate.value) === String(step.value));
                    return {
                        code: item?.code || step.code || step.type,
                        type: step.type,
                        typeLabel: item?.typeLabel || step.typeLabel || step.type,
                        label: step.label || item?.label || step.value,
                        value: step.value,
                        waitAfterMs: Number(step.waitAfterMs || 0),
                        delayMode: String(step.delayMode || 'auto'),
                        delayMinMs: Number(step.delayMinMs || step.waitAfterMs || 0),
                        delayMaxMs: Number(step.delayMaxMs || 0),
                        simulateTyping: step.simulateTyping !== false,
                        recordedAudio: step.recordedAudio !== false
                    };
                });
        };

        const addCustomFunnelStepByCode = () => {
            const raw = window.prompt('Digite o codigo do item para adicionar ao bloco (ex.: A08, M01, T02):');
            const code = String(raw || '').trim().toUpperCase();
            addCustomFunnelStepFromCode(code);
        };

        const customFunnelDelayConfigFromInputs = () => {
            const mode = String(el('customFunnelStepDelayMode')?.value || 'auto');
            const minSeconds = Math.max(0, Math.min(600, Number(el('customFunnelStepDelaySeconds')?.value || 0)));
            const maxSeconds = Math.max(minSeconds, Math.min(600, Number(el('customFunnelStepDelayMaxSeconds')?.value || 0)));
            if (mode === 'fixed') {
                if (minSeconds <= 0) {
                    showToast('Informe o delay fixo em segundos');
                    return null;
                }
                return {
                    delayMode: 'fixed',
                    waitAfterMs: minSeconds * 1000,
                    delayMinMs: minSeconds * 1000,
                    delayMaxMs: 0
                };
            }
            if (mode === 'random') {
                if (minSeconds <= 0 || maxSeconds <= minSeconds) {
                    showToast('Delay randomico precisa de min e max validos');
                    return null;
                }
                return {
                    delayMode: 'random',
                    waitAfterMs: 0,
                    delayMinMs: minSeconds * 1000,
                    delayMaxMs: maxSeconds * 1000
                };
            }
            return {
                delayMode: 'auto',
                waitAfterMs: 0,
                delayMinMs: 0,
                delayMaxMs: 0
            };
        };

        const addCustomFunnelStepFromCode = (codeValue = '') => {
            const code = String(codeValue || '').trim().toUpperCase();
            if (!code) return;
            const country = currentTemplateCountry();
            const item = footerFileItems((state.audioTemplates || []).filter((template) => template.country === country))
                .find((candidate) => {
                    const candidateText = normalizeFunnelSearchText([
                        candidate.code,
                        candidate.label,
                        candidate.detail,
                        candidate.value,
                        candidate.mediaUrl,
                        candidate.previewUrl
                    ].filter(Boolean).join(' '));
                    const target = normalizeFunnelSearchText(code);
                    return candidateText === target || candidateText.includes(target) || target.includes(candidateText);
                });
            if (!item || item.type === 'block') {
                showToast('Codigo nao encontrado ou bloco dentro de bloco nao permitido');
                return;
            }
            const delayConfig = customFunnelDelayConfigFromInputs();
            if (!delayConfig) return;
            state.customFunnelDraftSteps = [
                ...(state.customFunnelDraftSteps || []),
                {
                    code: item.code,
                    type: item.type,
                    typeLabel: item.typeLabel,
                    label: item.label,
                    value: item.value,
                    ...delayConfig,
                    simulateTyping: item.type === 'draft',
                    recordedAudio: item.type === 'audio',
                    viewOnce: item.viewOnce === true
                }
            ].slice(0, 12);
            renderCustomFunnelDraft();
            showToast('Item adicionado ao bloco');
        };

        const saveCustomFunnelText = ({ addToBlock = false } = {}) => {
            const input = el('customFunnelTextInput');
            const titleInput = el('customFunnelTextTitleInput');
            const text = String(input?.value || '').trim();
            if (!text) {
                showToast('Digite o texto proprio antes de salvar');
                input?.focus();
                return;
            }
            const title = String(titleInput?.value || '').trim();
            const editingId = String(state.editingCustomFunnelTextId || '');
            const item = normalizeCustomFunnelTexts([{
                id: editingId || `text_${Date.now()}_${Math.random().toString(16).slice(2, 8)}`,
                label: title || customFunnelTextLabel(text),
                text
            }])[0];
            if (!item) return;
            state.customFunnelTexts = normalizeCustomFunnelTexts(editingId
                ? (state.customFunnelTexts || []).map((candidate) => String(candidate.id) === editingId ? item : candidate)
                : [
                    ...(state.customFunnelTexts || []),
                    item
