            const label = (el('customFunnelName')?.value || '').trim() || `Bloco personalizado ${state.customFunnelBlocks.length + 1}`;
            const isEditingBlock = Boolean(state.editingCustomFunnelBlockValue);
            const value = state.editingCustomFunnelBlockValue || `custom_${Date.now()}_${Math.random().toString(16).slice(2, 8)}`;
