                        { type: 'audio', label: 'Inicio universal 02', value: UNIVERSAL_INTRO_AUDIO_02_EC },
                        { type: 'media', label: 'Prova 1', value: '/media/sales/shared/social_01.jpeg' },
                        { type: 'media', label: 'Frasco Vit Power', value: '/media/sales/ec/vit_power.jpeg', waitAfterMs: 0 }
                    ]
                }];
            const customBlocks = (state.customFunnelBlocks || [])
                .filter((block) => block.productKey === 'all' || block.productKey === selectedProductKey)
                .map((block, index) => ({ ...block, code: customFunnelCode(defaultBlocks.length + index) }));
            return [
                ...defaultBlocks,
                ...customBlocks
            ];
        };

        const sortedFooterAudioTemplates = (templates = []) => [...templates]
            .sort((a, b) => {
                const aLabel = `${a.label || ''} ${a.id || ''}`;
                const bLabel = `${b.label || ''} ${b.id || ''}`;
                const ag = footerFunnelGroupInfo(a);
                const bg = footerFunnelGroupInfo(b);
                if (ag.order !== bg.order) return ag.order - bg.order;
                const ai = footerAudioPriorityLabels.findIndex((pattern) => pattern.test(aLabel));
                const bi = footerAudioPriorityLabels.findIndex((pattern) => pattern.test(bLabel));
                const as = ai === -1 ? 999 : ai;
                const bs = bi === -1 ? 999 : bi;
                return as - bs || String(a.label || a.id || '').localeCompare(String(b.label || b.id || ''), undefined, { numeric: true, sensitivity: 'base' });
            });

        const footerAudioCodeForMediaUrl = (mediaUrl = '') => {
            const country = currentTemplateCountry();
            const templates = sortedFooterAudioTemplates((state.audioTemplates || []).filter((template) => template.country === country));
            const index = templates.findIndex((template) => String(template.mediaUrl || '') === String(mediaUrl || ''));
            return index === -1 ? '' : footerShortCode('A', index);
        };

        const footerFileItems = (templates = []) => [
            ...footerFunnelBlocks(),
            ...footerDraftFiles(),
            ...sortedFooterAudioTemplates(templates).map((template, index) => ({
                code: footerShortCode('A', index),
                type: 'audio',
                typeLabel: 'audio',
                label: funnelAudioLabel(template),
                detail: `${footerFunnelGroupInfo(template).label} - ${footerFileName(template.mediaUrl || template.previewUrl || template.id || '')}`,
                value: template.mediaUrl
            })),
            ...(state.customFunnelUploads || []),
            ...footerMediaFiles()
        ];

        const renderFunnelMemory = () => {
            const strip = el('funnelMemoryStrip');
            const list = el('funnelMemoryList');
            if (!strip || !list) return;
            const refs = (state.recentFunnelRefs || []).slice(0, 6);
            strip.classList.toggle('active', Boolean(refs.length));
            list.innerHTML = refs.map((item) => `
                <button
                    class="funnel-memory-chip"
                    data-footer-file-type="${escapeHtml(item.type)}"
                    data-footer-file-value="${escapeHtml(item.value)}"
                    type="button"
                    title="${escapeHtml(item.detail || item.label || '')}">
                    <strong>${escapeHtml(item.code || item.typeLabel || '')}</strong>
                    <span>${escapeHtml(item.label || item.value || '')}</span>
                </button>
            `).join('');
        };

        const rememberFunnelRef = (item = {}) => {
            if (!item.value && !item.label) return;
            const normalized = {
                code: item.code || '',
                type: item.type || 'draft',
                typeLabel: item.typeLabel || item.type || '',
                label: item.label || item.value || '',
                detail: item.detail || item.value || '',
                value: item.value || ''
            };
            state.recentFunnelRefs = [
                normalized,
                ...(state.recentFunnelRefs || []).filter((ref) => `${ref.type}:${ref.value}` !== `${normalized.type}:${normalized.value}`)
            ].slice(0, 6);
            renderFunnelMemory();
            renderComposerQuickStatusBar();
        };

        const findFooterFileItem = (type, value) => footerFileItems((state.audioTemplates || []).filter((template) => template.country === currentTemplateCountry()))
            .find((item) => {
                if (String(item.type) !== String(type)) return false;
                const target = normalizeFunnelSearchText(String(value || '').replace(/\.[a-z0-9]{2,5}$/i, ''));
                if (!target) return false;
                const candidateText = normalizeFunnelSearchText([
                    item.code,
                    item.label,
                    item.detail,
                    item.value,
                    item.mediaUrl,
                    item.previewUrl
                ].filter(Boolean).join(' '));
                return candidateText === target || candidateText.includes(target) || target.includes(candidateText);
            });

        const normalizeFunnelSearchText = (value = '') => String(value || '')
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .toLowerCase()
            .replace(/[^a-z0-9]+/g, ' ')
            .trim();

        const funnelSearchTokens = (value = '') => normalizeFunnelSearchText(value)
            .split(/\s+/)
            .filter(Boolean);

        const funnelSearchInitials = (value = '') => funnelSearchTokens(value)
            .map((token) => token[0] || '')
            .join('');

        const matchesFunnelSearch = (item = {}, rawSearch = '') => {
            const search = normalizeFunnelSearchText(rawSearch);
            if (!search) return true;
            const fields = [
                item.code,
                item.label,
                item.detail,
                item.typeLabel,
                item.value
            ].filter(Boolean);
            const haystack = normalizeFunnelSearchText(fields.join(' '));
            if (haystack.includes(search)) return true;
            const compactSearch = search.replace(/\s+/g, '');
            if (!compactSearch) return true;
            if (fields.some((field) => normalizeFunnelSearchText(field).replace(/\s+/g, '').includes(compactSearch))) return true;
            const tokens = funnelSearchTokens(fields.join(' '));
            if (tokens.some((token) => token.startsWith(compactSearch))) return true;
            const initialSets = fields.map(funnelSearchInitials).filter(Boolean);
            if (initialSets.some((initials) => initials.startsWith(compactSearch) || initials.includes(compactSearch))) return true;
            return tokens.filter((token) => token[0] === compactSearch[0]).some((token) => token.startsWith(compactSearch));
        };

        const syncFunnelSearchFromInput = () => {
            const input = el('funnelFileSearch');
            if (input) state.funnelSearchText = input.value || '';
            return state.funnelSearchText || '';
        };

        const restoreFunnelSearchInput = ({ focus = false } = {}) => {
            const input = el('funnelFileSearch');
            if (!input) return;
            const value = state.funnelSearchText || '';
            if (input.value !== value) input.value = value;
            if (focus) {
                input.focus();
                const caret = input.value.length;
                input.setSelectionRange?.(caret, caret);
            }
        };

        const quickStatusItems = () => {
            const countryTemplates = (state.audioTemplates || []).filter((template) => template.country === currentTemplateCountry());
            const all = footerFileItems(countryTemplates);
            const recent = (state.recentFunnelRefs || []).map((ref) => findFooterFileItem(ref.type, ref.value) || ref);
            const groups = [
                recent,
                all.filter((item) => item.type === 'block').slice(0, 4),
                all.filter((item) => item.type === 'audio').slice(0, 4),
                all.filter((item) => item.type === 'draft').slice(0, 3),
                all.filter((item) => item.type === 'media').slice(0, 3)
            ];
            const seen = new Set();
            return groups.flat().filter((item) => {
                const key = `${item.type}:${item.value}`;
                if (!item.value || seen.has(key)) return false;
                seen.add(key);
                return true;
            }).slice(0, 12);
        };

