            const data = await api(`/api/whatsapp/templates?country=${encodeURIComponent(country)}`);
            const otherCountryTemplates = state.audioTemplates.filter((template) => template.country !== country);
            state.audioTemplates = [...otherCountryTemplates, ...(data.templates || [])];
            renderAudioTemplates();
            renderActionableSamples();
        }

        async function sendFunnelAudio(mediaUrl, button) {
