            const values = [year, month, day];
            const complete = values.every((field) => field.value && field.validity.valid)
                && /^\d{4}$/.test(year.value);
            const iso = complete ? `${year.value}-${month.value.padStart(2, '0')}-${day.value.padStart(2, '0')}` : '';
            el('customerBuyLaterDateInput').value = iso;
