        const mimeFromFileName = (name = '') => {
            const ext = String(name || '').toLowerCase().split('.').pop() || '';
            const map = {
                jpg: 'image/jpeg',
                jpeg: 'image/jpeg',
                png: 'image/png',
                webp: 'image/webp',
                gif: 'image/gif',
                heic: 'image/heic',
                heif: 'image/heif',
                mp3: 'audio/mpeg',
                mpeg: 'audio/mpeg',
                ogg: 'audio/ogg',
                opus: 'audio/ogg',
                m4a: 'audio/mp4',
                aac: 'audio/aac',
                wav: 'audio/wav',
                webm: 'video/webm',
                mp4: 'video/mp4',
                mov: 'video/quicktime'
            };
            return map[ext] || '';
        };

        const effectiveFileMime = (file) => {
            const explicit = String(file?.type || '').toLowerCase();
            if (explicit && explicit !== 'application/octet-stream') return explicit;
            return mimeFromFileName(file?.name || '') || explicit;
        };

        const mediaKindFromFile = (file) => {
            const mime = effectiveFileMime(file);
            if (mime.startsWith('image/')) return 'imagem';
            if (mime.startsWith('video/')) return 'video';
            if (mime.startsWith('audio/')) return 'audio';
            return 'midia';
        };

        const mediaTypeFromFile = (file) => {
            const mime = effectiveFileMime(file);
            if (mime.startsWith('image/')) return 'image';
            if (mime.startsWith('video/')) return 'video';
            if (mime.startsWith('audio/')) return 'audio';
            return 'media';
        };

        const manualTypingDelaySeconds = (text = '') => {
            const chars = String(text || '').trim().length;
            if (!chars) return 0;
            return Math.max(2, Math.min(12, Math.ceil(chars / 18)));
        };

        const manualRecordingDelaySeconds = (file) => {
            const kind = mediaTypeFromFile(file);
            if (kind === 'audio') return 6;
            if (kind === 'video') return 4;
            if (kind === 'image') return 2;
            return 2;
        };

        const readFileAsDataUrl = (file) => new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = () => {
                const value = String(reader.result || '');
                const mime = effectiveFileMime(file);
                if (mime && value.startsWith('data:application/octet-stream;')) {
                    resolve(value.replace(/^data:application\/octet-stream;/, `data:${mime};`));
                    return;
                }
                if (mime && value.startsWith('data:;')) {
                    resolve(value.replace(/^data:;/, `data:${mime};`));
                    return;
                }
                resolve(value);
            };
            reader.onerror = () => reject(reader.error || new Error('Nao foi possivel ler o arquivo.'));
            reader.readAsDataURL(file);
        });

        async function sendMediaAttachment(file) {
            if (!state.selectedChat || state.sendingMessage || !file) return;
            if (!/^(image|video|audio)\//i.test(effectiveFileMime(file) || '')) {
                showToast('Selecione apenas imagem, video ou audio.');
                return;
            }
            const maxBytes = 16 * 1024 * 1024;
            if (file.size > maxBytes) {
                showToast('Arquivo muito grande. Use ate 16 MB para envio pelo painel.');
                return;
            }
            if (
                window.VitalismenCleanChatV29?.isGuideMediaCandidate(file.name || '')
                && state.customerProfile?.shipment?.allowGuideImage !== true
            ) {
                showToast('PEDIDO AINDA NÃO ESTÁ LIBERADO PARA RETIRADA');
                return;
            }
            const attachButton = el('attachMediaBtn');
            const sendButton = el('sendBtn');
            const originalAttachText = attachButton.textContent;
            state.sendingMessage = true;
            attachButton.disabled = true;
            sendButton.disabled = true;
            attachButton.textContent = '...';
            let apiResponded = false;
            let pendingMessage = null;
            try {
                const dataUrl = await readFileAsDataUrl(file);
                pendingMessage = appendLocalMessage(`Enviando ${mediaKindFromFile(file)}`, {
                    type: mediaTypeFromFile(file),
                    mediaUrl: dataUrl,
                    mediaPreviewUrl: dataUrl
                });
                const result = await api('/api/whatsapp/send', {
                    method: 'POST',
                    body: JSON.stringify({
                        phone: currentChatPhone(),
                        message: dataUrl,
                        isMedia: true,
                        fileName: file.name || '',
                        clientGeneratedId: pendingMessage?.clientGeneratedId || '',
                        sessionId,
                        delayTypingSeconds: manualRecordingDelaySeconds(file),
                        recordedAudio: mediaTypeFromFile(file) === 'audio',
                        sendMode: 'manual_panel',
                        allowAudioDedupeBypass: true,
                        country: state.country || state.selectedChat?.country || 'EC'
                    })
                });
                apiResponded = true;
                if (!result?.success) {
                    await loadSelectedMessages({ force: true });
                    throw new Error(result?.error || 'WhatsApp nao retornou confirmacao da midia; confira no aparelho.');
                }
                if (pendingMessage?._id) confirmPendingLocalMessage(pendingMessage._id, result);
                showToast(`${mediaKindFromFile(file)} enviado`);
                loadSelectedMessages({ force: true }).catch(() => null);
                loadChats().catch(() => null);
                window.setTimeout(() => loadActionableSamples().catch(() => null), 900);
            } catch (error) {
                if (pendingMessage?._id) {
                    state.pendingLocalMessages = (state.pendingLocalMessages || []).map((item) => (
                        String(item._id || '') === String(pendingMessage._id)
                            ? { ...item, deliveryStatus: 'unconfirmed' }
                            : item
                    ));
                }
                loadSelectedMessages({ force: true }).catch(() => null);
                showToast(error.message);
            } finally {
                state.sendingMessage = false;
                attachButton.textContent = originalAttachText;
                attachButton.disabled = !state.selectedChat;
                el('mediaFileInput').value = '';
                el('messageInput').focus();
                updateMessageComposerControls();
            }
        }

        const clipboardFilesFromPasteEvent = (event) => {
            const data = event.clipboardData;
            if (!data) return [];
            const directFiles = Array.from(data.files || []);
            const itemFiles = Array.from(data.items || [])
                .filter((item) => item.kind === 'file')
                .map((item) => item.getAsFile())
                .filter(Boolean);
            const files = [...directFiles, ...itemFiles];
            return files.filter((file, index) => (
                file
                && /^(image|video|audio)\//i.test(effectiveFileMime(file) || '')
                && files.findIndex((candidate) => (
                    candidate
                    && candidate.name === file.name
                    && candidate.size === file.size
                    && candidate.type === file.type
                )) === index
            ));
        };

        const handleComposerPaste = (event) => {
            const files = clipboardFilesFromPasteEvent(event);
            if (!files.length) return;
            event.preventDefault();
            if (!state.selectedChat) {
                showToast('Selecione um cliente antes de colar imagem, audio ou video.');
                return;
            }
            if (state.sendingMessage) {
                showToast('Aguarde o envio atual terminar.');
                return;
            }
            (async () => {
                for (const file of files) {
                    await sendMediaAttachment(file);
                }
            })().catch((error) => showToast(error.message));
        };

