                    document.querySelectorAll('[data-dropi-filter]').forEach((item) => item.classList.toggle('active', item.dataset.dropiFilter === 'not_sent'));
                    await Promise.all([loadShipments(), loadChats()]);
                } else if (action === 'prepare-dropi') {
                    const country = button.dataset.country || selectedOperationalCountry();
                    if (!confirmManualDropiAction(orderId, country, action)) return;
                    const result = await prepareDropiOrder(orderId, country);
