                    const country = button.dataset.country || selectedOperationalCountry();
                    if (!confirmManualDropiAction(orderId, country, action)) return;
                    await api(routes[action], {
                        method: 'POST',
                        body: action === 'confirm-pickup'
                            ? JSON.stringify({ sendBonus: true })
                            : action === 'send-to-review'
                                ? JSON.stringify({ reason: 'operator_sent_from_confirmed_panel' })
                            : action === 'finalize-review'
                                ? JSON.stringify({ reason: 'operator_finalized_from_conferir_pedidos' })
                            : action === 'notify-guide'
                                ? JSON.stringify({ force: true })
                            : action === 'notify-pickup'
                                ? JSON.stringify({ force: true })
                            : action === 'delete-fake'
                                ? JSON.stringify({ reason: 'fake_order_deleted_from_panel' })
                            : action === 'remove-from-confirmed'
                                ? JSON.stringify({ reason: window.prompt('Motivo: duplicado, nao e pedido, cliente desistiu ou outro?', 'duplicado') || 'removido_pelo_painel' })
                                : action === 'requeue-dropi'
                                    ? JSON.stringify({ reason: 'operator_requeue_from_panel' })
                                : undefined
                    });
                    showToast(action === 'mark-manual-sent'
                        ? 'Pedido marcado como enviado manual'
                        : action === 'send-to-review'
                            ? 'Pedido enviado para Conferir Pedidos'
                        : action === 'finalize-review'
                            ? 'Pedido arquivado da conferencia'
                        : action === 'requeue-dropi'
                            ? 'Pedido voltou para 2 Enviar para Dropi'
                        : action === 'delete-fake'
                            ? 'Pedido fake excluido do painel'
                        : action === 'remove-from-confirmed'
                            ? 'Pedido removido da fila de Confirmados'
