        async function processSelectedDropiOrders() {
            if (state.busy || !state.selectedDropiOrders.size) return;
            const selectedOrders = [...state.selectedDropiOrders]
                .map((orderId) => state.dropiItems.find((item) => item.type === 'order' && item.order?.orderId === orderId)?.order)
                .filter(Boolean);
            if (!selectedOrders.length) {
                showToast('Nenhum pedido selecionado encontrado na lista atual');
                return;
            }
            const blockedBrazil = selectedOrders.filter(isBrazilTestRecord);
            if (blockedBrazil.length) {
                blockedBrazil.forEach((order) => state.selectedDropiOrders.delete(order.orderId));
                renderShipments();
                showToast(`${blockedBrazil.length} pedido(s) BR teste removido(s). Eles nunca vao para Dropi.`);
                return;
            }
            const authorizing = state.dropiFilter === 'confirmed';
            const ok = authorizing
                ? window.confirm(`Autorizar ${selectedOrders.length} pedido(s) para entrar na etapa 2 Enviar para Dropi?\n\nNada sera enviado agora. O envio real exige outro clique em Enviar para Dropi.`)
                : confirmBulkDropiSubmission(selectedOrders);
            if (!ok) return;

            state.busy = true;
            renderShipments();
            let success = 0;
            let manual = 0;
            let failed = 0;
            try {
                for (const order of selectedOrders) {
                    state.dropiProcessStatus[order.orderId] = {
                        kind: 'running',
                        label: authorizing ? 'autorizando' : 'enviando',
                        message: authorizing ? 'Autorizando para envio...' : 'Enviando para Dropi agora...'
                    };
                    el('bulkDropiSummary').textContent = `${authorizing ? 'Autorizando' : 'Processando'} ${order.orderId}...`;
                    renderShipments();
                    try {
                        if (authorizing) {
                            await authorizeDropiOrder(order.orderId, order.country);
                            success += 1;
                            state.dropiProcessStatus[order.orderId] = {
                                kind: 'pending',
                                label: 'autorizado',
                                message: 'Autorizado para etapa 2 Enviar para Dropi'
                            };
                            state.selectedDropiOrders.delete(order.orderId);
                            renderShipments();
                            continue;
                        }
                        const result = await submitDropiOrder(order.orderId, order.country);
                        if (result.paymentRequired) {
                            manual += 1;
                            state.dropiProcessStatus[order.orderId] = {
                                kind: 'manual',
                                label: 'aguardando saldo',
                                message: result.message || 'Dropi chegou ate o envio, mas falta saldo.'
                            };
                        } else if (result.manualSendRequired) {
                            manual += 1;
                            state.dropiProcessStatus[order.orderId] = {
                                kind: 'manual',
                                label: 'envio manual',
                                message: result.message || 'Dropi pediu envio manual.'
                            };
                        } else {
                            success += 1;
                            state.dropiProcessStatus[order.orderId] = {
                                kind: 'success',
                                label: 'pedido enviado',
                                message: dropiSuccessMessage(result)
                            };
                        }
                        state.selectedDropiOrders.delete(order.orderId);
                    } catch (error) {
                        failed += 1;
                        state.dropiProcessStatus[order.orderId] = {
                            kind: 'error',
                            label: 'erro',
                            message: error.message || 'Erro ao enviar para Dropi.'
                        };
                        showToast(`${order.orderId}: ${error.message}`);
                    }
                    renderShipments();
                }
                showToast(authorizing
                    ? `Dropi: ${success} autorizado(s), ${failed} erro(s)`
                    : `Dropi: ${success} enviado(s), ${manual} manual, ${failed} erro(s)`);
                state.dropiFilter = authorizing
                    ? (failed ? 'progress' : 'not_sent')
                    : (failed || manual ? 'progress' : 'sent');
                document.querySelectorAll('[data-dropi-filter]').forEach((item) => item.classList.toggle('active', item.dataset.dropiFilter === state.dropiFilter));
                await Promise.all([loadShipments(), loadChats()]);
            } finally {
                state.busy = false;
                renderShipments();
            }
        }

